-- Inserting report ID 29836
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support activities Lifeboat  Sea trial test', 'Mechanic', 'OTH', 'Completed', '2025-04-29', '<p>- Pre check Lifeboat before launching.</p><p>- Lifeboat launching.</p><p>- Deluge test.</p><p>- Full speed test.</p><p>&nbsp; <span style="background-color: rgb(255, 255, 255);">During sea trial test found finding as below</span></p><p><span style="background-color: rgb(0, 255, 0);"><b><u>No.1</u></b></span></p><p><span style="background-color: rgb(255, 255, 255);">&nbsp; </span><span style="background-color: rgb(255, 156, 0);">Found engine shutdown solenoid malfunction.</span></p><p><span style="background-color: rgb(0, 255, 0);"><u><b>No.2</b></u></span></p><p><span style="background-color: rgb(255, 255, 255);">&nbsp; </span><span style="background-color: rgb(255, 156, 0);">Found winch static brake not release.</span></p><p><span style="background-color: rgb(255, 255, 255);">&nbsp; </span><span style="background-color: rgb(255, 156, 0);">Found radio can not communicate.</span></p><p><span style="background-color: rgb(0, 255, 0);"><b><u>No.3</u></b></span></p><p><span style="background-color: rgb(255, 255, 255);">&nbsp; </span><span style="background-color: rgb(255, 156, 0);">Found electrical starting system not function. Fail to start with Main &amp; Emergency </span></p><p>&nbsp; <span style="background-color: rgb(255, 156, 0);">battery.</span> <span style="background-color: rgb(0, 255, 0);">(Engine running with manual starter)</span></p><p><span style="background-color: rgb(255, 255, 255);">&nbsp; </span><span style="background-color: rgb(255, 156, 0);">Engine stop during select forward &amp; backward due to low idle RPM&nbsp;</span></p><p>- Lifeboat recovery.</p><p>- Flush deluge system with portable water.</p><p>- Clean up Lifeboat &amp; working area.</p><p>Team <a href="member:Ruamlert"><font color="#000000">member: Ruamlert</font></a>&nbsp;P./Tawatchai P./Kawinwipart N./Aphai K.Pornthep K./Panot C./Kittipong S./Apinan I./Direk T./Warawoot N./Wachairagorn N.Thanakorn M.</p>', '<p>Completed report Link :&nbsp;<a href="https://pttep.sharepoint.com/:b:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/05.%20Report/52.%20Job%20Completed%20%20report/522.%20QPS%20Completed%20%20Report/Survival%20%26%20Fast%20Rescue%20Craft/Sea%20trial%20test%20report/20250430%202X-6902,%206903,%206904%20Lifeboat%20annual%20sea%20trial%20test%20report.pdf?csf=1&amp;web=1&amp;e=WuRXBR">20250430 2X-6902, 6903, 6904 Lifeboat annual sea trial test report.pdf</a></p><p>Photo Link :&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/6.%20Picture/62.%20QPS%20Equipment%20Picture/Survival%20and%20Fast%20Rescue%20Craft/2025%20Lifeboat%20sea%20trial%20test/20250429%202X-6902,%202X-6903,%202X-6904%20sea%20trial%20test?csf=1&amp;web=1&amp;e=72Pp4u" style="font-size: 15px;">20250429 2X-6902, 2X-6903, 2X-6904 sea trial test</a></p>', '2025-04-29 20:55:53', '2025-05-01 09:43:54', 'PTTEP\\ApinanI', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
