  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Metee', NULL, 'EXTERNAL', '2025-04-30 12:04:00', '2025-05-01 08:43:41', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Supv');
