  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'YPM Mercury (Hg) analyzer AIT-1681 (iLabFluid)', 'Instrument', 'CM', 'In Progress', '2025-04-30', '<p>YPM and CM Mercury (Hg) analyzer AIT-1681 (iLabFluid Vendor)</p><p>Consult manufacturer (MI-Mercury Instruments Germany), MI recommended T/S as following,&nbsp;&nbsp;</p><p>- Take Hg sample from MC-3000 (Mercury Calibrator) Detector2 Cal Gas Concentration 100 ug/m3 with Tedlar Bag for UT-3000 validate (Span Check), Syringe Inject into Cal Port by volume 10 ul, Abs still low.</p><p>- Validate with MC-3000 Det2 deliver Cal Gas Conc 100 ug/m3 to UT-3000 Set Sample Vol 0.01 L, Abs is higher than static check with syringe but Abs still lower than manufacurer recommended.</p><p>- Check Flow inside UT-3000 comprisist of Heating Flow, Sampling Flow and Cooling Flow), normal in require rate.</p><p>- Vendor will be verified Mercury Manual Calibation Box and consult manufacturer (MI-Mercury Instruments Germany) for next solution to improve more accurency.&nbsp;&nbsp;</p><p><br></p><p>Progress 90% of plan 100%&nbsp;</p><p><br></p><p>_/_/_/_/_/_/_/_/_/_/ Next Plan _/_/_/_/_/_/_/_/_/_/&nbsp;</p><p><br></p><p>- T/S (CM) Max-Absorbance is lower than Factory recommended.</p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F00%2DInstrument%2F04%20%2D%20Mercury%20Analyzer%5F1681%2F2025%20Report%2F20250425%2D30%5FYPM%5FHg%2DAnalyzer%5FiLabFluid&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250425-30_YPM_Hg-Analyzer_iLabFluid</a><br></p>', '2025-04-30 15:24:05', '2025-05-01 13:24:05', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
