  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist PFO2/NM-MM verify lifeboat after overhaul.', 'Electrical', 'OTH', 'Complete', '2025-05-01', '<p>Connect cable (16 sq.mm2) pole positive and negative from alternator for charging battery starter and radio as per drawing attach file.</p><p>&nbsp;- Voltage from alternator = 15.13 Vdc.</p><p>&nbsp;- load current = 3 A</p><p>&nbsp;- <span style="background-color: rgb(255, 255, 0);">Battery of starter bank#1</span> found low voltage = 5.55 Vdc, internal resistance = 0.66 ohm then replaced by new one, voltage = 12 Vdc, internal resistance = 4.7 mohm.</p><p>&nbsp; - Starting current = 24.7 A.</p><p>&nbsp; - Voltage charge = 14.91 Vdc, charging current = 9.8 A.&nbsp;</p><p>&nbsp;- <span style="background-color: rgb(255, 255, 0);">Battery of starter bank#2</span> voltage = 12.52 Vdc, internal resistance = 12.5 mohm.</p><p>&nbsp; - Starting current = 27.1 A.</p><p>&nbsp; - Voltage charge = 14.91 Vdc, charging current = 8.4 A.&nbsp;</p><p>&nbsp;- <span style="background-color: rgb(255, 255, 0);">Battery of radio </span>voltage = 12.38 Vdc, internal resistance = 13.7 mohm.</p><p>&nbsp;<span style="background-color: rgb(0, 255, 255);"> - No load waiting IT install radio.</span></p><p>&nbsp; - Voltage charge = 13.66 Vdc, charging current = 4 A.&nbsp;</p><p>- Turn on all lighting working normally.</p><p><br></p>', NULL, '2025-05-01 18:37:53', '2025-05-01 18:39:12', 'PTTEP\\Bongkot.EI-lead1', 'PTTEP\\Bongkot.EI-lead1', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-X-6900E', 'GBN-X-6900E', 'LIFEBOAT/DAVIT NO.5', NULL, NULL, 'LIFEBOAT/DAVIT NO.5', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
