-- Inserting report ID 29894
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify & T/S Valve Indicator Malfunction HOV-81704', 'Mechanic', 'CM', 'In Progress', '2025-05-01', '<p><u><b><br></b></u></p><p><u><b>Today Activity</b></u></p><p>Verify &amp; T/S Valve Indicator Malfunction HOV-81704.</p><p><br></p><p><u><b>01-May-2025</b></u></p><p>- Performed Function Test to check valve traveling status.</p><p>- Found the valve stem unable to drive the indicator stem.</p><p>- Removed the indicator and the cap to investigate the internal parts.</p><p>- Found no abnormality.</p><p>- Removed the metal sleeve and the rubber sleeve to investigate.</p><p>- Found that the indicator stem is stuck.</p><p>- Installed the indicator and the cap.</p><p><br></p><p><u><b>02-May-2025</b></u></p><p>- Found the valve stem unable to drive the indicator stem.</p><p>- Removed the indicator and the cap to investigate the internal parts.</p><p>- Drive the indicator stem with pipe wrench.</p><p>- Lubricated the indicator stem with WD-40.</p><p>- Spin exercise the indicator stem.</p><p>- Found that the indicator can be driven but still stuck.</p><p>- Installed the indicator and the cap.</p><p><br></p><p><b><u>03-May-2025</u></b></p><p>- Removed the indicator and the cap.</p><p>- Removed the valve positioner clusters and lock nut from the indicator stem.</p><p>- Removed the valve positioner switches in frame.</p><p>- Deisolation and depressurization.</p><p>- Disconnected the related tubing.</p><p>- Removed the valve indicator housing from the mounting.</p><p>- Removed the circlips on both end of the indicator stem.</p><p>- Removed the plastic washers.&nbsp;</p><p>- Removed the indicator stem by tapping with a mallet.</p><p>- Removed the lock pin in the indicator driven head.</p><p>- Cleaned the indicator stem and used sandpaper for smoothing.</p><p>- Lubricated the stem with universal grease.</p><p>- Inserted the indicator stem and spin the stem to check smooth performance.</p><p>- Inserted the washers and circlips on both ends.</p><p>- Installed the valve indicator housing to the mounting.</p><p>- Installed the valve positioner switches in frame.</p><p>- Installed the valve positioner clusters and lock nut from the indicator stem.</p><p>- Connected the tubing.</p><p>- Confirmed the valve status with CCR.</p><p>- Installed the indicator and the cap.</p><p>- Connected the rubber couplings.</p>', 'Comparing to HOV-81715, the indicator stem must be travelled by hand drive.', '2025-05-01 18:39:23', '2025-05-03 18:22:52', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HOV-81704', 'ATL-OC-HOV-81704', 'Valve 28" PG-81023 upstream of PL-8170', NULL, NULL, 'Valve 28" PG-81023 upstream of PL-8170', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Chan', NULL, 'EXTERNAL', '2025-05-01 18:39:23', '2025-05-03 18:22:52', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neymar', NULL, 'EXTERNAL', '2025-05-01 18:39:23', '2025-05-03 18:22:52', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec');
END $$;

