  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace Helium Gas Cylinder No.3 at OGC AIT-84307', 'Electrical & Instrument', 'CM ', 'Completed', '2025-05-02', '<p><b><u>Activity</u></b></p><p>Replaced Helium Gas Cylinder No.3 at OGC AIT-84307.</p><p><br></p><p><b><u>Action Plan</u></b></p><p>1.Inform to relevant party including MOGE Representative. Set AIT-84306 (In Used Auto to Manual ) and log the activity.</p><p>2.Replaced helium gas cylinder No.3 and perform leak test. No leak all connection of Helium Cylinder No.3.</p><p>3.Set <span style="background-color: rgb(255, 255, 0);">New Helium Gas Cylinder No.3 Outlet Pressure </span>is <span style="background-color: rgb(255, 255, 0);">110psig(Lag) </span>and <span style="background-color: rgb(255, 255, 0);">Helium Gas Cylinder No.4 Outlet</span> <span style="background-color: rgb(255, 255, 0);">Pressure</span> is <span style="background-color: rgb(255, 255, 0);">120psig(Lead).</span></p><p>4.After completion of Helium Cylinder Replacement Job, put back AIT-84306(In Used Manual to Auto) and log the activity.</p><p>5.Checked any alarm is activate or not at the GC/Metering HMI Computer and also checked the GC parameter value is stable or not. If no alarm, unit is back to normal.</p>', NULL, '2025-05-02 17:13:43', '2025-05-02 17:14:27', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-AIT-84307', 'ATL-MS-AIT-84307', 'Gas chromatograph to metering.N2and CO2', NULL, NULL, 'Gas chromatograph to metering.N2and CO2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2025-05-02 17:13:43', '2025-05-02 17:14:27', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Harry', NULL, 'EXTERNAL', '2025-05-02 17:13:43', '2025-05-02 17:14:27', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech');
