-- Inserting report ID 29948
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced deteriorate TR-65-302.', 'Electrical', 'CM', 'In Progress', '2025-05-03', '<p>- Remove old TR-65-302 and connect power cable existing transformer for temporary supply to load back to normal.</p><p>&nbsp; &nbsp; - Measure insulation before energizing power.</p><p>&nbsp; &nbsp; &nbsp; - Primary</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Insulation L1/E = 130 Gohm, L2/E = 130 Gohm, L3/E = 130 GMohm.</p><p>&nbsp; &nbsp; &nbsp;&nbsp;- Secondary&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Insulation L1/E = 108 Gohm, L2/E = 108 Gohm, L3/E = 108 Gohm.</p><p>&nbsp;- Insulation between Primary/Secondary = 203 Gohm&nbsp;<br></p><p><br></p><p>- Install new transformer for replaced will terminate power cable next day.</p><p>&nbsp; &nbsp; - Measure insulation and resistance.</p><p>&nbsp; &nbsp; &nbsp; - Primary </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Insulation L1/E = 490 Mohm, L2/E = 492 Mohm, L3/E = 497 Mohm. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Resistance L1/L2 = 20.5 mohm, L2/L3 = 20.46 mohm, L3/L1 = 20.45 mohm.  </p><p>&nbsp; &nbsp; &nbsp;&nbsp;- Secondary&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Insulation L1/E = 893 Mohm, L2/E = 883 Mohm, L3/E = 874 Mohm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Resistance L1/L2 = 4.76 mohm, L2/L3 = 4.72 mohm, L3/L1 = 4.78 mohm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Resistance L1/N = 2.36 mohm, L2/N = 2.35 mohm, L3/N = 2.39 mohm.<br></p><p>&nbsp;- Insulation between Primary/Secondary = 551 Mohm&nbsp;</p><p><br></p><p><br></p><p><br></p><p><br></p>', '<p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/QP/Replaced%20TR-65-302%20on%203-4%20May%202025?csf=1&amp;web=1&amp;e=pcPC2e">https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/QP/Replaced%20TR-65-302%20on%203-4%20May%202025?csf=1&amp;web=1&amp;e=pcPC2e</a><br></p>', '2025-05-03 18:09:22', '2025-05-03 18:11:47', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-lead2', false, 'G2N') RETURNING id INTO new_report_id;
