-- Inserting report ID 29976
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify & T/S Valve Indicator Malfunction HOV-81704', 'Electrical & Instrument', 'CM', 'Completed', '2025-05-04', '<p><u>Today Activity</u></p><p>Verify &amp; T/S Valve Indicator Malfunction HOV-81704.</p><p><u></u></p><p><u>Action</u></p><p>-Perform to Remove the indicator and the cap.</p><p>-Adjust limit switch to their place (open position and close position)</p><p>-Valve open/ close with CCR and operator&nbsp;</p><p>-Function test Ok</p><p>-Back in service&nbsp;</p><p><br></p><p><u>03</u><u>.05.25 Activity</u></p><p>Verify &amp; T/S Valve Indicator Malfunction HOV-81704.</p><p><br></p><p><u>Action</u></p><p>- Removed the indicator and the cap.</p><p>- Removed the valve positioner clusters and lock nut from the indicator stem.</p><p>- Removed the valve positioner switches in frame.</p><p>- Deisolation and depressurization.</p><p>- Disconnected the related tubing.</p><p>- Removed the valve indicator housing from the mounting.</p><p>- Removed the circlips on both end of the indicator stem.</p><p>- Removed the plastic washers.&nbsp;</p><p>- Removed the indicator stem by tapping with a mallet.</p><p>- Removed the lock pin in the indicator driven head.</p><p>- Cleaned the indicator stem and used sandpaper for smoothing.</p><p>- Lubricated the stem with universal grease.</p><p>- Inserted the indicator stem and spin the stem to check smooth performance.</p><p>- Inserted the washers and circlips on both ends.</p><p>- Installed the valve indicator housing to the mounting.</p><p>- Installed the valve positioner switches in frame.</p><p>- Installed the valve positioner clusters and lock nut from the indicator stem.</p><p>- Connected the tubing.</p><p>- Confirmed the valve status with CCR.</p><p>- Installed the indicator and the cap.</p><p>- Connected the rubber couplings.</p><p>-Perform to function test valve operate with operator tomorrow</p><p><br></p><p><u>02.05.25 Activity</u></p><p>Verify &amp; T/S Valve Indicator Malfunction HOV-81704.</p><p><br></p><p><u>Action</u></p><p>&nbsp;- Found the valve stem unable to drive the indicator stem.</p><p>- Removed the indicator and the cap to investigate the internal parts.</p><p>- Drive the indicator stem with pipe wrench.</p><p>- Lubricated the indicator stem with WD-40.</p><p>- Spin exercise the indicator stem.</p><p>- Found that the indicator can be driven but still stuck.</p>', NULL, '2025-05-04 10:22:48', '2025-09-11 11:29:38', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HOV-81704', 'ATL-OC-HOV-81704', 'Valve 28" PG-81023 upstream of PL-8170', NULL, NULL, 'Valve 28" PG-81023 upstream of PL-8170', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2025-05-04 10:22:48', '2025-09-11 11:29:38', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Mech-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neymar', NULL, 'EXTERNAL', '2025-05-04 10:22:48', '2025-09-11 11:29:38', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Mech-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2025-05-04 10:22:48', '2025-09-11 11:29:38', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Mech-Tec');
