-- Inserting report ID 29979
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '500586617 PM ME Closed Drain Sump Pump Unit 6M', 'Mechanic', 'PM', 'Completed', '2025-04-11', '<div>"Perform maintenance and inspection as follow:</div><div>&nbsp;1. Check foundation holding down bolts and tightening check.</div><div>&nbsp;2. Check for any leaks from gaskets and seals around the pump skid.</div><div>&nbsp;3. Replaced lip oil sealback and front.</div><div>&nbsp;3. Change lubes oil gear box. (PTT GEAR OIL EP 220 = 10 Liters)</div><div>&nbsp;4. Change oil in hydraulic oil chamber. ( PTT DYNAMIC SUPER COM 5W-40 = 10 Liters)</div><div>&nbsp;5. Remove suction strainer for inspection and cleaning.(5% clogged found)</div><div>&nbsp;6. Check discharge check valve for clog and damage.</div><div>&nbsp;7. Test run and data recording as follow.</div><div>&nbsp; &nbsp;- Running hour = 432 Hrs.</div><div>&nbsp; &nbsp;- Running current = N/A Amp.</div><div>&nbsp; &nbsp;- Discharge pressure PT-01504 = 1.393 BAR."</div><div><br></div>', NULL, '2025-05-04 11:22:31', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
