TTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-W-4910', 'ART-W-4910', 'WHRU - MAIN POWER GENERATION TURBINE 3', NULL, NULL, 'WHRU - MAIN POWER GENERATION TURBINE 3', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
