 INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-1865', 'ART-P-1865', 'CONDENSATE EXPORT PUMP', NULL, NULL, 'CONDENSATE EXPORT PUMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'CONCOR', NULL, 'EXTERNAL', '2025-05-04 12:47:04', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
