  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-W-4880', 'ART-W-4880', 'WHRU-SALE GAS COMPRESSION TURBINE TRN 2', NULL, NULL, 'WHRU-SALE GAS COMPRESSION TURBINE TRN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'CONCOR', NULL, 'EXTERNAL', '2025-05-04 15:28:30', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
