  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-4580', 'ART-P-4580', 'SUMP TANK PUMP', NULL, NULL, 'SUMP TANK PUMP', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
