  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM 18CR-7003 Perform 6MPM', 'Mechanic', 'PM', 'In Progress', '2025-04-27', '<p>Opened work permit, toolbox talk and prepared hand tools to start work.</p>  <p>- General checked on control station, power pack.</p>  <p>- Checked all pressure gauges, control valves, any leakage of hoses and fittings.</p>  <p>- Checked hydraulic oil level. (OK.)</p>  <p>- Checked diesel oil level. (OK.) and found oil leak at sight glass.</p>  <p>- Checked engine coolant level. (OK.)</p>  <p>- Checked engine fan belt. (OK.)</p>  <p>- Checked hydraulic oil for engine throttle and dynamic slew brake. (Proper level) </p>  <p>- Changed engine lube oil. (15W-40 = 18 liters)</p>  <p>- Replaced 2 ea. fuel filters. (CAT 435-6493)</p>  <p>- Replaced engine lube oil filter. (CAT 462-1171)</p>  <p>- Replaced fuel/water separator filter. (CAT 441-5111) </p>  <p>- Replaced crankcase breather filter. (CAT 2735711)&nbsp; </p>  <p>- Replaced 2 ea. hydraulic return filters. (Donaldson P-165675)</p>  <p>- Replaced air engine filter primary. (CAT 2892348)</p>  <p>- Replaced air engine filter secondary. (CAT 2892349)</p>  <p>- Changed slew gear oil (PTT 220 = 6 liters)</p>  <p>- Lubricate slew ring gear.</p>  <p>- Removed hydraulic starter for inspect pinion gear and flywheel gear condition. (Good condition) </p>  <p>- Fix leak sight glass of diesel tank.</p>  <p>- Housekeeping and cleaned up working area.&nbsp; &nbsp;&nbsp;</p>', NULL, '2025-05-04 17:15:58', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Youngyuth K.', NULL, 'EXTERNAL', '2025-05-04 17:15:58', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL);
