  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2LIT-33103 and 2LIT-33102 reading difference ', 'Instrument', 'CM', 'Completed', '2025-05-05', '<p>The trasmitter reading difference more due to 2LIT-32103 diaphram defective (not response).</p><p><i><b>&nbsp;Befor start job :</b></i></p><p>&nbsp; &nbsp; - The sigh glass show 60% , <span style="background-color: rgb(255, 255, 0);">2LIT-33102 = 61% (SG=0.74) , 2LIT-33103 = 42% (SG=0.74).</span></p><p>&nbsp; &nbsp; - Then perform flushing sigh glass and show 26%.</p><p>&nbsp; Replace transmitter 2LIT-33103 by new spare and calibration.</p><p>&nbsp; &nbsp; - Change SG from 0.74 to 0.9 (Discuss with CCR, Mike,Bird,Tor)</p><p>&nbsp; &nbsp; - SG 0.9 come from lab analyze by (Ton).</p><p>Process back to normal and reading below :</p><p>&nbsp; &nbsp; - The sigh glass reading 26 %.</p><p>&nbsp; &nbsp; - 2LIT-33102 change SG = 0.9 <span style="background-color: rgb(255, 255, 0);">(re-range URV= -68, LRV = -1148)</span> reading = 28.5%</p><p>&nbsp; &nbsp; - 2LIT-33103 set SG = 0.9 , <span style="background-color: rgb(255, 255, 0);">URV= -68, LRV= -1148</span>&nbsp; reading 28.1%</p><p>Remark : Torque 339 Nm, wrench# 36, RTJ# 3"/900.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : <span style="background-color: rgb(255, 231, 206);">For 2LIT-33102 to be force value at Mark-VIe because effect to TC trip.</span></p><p><br></p><p><br></p><p><br></p>', NULL, '2025-05-05 16:05:22', '2025-05-07 20:21:52', 'PTTEP\\PongsakR', 'PTTEP\\PongsakR', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2LIT-33102', 'GBS-2LIT-33102', 'LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2LIT-33103', 'GBS-2LIT-33103', 'LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
