-- Inserting report ID 30238
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify & T/S  HOV-81715 ', 'Electrical & Instrument', 'CM', 'In Progress', '2025-05-05', '<div><b><u>Today Activity</u></b></div><div><p>Verify &amp; T/S&nbsp; HOV-81715&nbsp;</p><p><br></p><p><b><u>Action</u></b></p><p><br></p><p>-Perform to operate valve from CCR command, Valve doesn''t move open and close properly</p><p>-Found Local/remote selector switch doesn''t work properly, need to replace with new</p><p>-Perform to check&nbsp; PDI 81001 fuse ( terminal block - 51, 52 ) ( fuse is Ok )</p><p>-Check surge protection SPDDI26-13 ( OK )</p><p>-Perform to check PDO-81001 fuse ( terminal block - 9, 10 )&nbsp; (fuse is&nbsp; OK )</p><p>-Check surge protection SPDDO31-5 ( OK )</p><p>-Perform to PDO-81001 fuse ( terminal block - 11, 12 ) ( OK )</p><p>-Check surge protection SPDDO 31-6 ( OK )</p><p>- Check Open solenoid relay RED031-5 ( OK )</p><p>-Check close solenoid relay RED031-6 ( OK )</p><p>- Found CCR command to valve open , energize valve close relay RED031-6&nbsp;</p><p>-Found CCR command to valve close, energize valve open relay RED031-5</p><p>-Need to check the system logic&nbsp;&nbsp;</p><p>-continue to check and troubleshoot&nbsp;</p><p><br></p><p><u>29.4.25 Activity</u></p><p>Replace defective solenoid at HOV81715 open side.</p><p><br></p><p><u>Activity</u></p><p>Process isolation done by OPT.</p><p>Remove Cover from HOV after CPI done.</p><p>Check the voltage (0VDC).</p><p>Check the resistance of defective solenoid. ( OL)</p><p>Remove defective solenoid cable from terminal block.</p><p>Remove tubing from defective solenoid.</p><p>Remove defective solenoid from HOV.</p><p>Install new solenoid and install back tubing. (63.5Ohm)</p><p>Reconnect cable termination at JB.</p><p>Recover the HOV cover.</p><p><br></p><p>Note: Function test and leak test not yet completed due to OPT not ready yet.</p><p><br></p></div>', NULL, '2025-05-05 18:14:42', '2025-05-06 13:49:17', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HOV-81715', 'ATL-OC-HOV-81715', 'HOV at Outlet from ZOC to PLC', NULL, NULL, 'HOV at Outlet from ZOC to PLC', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2025-05-05 18:14:42', '2025-05-06 13:49:17', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2025-05-05 18:14:42', '2025-05-06 13:49:17', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
