  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace defective thyristor V1, V5 and V6.', 'Electrical', 'CM', 'Complete', '2025-05-05', '<p>Replaced defective thyristor V1, V5 and V6.</p><p>&nbsp;- Replaced Thyristor 2V1, 2V5 and 2V6 by new spare SEMIKRON model SKT 300/12E.</p><p><span style="background-color: rgb(255, 255, 0);">2V1</span></p><p>&nbsp;- <u>Existing 2V1</u> resistance G1/G2 = 10.9 Ohm, <u>New 2V1</u> G1/G2 = 7.2 Ohm.</p><p>&nbsp;- <u>Existing 2V1</u> resistance A+/K- = 1.743 K. Ohm, <u>New 2V1</u> A+/K- = 11.88 M. Ohm.</p><p>&nbsp;- <u>Existing 2V1</u> Diode A+/K- = 0.986 V, <u>New 2V1</u> A+/K- = OL.</p><p><span style="background-color: rgb(255, 255, 0);">2V5</span></p><p>&nbsp;-&nbsp;<u>Existing 2V1</u>&nbsp;resistance G1/G2 = 11.11 Ohm,&nbsp;<u>New 2V1</u>&nbsp;G1/G2 = 6.8 Ohm.</p><p>&nbsp;-&nbsp;<u>Existing 2V1</u>&nbsp;resistance A+/K- = 1.338 K. Ohm,&nbsp;<u>New 2V1</u>&nbsp;A+/K- = 12.55 M. Ohm.</p><p>&nbsp;-&nbsp;<u>Existing 2V1</u>&nbsp;Diode A+/K- = 0.824 V,&nbsp;<u>New 2V1</u>&nbsp;A+/K- = OL.</p><p><span style="background-color: rgb(255, 255, 0);">2V6</span>
<br class="Apple-interchange-newline"></p><p>&nbsp;-&nbsp;<u>Existing 2V1</u>&nbsp;resistance G1/G2 = 10.5 Ohm,&nbsp;<u>New 2V1</u>&nbsp;G1/G2 = 7.0 Ohm.</p><p>&nbsp;-&nbsp;<u>Existing 2V1</u>&nbsp;resistance A+/K- = 1.642 K. Ohm,&nbsp;<u>New 2V1</u>&nbsp;A+/K- = 8.94 M. Ohm.</p><p>&nbsp;-&nbsp;<u>Existing 2V1</u>&nbsp;Diode A+/K- = 0.933 V,&nbsp;<u>New 2V1</u>&nbsp;A+/K- = OL.</p><p><br></p><p>After replacing defective thyristor then restart up battery charger and checked voltage ripple = O Vac.</p><p><br></p>', NULL, '2025-05-05 18:40:35', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-lead2', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-BC-65-301B', 'GBN-BC-65-301B', 'BC 48 VDC FOR EL CTRL AND PA', NULL, NULL, 'BC 48 VDC FOR EL CTRL AND PA', 'GBN-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
