  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TC#2 Synth oil filter 2F-3291 change over.', 'Instrument', 'CM', 'Completed', '2025-05-06', '<p data-start="95" data-end="168">Support Mech Turbine Team – Synth Oil Filter Changeover (2F-3291)</p><p data-start="170" data-end="351">Provided support mechanical turbine team for changeover of the synthetic oil filter 2F-3291 from Filter B to Filter A due to high differential pressure (DP) observed.</p><p data-start="170" data-end="351"><br></p><ul data-start="353" data-end="555"> <li data-start="353" data-end="473"> <p data-start="355" data-end="379"><u>Before changeover:</u></p> <ul data-start="382" data-end="473"> <li data-start="382" data-end="436"> <p data-start="384" data-end="436">Differential Pressure (PDIT-322981) = 1.37 bar&nbsp;(High alarm threshold = 1.5 bar)</p><p data-start="384" data-end="436"><br></p></li> </ul> </li> <li data-start="475" data-end="555"> <p data-start="477" data-end="500"><u>After changeover:</u></p> <ul data-start="503" data-end="555"> <li data-start="503" data-end="555"> <p data-start="505" data-end="555">Differential Pressure (PDIT-322981) = 0.81 bar</p> </li> </ul> </li> </ul><p>   </p><p data-start="557" data-end="636">Changeover successfully reduced DP.</p><p data-start="557" data-end="636"><br></p><p data-start="557" data-end="636">Replaced filter element on <strong data-start="550" data-end="562">Filter B.</strong></p><p><br></p>', NULL, '2025-05-06 14:38:43', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2F-3291', 'GBS-2F-3291', 'LUBE OIL DUPLEX FILTER PACKAGE', NULL, NULL, 'LUBE OIL DUPLEX FILTER PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
