  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2X-6904 Trouble shooting engine over heat.', 'Mechanic', 'CM', 'Completed', '2025-05-06', '<p><u>2X-6904 Trouble shooting engine over heat and idle speed stop.</u></p><p>-Pre check and run test for 45 min, found engine continue generated heat up to 95°C and stop at idle speed.</p><p>-Close check cooling water condition, found dirty and lower cooling performance as it should be. the control thermostat working normal to open(about 75°C)</p><p>-Let engine to cool down flush and change engine cooling water with fresh coolant liquid.</p><p>-Test run for 45 min with the same condition as before, found engine generated heat to steady temperature 85°C max. and engine kept running with no sign of idle speed stop.&nbsp;</p><p><br></p>', NULL, '2025-05-06 18:20:02', '2025-05-06 18:25:01', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
