  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM 2X-1406 CRANW WPS4 1YPM and 5YPM', 'Mechanic', 'PM', 'In Progress', '2025-05-05', '<p>- Travel from QPS to WPS-04.</p>  <p>- Toolbox talk.</p>  <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>1YPM.</b><b></b></p>  <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>Engine.</b></p>  <p>- Replaced fuel filter.</p>  <p>- Replaced generator filter.</p>  <p>- Replaced hydraulic return filter.</p>  <p>- Replaced high pressure filter of star system.</p>  <p>- Check pinion drive of motor starter. (85%)</p>  <p>- Top up new diesel fuel to tank approximate 90% of tank.</p>  <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>5Y, Braden winch replacement.</b></p>  <p>- Overhaul main winch by.</p>  <p>- NDT check crack internal part and drum.</p>  <p>- Replaced bearing, oil seal, sprag clutch and brake valve.</p>  <p>- Overhaul brake disc by replaced friction/steel disc, pressure spring and seal kit.</p>  <p>- Brake test with pressure 1,000 psi stand for 5 minutes.</p>  <p>- Assembly main winch.</p>  <p>- Housekeeping.</p>', NULL, '2025-05-06 19:02:13', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
