-- Inserting report ID 30333
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform to check and pressure test shuttle valve ', 'Electrical & Instrument', 'CM', 'In Progress', '2025-05-07', '<p><u>Today Activity</u></p><p>Perform to check and pressure test shuttle valve at ESDV 81717</p><p><u>Action</u></p><p>Reinstall some assembly and fitting for new shuttle valve&nbsp;</p><p>Reconnect back shuttle valve and assembly at ESDV 81717</p><p>Pressure test shuttle valve at local ESDV 81717</p><p>Reach 50 bar , start to leak at shuttle valve seat fitting</p><p>Disconnect shuttle valve and assembly to workshop&nbsp;</p><p>continue&nbsp;</p><p><br></p><p><u>6.5.25 activity</u></p><p>Perform to check and pressure test shuttle valve at workshop</p><p><u>Action</u></p><p>(1)-Install swagelok tubing for pressure test shuttle valve&nbsp;</p><p>&nbsp; &nbsp; -Replace Oring for Used shuttle valve body</p><p>&nbsp; &nbsp; -pressure test 12 Bar&nbsp;</p><p>&nbsp; &nbsp; -Leak at shuttle valve seat fitting</p><p>&nbsp; &nbsp; -Remove tubing again</p><p>(2)&nbsp; &nbsp;-Use old shuttle valve seat fitting&nbsp; and Used shuttle valve body</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Pressure test 12 bar</p><p>&nbsp; &nbsp; &nbsp; &nbsp; -Leak cheak and pressure test ok at 12 bar</p><p>(3) Take new shuttle valve at warehouse</p><p>&nbsp; &nbsp; &nbsp; Pressure test 12 Bar&nbsp;</p><p>&nbsp; &nbsp; &nbsp; Leak check and pressure test ok at 12 bar</p><p>&nbsp;</p><p><br></p><p><u>5.5.25&nbsp; Activity</u></p><p>Perform to check valve leak and tighten at ESDV 81717</p><p><u>Action</u></p><p>check leak point shuttle valve with operator&nbsp;</p><p>Remove shuttle valve from ESDV 81717</p><p>Take shuttle valve to workshop&nbsp;</p><p>Check shuttle valve assembly&nbsp; at workshop</p>', NULL, '2025-05-07 16:42:56', '2025-05-07 18:11:43', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
