  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2025-05-07 16:42:56', '2025-05-07 18:11:43', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'MSO', NULL, 'EXTERNAL', '2025-05-07 16:42:56', '2025-05-07 18:11:43', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
