  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'HVAC A-8300 unit B1 Oil compressor low pressure.', 'Electrical', 'CM', 'In Progress', '2025-05-07', '<p>T/S HVAC A-8300 (CM-8410) unit B1 Oil compressor low pressure.</p><p>-Finding leak point of oil compressor line.</p><p>- Found leak point at ORV 1/4 copper tube leak. </p><p>- Block refrigerant line and bleed off until 0 psi. So replace new one and install isolation valve at oil separator.</p><p>- Re-fill oil compressor about 9 litle.</p><p>- Vacuum system ultil -30 In.hg. after that keep for monitor 30 minuit not build up pressure.</p><p>- Line up and re fill refrigerant R-134a about 30 kg.</p><p>- Running system and keep monitoring.</p><p>&nbsp;&nbsp;&nbsp;<br></p>', NULL, '2025-05-07 18:18:10', '2025-05-07 18:37:42', 'PTTEP\\MeechaiD', 'PTTEP\\MeechaiD', false, 'ART') RETURNING id INTO new_report_id;
