  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 6MPM G8935', 'Electrical & Instrument', 'PM', 'Completed', '2025-05-09', '<h3 class="modal-title displayform"><p><u>Today Activity</u></p><p>Perform 6MPM G8935</p><p><br></p><p><u>Action</u>&nbsp;</p><p>-Inhibit FM200</p><p>-Remove solenoid from FM200</p><p>-Turn to selector switch off position G-8935</p><p>-Local self breaker off inside generator control panel</p><p>-Electrical isolation G-8935 Q14 and Q19</p><p>-check battery condition and battery water level ( Fill 0.5 liter )</p><p>-Measure battery voltage 25.3V</p><p>-Check FM200 panel&nbsp;</p><p>-Visual check and tightened connection at FM200 panel</p><p>-Check&nbsp; KCP panel , look for signs of overheating, deterioration of insulation and loose connection.</p><p>-Visual check and tightened connection at KCP Panel</p><p>-Check alternator winding temperature panel, look for sings of overheating, deterioration of insulation and loose connection.</p><p>-Visual check and tightened connection at Alternator winding temperature panel.</p><p>-Visual check PMG (OK)</p><p>-Visual check alternator (OK)</p><p>-Check starter motor connection and condition(OK)</p><p>-Check generator housing lamps (OK)</p><p>-Inspect the condition of cable gland, cabling and tray work</p><p>-Check Air Circuit breaker&nbsp;</p><p>-Check ACB control wiring&nbsp;</p><p>-Follow G-8935 Preventive maintenance Job card step by step</p><p>-Reconnect solenoid at FM200</p><p>-De-Isolation step by step&nbsp;</p><p>-Test Run with load ( OK )</p><p>-Stop G8935&nbsp;</p><p>-Back to Auto and Stand By Position</p><p><br></p><p><br></p><p><br></p><div><br></div></h3>', NULL, '2025-05-09 18:15:52', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8935-PACK', 'ATL-OC-G-8935-PACK', 'Gen, ZOC Diesel Generator Package', NULL, NULL, 'Gen, ZOC Diesel Generator Package', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2025-05-09 18:15:52', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'MSO', NULL, 'EXTERNAL', '2025-05-09 18:15:52', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL);
