-- Inserting report ID 30436
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Elect Isolation and Deisolation  G8935 for Mech', 'Electrical & Instrument', 'OTH', 'Completed', '2025-05-10', '<h3 class="modal-title displayform"><p><u>Today Activity</u></p><p>Electrical Isolation and Deisolation&nbsp; G8935 for Mech PM</p><p><br></p><p><u>Action</u>&nbsp;</p><p>-Inhibit FM200</p><p>-Remove solenoid from FM200</p><p>-Turn to selector switch off position G-8935</p><p>-Local self breaker off inside generator control panel</p><p>-Electrical isolation G-8935 Q14 and Q19</p><p>-After Mech PM</p><p>-Reconnect solenoid at FM200</p></h3><h3 class="modal-title displayform"><p>-De-Isolation step by step&nbsp;</p><p>-Test Run with load ( OK )</p><p>-Stop G8935&nbsp;</p><p>-Back to Auto and Stand By Position</p><p><br></p></h3>', NULL, '2025-05-10 17:22:32', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
