-- Inserting report ID 30439
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2UCP-34600 Condensate Auto Sampler – Sample No', 'Instrument', 'CM', 'Completed', '2025-05-10', '<p data-start="65" data-end="130" class=""><strong data-start="65" data-end="130">T/S 2UCP-34600 Condensate Auto Sampler – Sample Not Collected</strong></p> <p data-start="132" data-end="208" class=""><strong data-start="132" data-end="142">Issue:</strong><br data-start="142" data-end="145"> The condensate auto-sampler failed to properly collect samples.</p> <p data-start="210" data-end="408" class=""><strong data-start="210" data-end="223">Findings:</strong><br data-start="223" data-end="226"> The Welker probe regulator was not functioning as expected, potentially leading to the sampling issue. Upon inspection, the O-ring on the D-head of the probe was found to be damaged.</p> <p data-start="410" data-end="430" class=""><strong data-start="410" data-end="428">Actions Taken:</strong></p> <ul data-start="431" data-end="657"> <li data-start="431" data-end="480" class=""> <p data-start="433" data-end="480" class="">Disassembled the Welker probe for inspection.</p> </li> <li data-start="481" data-end="559" class=""> <p data-start="483" data-end="559" class="">Identified and replaced the damaged O-ring on the D-head with a new spare.</p> </li> <li data-start="560" data-end="657" class=""> <p data-start="562" data-end="657" class="">Performed a functional test; the sampler is now working correctly and collecting 4 cc per grab.</p> </li> </ul> <p data-start="659" data-end="752" class=""><strong data-start="659" data-end="674">Next Steps:</strong><br data-start="674" data-end="677"> Continue monitoring the system to ensure consistent and reliable operation.</p>', NULL, '2025-05-10 17:34:59', '2025-05-10 17:38:18', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-3992', 'GBS-2X-3992', 'AUTO SAMPLING SYSTEM', NULL, NULL, 'AUTO SAMPLING SYSTEM', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-05-10 17:34:59', '2025-05-10 17:38:18', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
