-- Inserting report ID 30455
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM 2HV-19E04 Choke Valve WPS-9 Verify liquid leak ', 'Mechanic', 'CM', 'Completed', '2025-05-10', '<p align="left">-&nbsp; &nbsp;Process isolation by production team. </p>  <p align="left">-&nbsp; &nbsp;Close hydraulic valve to hydraulic actuator and release pressure tap.</p>  <p align="left">-&nbsp; &nbsp;Remove instrument module.</p>  <p align="left">-&nbsp; &nbsp;Remove all hydraulic actuator FC-2 part.</p>  <p align="left">-&nbsp; &nbsp;Remove bonnet from valve body, loosen bolt 12 point hex cap screw 7/8”</p>  <p align="left">-&nbsp; &nbsp;Check sealing surface on flow ring found sealing surface damaged.</p>  <p align="left">-&nbsp; &nbsp;Inspect sealing surface in valve body for pitting and scratches.</p>  <p align="left">-&nbsp; &nbsp;Inspect Teflon seal at position Body-balance sleeve, seal is pressed and level with balance sleeve&nbsp; &nbsp; &nbsp; &nbsp;surface.</p>  <p align="left">-&nbsp; &nbsp;Remove retainer sleeve, Seal: Body-balance sleeve and Back up ring: Body-balance sleeve.</p>  <p align="left">-&nbsp; &nbsp;Loosen flow ring with balance sleeve to remove Seal: Bonnet- balance sleeve.</p>  <p align="left">-&nbsp; &nbsp;Remove seal: Seat-Body on seat part.</p>  <p align="left">-&nbsp; &nbsp;Assembly new spare part as per manual.</p>  <p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Master flow: Model P3E with Double acting linear hydraulic actuator FC-2<u></u></p>  <p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <u>Key#Piston/FC2 Actuator Ref. Dwg A30-000-K061</u></p>  <p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <u>Seal material (TEFLON) Dash no. -003</u></p>  <p align="left">-&nbsp; &nbsp;Replace new seal: Bonnet- balance sleeve.</p>  <p align="left">-&nbsp; &nbsp;Replace new lock washer and apply thread locker 263 on stud.</p>  <p align="left">-&nbsp; &nbsp;Re-tighten flow ring and balance sleeve into stud.</p>  <p align="left">-&nbsp; &nbsp;Replace new seal: Body-balance sleeve and back up ring: Body-balance sleeve on balance sleeve.</p>  <p align="left">&nbsp; &nbsp;Replace seat-body on seat part.</p>  <p align="left">-&nbsp; &nbsp;Install seat in valve body on outlet port, direct hole to the inlet port.</p>  <p align="left">-&nbsp; &nbsp;Install bonnet into valve body, Hex cap screw 7/8”, apply torque 163 ft-lb (221 NM)</p>  <p align="left">-&nbsp; &nbsp;Install hydraulic actuator FC-2 and calibrate by PBS/MEI</p>  <p align="left">-&nbsp; &nbsp;Leak test valve body and bonnet, not found any leak.</p>  Passing test, fully closed choke valve, not passing', NULL, '2025-05-10 18:54:32', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2HV-19E04', 'GBS-2HV-19E04', 'Valve Choke WH09E to Prod and Test Man', NULL, NULL, 'Valve Choke WH09E to Prod and Test Man', 'GBS-WP09', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Direk T.', NULL, 'EXTERNAL', '2025-05-10 18:54:32', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surachai J.', NULL, 'EXTERNAL', '2025-05-10 18:54:32', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL);
