-- Inserting report ID 30528
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform to function test with new Comp-A G8935', 'Electrical & Instrument', 'OTH', 'In Progress', '2025-05-11', '<div><u>Today''s Activity</u></div><div><p>Perform to function test with new Comp-A generator controller at G-8935</p><p><br></p><p><u>Action</u></p><p>-Selector switch turn to off position and isolate breaker inside the generator control panel</p><p>-Disconnect connection at CompA Controller for replace new comp A</p><p>-Perform to replace with new Comp A controller</p><p>-Connect electrical connection to new CompA</p><p>-Switch on breaker</p><p>-Check configure and set point for new CompA Controller</p><p>-Start to test run by manual with new CompA Controller</p><p>-Running normal</p><p>-Start to command breaker close, ACB breaker close at that time load couldn''t pick up and couldn''t share load.</p><p>-it can happen reverse power&nbsp;</p><p>-Initiate breaker open, stop the engine and check again CompA controller</p><p>-Upload Comp A files from old unit&nbsp;</p><p>-Download Comp A files to new unit&nbsp;</p><p>-Reconnect connection for new CompA for test run</p><p>-Initiate breaker close</p><p>-It happen again as like reverse power, it that time show the screen PF- 0.3, Active power -&nbsp; -25KW</p><p>-Breaker open and stop the engine.</p><p>-Replace with old unit CompA , test run again</p><p>-Running OK , share load ok</p><p>-Let it standby and auto position</p><p>-troubleshoot new CompA controller unit</p><p><br></p><p>&nbsp;</p><p><br></p><p><br></p><p><br></p></div>', NULL, '2025-05-12 09:03:44', '2025-05-12 09:04:01', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
