-- Inserting report ID 30588
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C) Verification of 2FIT-11209A – Flow Transmitter', 'Instrument', 'CM', 'Completed', '2025-05-13', '<div>Verification of 2FIT-11209A – Flow Transmitter Zero Reading Issue</div><div>- As-found reading of 2FIT-11209A was approximately 0.1 MMSCFD while the test separator was not in operation,&nbsp;</div><div>- Isolation for Calibration: Performed block-in of both upstream and downstream valves to isolate the transmitter for zero calibration.</div><div>- Calibrated the transmitter with no actual flow conditions.</div><div>After calibration, the reading initially dropped to ~0.08 MMSCFD, but gradually increased to ~0.3 MMSCFD, indicating an unstable zero</div><div>- Mass Flow Cutoff Adjustment: Attempted to suppress low false readings by adjusting the mass flow cutoff parameter from 0.00019 MMSCFD to 0.3 MMSCFD. After this adjustment, the transmitter briefly showed 0.0 MMSCFD, but shortly after, readings began to rise again to ~0.3–0.4 MMSCFD, even with no process flow.</div><div><br></div><div>Current Status: </div><div>Transmitter continues&nbsp;unstable zero, Issue remains unresolved and further action is required.</div>', NULL, '2025-05-13 17:16:20', '2025-05-18 07:41:09', 'PTTEP\\PooritadT', 'PTTEP\\GBS.Electrical-TMLD', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2FIT-11209A', 'GBS-2FIT-11209A', 'COLIORIS FLOW TRANSMITTER', NULL, NULL, 'COLIORIS FLOW TRANSMITTER', 'GBS-WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-05-13 17:16:20', '2025-05-18 07:41:09', 'PTTEP\\PooritadT', 'PTTEP\\GBS.Electrical-TMLD');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'MeteeT', NULL, 'EXTERNAL', '2025-05-13 17:16:20', '2025-05-18 07:41:09', 'PTTEP\\PooritadT', 'PTTEP\\GBS.Electrical-TMLD');
END $$;

