  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '3MPM IN OGC Analyzer AIT-1450 (UOP Permeated CO2)', 'Instrument', 'PM', 'In Progress', '2025-05-14', '<p>3MPM IN OGC Analyzer AIT-1450 (UOP Permeated CO2)</p><p>- <font color="#0000ff">Collected Baseline</font> after run analyzer overnight, Baseline is good.</p><p><font color="#0000ff">- Found calibration result is out of tolerance</font> (RF +/- 2 and RT +/-0.5) and Final-Cal Chromatogram (CGM) peaks shift out from recently, suspected flow at 6-port Valve3 is reduced, then sent Chromatogram (CGM) to K.Teerapat B. (PDD/S) for consultance.</p><p></p><p><br></p><p>- Check Measurement Vent Flow which found MV in 2 state are deviated over 2 ml/min by </p><p>V3 On = 15.3 ml/min and V3 Off = 11.9 ml/min.</p><p>- Found pressure seeping at port1 of 6-port Valve, then re-tighten fitting (1/16").</p><p>&nbsp; &nbsp;<br></p><p><br></p><p><font color="#0000ff">- Verified flow at 6-port valve3 </font>one by one port which found inlet flow at port4 is 50 ml/min but outlet flow at port1 is differance between both state by V3 Energized is 22 ml/min but V3 De-energized is 12 ml/min.</p><p>- Found Restriction Column (R1) which connected between port3 to port2 is clogged, then flushing R1 (1/16" OD) and install back to V3. Flow throught V3 is increased to 24 ml/min for both state (V3 On and Off)</p><p>- Measure MV that found flow is increased to 17.7 ml/min for both state (V3 On and Off) as normal condition.</p><p>&nbsp; &nbsp;</p><p><br></p><p><font color="#ff0000">- Calibration inprogress.</font></p><p><br></p><p>- Found Solenoid valve of Stream Switching valve S1 (SL-1, TB4-51/52) malfuction. waiting for spare part.</p><p>SOV: ASCO Model EF8016G2, 110VAC/11W, MESC: 60.50.50.105.3</p><p>&nbsp; &nbsp;<br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FAnalyzer%5FOGC%5FGasCylinder%2FAIT%2D1450%5FCG%5FUOP%2DDCS%2F20250514%5FTS%20Cal%5FLowFlow&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250514_TS Cal_LowFlow</a><br></p>', '2025-05-14 13:50:06', '2025-05-15 18:34:44', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-AIT-1450', 'ART-AIT-1450', 'ANALYSIS TRANSMITTER(UOP C6 GC)', NULL, NULL, 'ANALYSIS TRANSMITTER(UOP C6 GC)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Winyoo N.', NULL, 'EXTERNAL', '2025-05-14 13:50:06', '2025-05-15 18:34:44', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
