  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify a root cause unexpected Shutdown.', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2025-05-13', '<p>T/S Platform shutdown ESD-1 due to unknown reason. </p><p>- Discovered the control net card of node 8 was fault time to time.</p><p>- Verified power supply 24 Vdc to PLC&nbsp; have grounding at negative. ( - / G = 0.0 Vdc )&nbsp;</p><p>- The HP2 pump have low performance and can''t build up pressure.</p><p>&nbsp; </p><p>Action:</p><p>- Replaced new the control net card, result is satisfied.</p><p>- Found that power supply negative grounding at RIO-10201,RIO-10204,RIO-10205 and RIO-10206. To be&nbsp; &nbsp; &nbsp;verfy again.</p><p>- The HP2 pump has been overhauled and functional test, result is satistify.&nbsp;</p><p>- Restart up platform that is normal operate, Under monitoring.</p>', NULL, '2025-05-14 16:12:10', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
