-- Inserting report ID 30741
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'X-6900E Perform Maintenances winch gear YPM ', 'Mechanic', 'PM', 'Complete', '2025-05-16', '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<b>X-6900E Perform Maintenances winch gear YPM&nbsp;</b></p><p>1. Replaced lube oil winch gear. (PTT hydraulic 32) Non drive end side 6 L, Drive end side 12 L.</p><p>2. Checked and inspected sprocket and chain drive were normal.<u></u></p><p>3. Inspected and cleaning the internal parts of winch brake were good conditions.<u></u></p><p>4. Measuring brake thickness. (Drum brake @ = 5 mm.), (Governor Brake @ = 8 mm.)<u></u></p><p>5. Functional tested of winch manual brake both direction and remote control was normal operation.<u></u></p><p>6. Lubricate wire rope and greased all greasing points.<u></u></p><p>7. Inspected all rotating parts and lubricate all roller wheels.</p><p><br></p>', NULL, '2025-05-17 08:40:03', '2025-05-17 08:41:29', 'PTTEP\\Mech_WS', 'PTTEP\\Mech_WS', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-X-6900E', 'GBN-X-6900E', 'LIFEBOAT/DAVIT NO.5', NULL, NULL, 'LIFEBOAT/DAVIT NO.5', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
