-- Inserting report ID 30747
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'QP:  T/S lifeboat no.2 could not be stopped by ele', 'Electrical', 'CM', 'Complete', '2025-05-17', '<div>T/S lifeboat no.2 (X-6900B) could not be stopped by electric mode.</div><div> <ul data-start="234" data-end="421"> <li data-start="234" data-end="315" class=""> <p data-start="236" data-end="315" class="">&nbsp; &nbsp; - The fuel shut-off solenoid was found to be malfunctioning in the pull status.</p> </li> <li data-start="316" data-end="421" class=""> <p data-start="318" data-end="421" class="">&nbsp; &nbsp; - The faulty solenoid was replaced with a hot spare, and the system was tested with satisfactory results.</p><p data-start="318" data-end="421" class="">&nbsp; &nbsp; - The system is now fully functional after replacement and testing.<br></p> </li> </ul> <p data-start="423" data-end="454" class=""><strong data-start="423" data-end="454"><br></strong></p><p data-start="423" data-end="454" class="">Test Results for Hot Spare:</p> <ul data-start="455" data-end="698"> <li data-start="455" data-end="505" class=""> <p data-start="457" data-end="505" class="">Fuel Shut-off Solenoid Resistance: 0.5 ohm</p> </li> <li data-start="506" data-end="567" class=""> <p data-start="508" data-end="567" class="">Insulation Resistance (IR): &gt; 55 Mohm with diode BYW96E</p> </li> <li data-start="568" data-end="663" class=""> <p data-start="570" data-end="663" class="">Pull/Hold Current: 8.8 A / 0.9 A&nbsp;&nbsp;&nbsp;&nbsp;<em data-start="611" data-end="661">Note: Pull status duration is less than 1 second</em></p> </li> <li data-start="664" data-end="698" class=""> <p data-start="666" data-end="698" class="">DC Supply Voltage: 13.47 V</p> </li> </ul> <p data-start="700" data-end="728" class=""><br></p><p data-start="700" data-end="728" class="">Note on Faulty Solenoid:</p> <ul data-start="729" data-end="838"> <li data-start="729" data-end="778" class=""> <p data-start="731" data-end="778" class="">Resistance of Damaged Solenoid: 15.3 ohms</p> </li> <li data-start="779" data-end="838" class=""> <p data-start="781" data-end="838" class="">Insulation Resistance (IR): &gt; 55 Mohm (without diode)</p> </li> </ul> <p data-start="840" data-end="905" class=""><br></p><p data-start="840" data-end="905" class=""><br></p></div>', '<p><a href="Z:\\02-PBN-M\\02 MEI\\19 Photos\\00 Electrical Photos\\QP\\Lifeboat\\Life boat No.2\\17-05-25 TS lifeboat no.2 (X-6900B) could not be stopped by electric mode">Z:\\02-PBN-M\\02 MEI\\19 Photos\\00 Electrical Photos\\QP\\Lifeboat\\Life boat No.2\\17-05-25 TS lifeboat no.2 (X-6900B) could not be stopped by electric mode</a><br></p>', '2025-05-17 17:02:41', '2025-05-17 18:08:02', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-X-6900B', 'GBN-X-6900B', 'LIFEBOAT/DAVIT NO.2', NULL, NULL, 'LIFEBOAT/DAVIT NO.2', 'GBN-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
