  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitas', NULL, 'EXTERNAL', '2025-05-17 17:02:41', '2025-05-17 18:08:02', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop');
