-- Inserting report ID 30766
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Mobile Generator ART-G-03 malfunction.', 'Electrical', 'CM', 'Completed', '2025-05-17', '<p>TS Mobile Generator ART-G-03 malfunction. (at AWP1)</p><p>- Measure battery that found absence voltage 12.4 VDC.</p><p>- Started engine, found HMI alarm "ChrgAlternFail" by the engine able to continue running.</p><p>- Measure battery during engine is running that found voltage is 11.8 V and discharge current 4.5 A</p><p>- Observed belt of alternator is slewing, then stop the engine which found belt slip and damaged.</p><p>&nbsp; &nbsp;&nbsp; &nbsp;</p><p><br></p><p>- Try to adjust alternator for tighten belt and pulley, then started engine again.</p><p>- HMI still alarm "ChrgAlternFail" and there is no voltage from alternator while battery still discharge 4.3 A</p><p><br></p><p>- Installed temporary charger (Victron Energy - Skylla-IP65) which removed from in front of EI-Workshop inside generator enclosure by connect 230 VAC from outlet socket (Blue) and direct charge to battery box 12 VDC of inside package</p><p>&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; &nbsp;&nbsp;&nbsp;</p><p><br></p><p>- Started engine, found charger display 14.4 V and 15 A, then measure charging current into battery is&nbsp;</p><p>&nbsp;12.5 A by HMI (JB3) display power voltage 13.89 V</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<br></p><p><br></p><p>- Keep running engine for approx.40 min, charging current reduced to 5.2 A and stable.</p><p><br></p><p><br></p><p>*HMI alarm "ChrgAlternFail" by the engine able to continue running.</p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2FMobile%20Gen%20Picture%2FART%2DG%2D03%2F20250517%5FART%2DG%2D03%5FAlternator%5FNoVolt&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250517_ART-G-03_Alternator_NoVolt</a><br></p>', '2025-05-17 18:28:04', '2025-05-17 19:30:49', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
