-- Inserting report ID 30799
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot TG-3 signal loss on Pi-Data.', 'Turbine E&I', 'CM', 'Completed', '2025-05-18', '<div>Troubleshoot TG-3 signal loss on Pi-Data.</div><div>&nbsp;- A Major error was detected on the Ethernet/IP card in slot 6. This required a power cycle to reinitialize the clock timing.&nbsp;</div><div>&nbsp;- While the TG-3 was idle and offload, TG-1 and TG-2 continued to shar the load normally.</div><div>&nbsp;- The Ethernet/IP card in slot 6 was temporarily removed (Rack-out) and then reinserted (rack-in).</div><div>&nbsp;- After the rack-in, the card returned to healthy status, and the Pi-Data was successfully re-established.</div><div>&nbsp;- According to minimize running hours of the TG-1, and TG-3 was ready to load, then load sharing was adjust between TG-2 and TG-3 a 30/70 ratio.</div><div>&nbsp;- Finally, the TG-1 was normally stopped after the TG-2 and TG-3 resumed proper load sharing.</div>', NULL, '2025-05-18 16:05:14', '2025-05-18 16:06:42', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A6300.PK', 'ART-PP-A6300.PK', 'APP MAIN POWER GENERATOR 3 PACKAGE', NULL, NULL, 'APP MAIN POWER GENERATOR 3 PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
