  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sittichok', NULL, 'EXTERNAL', '2025-05-18 16:18:00', '2025-05-27 15:10:09', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
