-- Inserting report ID 30806
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S HypoChlorinator A-4670 unit-A Tripped.', 'Electrical', 'CM', 'In Progress', '2025-05-18', '<p>T/S HypoChlorinator A-4670 unit-A and Both Blower Tripped.</p><p>- Found UCP-PP-4670 (Unit-A) black out and MCB 100A inside Rectifier Control Panel Tripped.</p><p>- Turn off CB 2 A (Primary of Transformer) and reset MCB 100 A, then Turn on CB 2A.</p><p>- Unit-A is available, then test function.</p><p>&nbsp;&nbsp;</p><p><br></p><p>- Observed Blower tripped after start unit for a few minute by Blower-B Fault and Low Air Flow Blower-B Alarm on HMI.</p><p>- Try to start unit-A or B by select Blower-A, found Blower Fault same as previously.</p><p>&nbsp;&nbsp;</p><p><br></p><p>- Manual start Blower-A (BM-4670) and B (BM-4675) one by one, both blower able to run for over 5 minutes without tripping.</p><p>- The Flapper at discharge blower can be operated properly without friction.</p><p><br></p><p>- Monitor Flow (FIT-4671) and measure current (4-20 mA) to PLC which found blower unable to make up flow over setpoint 500 NCMH (Nm3/Hr : Normal Cubic Meter / Hour) cuase to blower tripped after start unit.</p><p><br></p><p>Blower-A (BM-4670) Running, Flow = 500.8 MCMH, I = 8.48 mA</p><p>&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp;&nbsp;<br></p><p><br></p><p>Blower-B (BM-4675) Running, Flow = 525 NCMH, I = 9.12 mA</p><p>&nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp;<br></p><p><br></p><p>Both Blowers Running, Flow = 631.8 NCMH, I = 8.89 mA</p><p>&nbsp;&nbsp;&nbsp; </p><p>&nbsp;&nbsp;<br></p><p><br></p><p>To be verified performance of blower-motor or error of flow transmitter.</p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FHypoChloride%5FA%2D4670%2F20250518%5FTrip%5FBlw%5FLowFlow&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250518_Trip_Blw_LowFlow</a><br></p>', '2025-05-18 17:32:09', '2025-06-14 09:21:25', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-FIT-4671', 'ART-FIT-4671', 'FLOW INDICATOR TRANSMITTER', NULL, NULL, 'FLOW INDICATOR TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-UCP-PP-4670', 'ART-UCP-PP-4670', 'CONTROL PANEL', NULL, NULL, 'CONTROL PANEL', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
