-- Inserting report ID 30807
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul and replace wear ring pump ', 'Mechanic', 'CM', 'Completed', '2025-05-17', '<p><b><u style="background-color: rgb(255, 255, 0);">Found Pump low flow performance</u></b></p><p><b><u>Overhaul pump and replace mech seal.</u></b></p><p>- Mark sure process &amp; electrical isolation complete before start work.<br>- Remove coupling cover guard of pump and motor.<br>- Remove flushing line mechanical seal.<br>- Mark and remove spacer of coupling by loosening bolts. Record the distance between two couplings (DBSE, DBFF)</p><p>- Swing setting washers to lock drive collar for protecting mechanical seal.<br>- Remove pump casing cover with bearing housing by loosening stud bolts.<br>Warning: Wear half mask, face shield and disposable coverall for mercury protection<br>- Remove impeller by loosening lock key and impeller nut. (Clockwise direction)<br>- Loosen set screw of drive collar mechanical seal and remove it from the shaft.</p><p>- Remove bolts lock bearing housing.<br>- Split bearing housing from casing cover.<br>- Remove mechanical seal by remove four nuts securing the gland plate to casing cover.<br>- Remove shaft assembly from bearing housing.<br>- Remove radial and thrust bearings by using press machine.</p><p>- Clean shaft, bearing cover, labyrinth rings with WD-40 and abrasive papers.</p><p>- Shaft run-out DE (Record 0.00 mm)<br>- Shaft run-out NDE (Record 0.02 mm)<br>- Heat up radial and thrust bearings to 90 degrees Celsius and slide into the shaft.<br>- Install shaft assembly into bearing housing.<br>- Install lock washer and lock nut torque 160 Nm.<br>- Install labyrinth ring.<br>- Install deflector.<br>- Clean impeller and pump casing cover by using WD-40 and abrasive paper.<br>- Install mechanical seal on casing cover and tighten the nuts torque 50 ft-lbs.<br>- Remove setting washers lock drive collar.<br>- Shaft end play (Dynamic 0.03 mm)<br>- Shaft lift between bearing-to-bearing housing (0.03 mm)<br>- Lift bearing housing and slide the shaft into mechanical seal.<br>- Mount impeller on shaft and tighten impeller nut. Lock impeller nut with set screw.<br>- Move pump casing cover with bearing housing and slide it into pump casing tighten &amp; toque stud bolts of pump casing torque 404 ft-lbs.<br>- Top up bearing housing oil to the correct level. (PTT TERBIN T46)<br>- Clean and install coupling with cloth.<br>- Install laser alignment tool on coupling of pump and motor<br>- Swing setting washers out off drive collar, Tighten set screw of drive collar mechanical seal with shaft.<br>- Install flushing line mechanical seal.<br>- Mechanical running test (MRT).</p><p>- Discharge pressure 4 bar.&nbsp;</p><p>- Flow rate 56-60&nbsp;</p><p><b><u style="background-color: rgb(255, 255, 0);">Replace wear ring.&nbsp;</u></b></p><p><u>- Casing wear ring (1500.1) </u></p><p>&nbsp; &nbsp; Old value&nbsp;Ø181.50 mm.</p><p>&nbsp; &nbsp; New value after replacing Ø181.03 mm.</p><p><u>- Impeller wear ring (2300.1)</u></p><p>&nbsp; &nbsp; Order spear part&nbsp;</p><p>&nbsp; &nbsp; Not replace and check value Ø180.17 mm.</p><p>** Gap between&nbsp;Casing wear ring (1500.1) and&nbsp;Impeller wear ring (2300.1) = 0.86 mm.**</p><p><u>- Casing cover wear ring (1500.2)</u></p><p>&nbsp; &nbsp; Old value&nbsp;Ø151.27 mm.</p><p>&nbsp; &nbsp; New value after replacing Ø151.27 mm.</p><p><u>- Impeller wear ring (2300.2)</u></p><p>&nbsp; &nbsp; Old value&nbsp;Ø150.30 mm.</p><p>&nbsp; &nbsp; New value after replacing Ø150.51 mm.</p><p>** Gap between&nbsp;Casing wear ring (1500.2) and&nbsp;Impeller wear ring (2300.2) = 0.76 mm.** (Old gap 0.97 mm)</p><p><br></p>', NULL, '2025-05-18 17:32:30', '2025-05-19 09:01:23', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-4100', 'ART-P-4100', 'PRODUCED WATER BOOSTER PUMP', NULL, NULL, 'PRODUCED WATER BOOSTER PUMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Suthus', NULL, 'EXTERNAL', '2025-05-18 17:32:30', '2025-05-19 09:01:23', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tinnakorn', NULL, 'EXTERNAL', '2025-05-18 17:32:30', '2025-05-19 09:01:23', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '33.30.03.201.3', 'Overhaul and replace wear ring pump ', '0', '2025-05-18 17:32:30', '2025-05-19 09:01:23', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '33.30.03.224.3', 'Overhaul and replace wear ring pump ', '0', '2025-05-18 17:32:30', '2025-05-19 09:01:23', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane');
