-- Inserting report ID 30912
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify water maker HP pump suction pressure low.', 'Mechanic', 'CM', 'Completed', '2025-05-22', '<p>Failure cause: Pressure suction pressure low S/D.</p><p><br></p><p>On&nbsp; 17 May 2025</p><p>1. Procduction operator found water maker package trip by suction pressure low.</p><p>2. Remove filter 5 micron and remove filter 20 micron.</p><p>3. Test run and still S/D suction pressure low.</p><p><br></p><p>On 18 May 2025</p><p>1. Found motor stange noise.</p><p>2. Assume LP pump low performance. Replace new pump and motor(overhaul)</p><p>3. Test run and still S/D suction pressure low.</p><p><br></p><p>On 19 May 2025</p><p>1. Verify pressure switch suction side of HP pump. Found pressure switch normal condition.</p><p>2. Assume selector valve V12 passing to overboard. Replace new valve.</p><p>3. Test run and still S/D suction pressure low.</p><p><br></p><p>On 20 May 2025</p><p>1. Assume selector valve V5 passing to overboard. Replace new valve.</p><p>2. Test run and still S/D suction pressure low.</p><p>3. Remove LP pump for install by pass line from suction of LP pump to filter.</p><p>4. Test run and water maker can operate.</p><p><br></p><p>On 21 May 2025</p><p>1. Assume motor rotate wrong direction. EI verify and found motor rotate correct direction.</p><p>2. Assume LP pump low performace. Remove LP pump and found suction eye side scratch with volute.</p><p>3. Repair and reinstall with motor.</p><p>4. Housekeeping and plan for tomorrow.</p><p><br></p><p>On 22 May 2025</p><p>1. Remove by pass line.</p><p>2. Install LP pump and motor.</p><p>3. Line up and start unit package.</p><p>4. Found water maker package running normal condition.</p><p>5. Housekeeping.</p><p><br></p>', NULL, '2025-05-21 18:08:36', '2025-05-22 16:43:07', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-5410A', 'ART-P-5410A', 'HIGH PRESSURE PUMP', NULL, NULL, 'HIGH PRESSURE PUMP', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pawais', NULL, 'EXTERNAL', '2025-05-21 18:08:36', '2025-05-22 16:43:07', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ratchanut', NULL, 'EXTERNAL', '2025-05-21 18:08:36', '2025-05-22 16:43:07', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nattachai', NULL, 'EXTERNAL', '2025-05-21 18:08:36', '2025-05-22 16:43:07', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
