  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM replace DE bearing of 2P-5030B', 'Mechanic', 'CM', 'In Progress', '2025-05-23', '<p>- Recheck alignment of pump.</p><p align="left">- Check leak DE mechanical seal for confirm mechanical seal.</p><p align="left">- Drain barrier fluid and brake flange 3/4”#3-600.</p><p align="left">- Drain DE bearing lube oil.</p><p align="left">- Turn setting plate of DE&amp;NDE mechanical seal to keep seal position.</p><p align="left">- Remove coupling spacer and hub.</p><p align="left">- Remove DE bearing housing.</p><p align="left">- Remove old bearing from sleeve .</p><p align="left">- Install new bearing with heat method temperature@110°C</p><p align="left">- DE Bearing, Roller SKF MTR NU 313 ECM. Qty 1 ea.</p><p align="left">- Replace labyrinth seal (4791) , (4811)</p><p align="left">- Install new bearing on pump shaft and install bearing housing.</p><p>                      </p><p align="left">- Reinstall hub for set DBSE between pump with motor.</p><p align="left">- Reinstall barrier fluid pipe line to DE mechanical seal.</p><p align="left">- Line up barrier fluid for mech seal leakage. No leak.</p><p align="left">    </p><p align="left">- Top up DE bearing lube oil.</p>', NULL, '2025-05-23 18:56:59', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5030B', 'GBS-2P-5030B', 'PRODUCED WATER RE-INJECTION PUMP B', NULL, NULL, 'PRODUCED WATER RE-INJECTION PUMP B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
