  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace membrane element T2B1(Air liquid type)', 'Mechanic', 'CM', 'Completed', '2025-05-23', '<p><span style="background-color: rgb(255, 255, 0);">Replace membrane element T2B1 (Tube no.12)</span></p><p>** North side 3 element (Air liquid type)</p><p>** South side 3 element (Air liquid type)</p><p><br></p><p>1. Remove UOP membrane element T2B1 both side.(2 element per side)<br>2. Cleaning inside tube by alcohol with with PIG cotton rags.<br>3. Installed loading tray for load element.<br>4. Load element with new design " AIR LIQUID TYPE " and accessory part.<br>5. Re-assembly nozzle and Elbow joint.<br>6. Hand torque 329 Nm.(242 lbf.ft)<br>7. Cleaning working area.<br>8. Leak test by Operator team.</p>', '<span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">1. Mem brane Air liquid type = 6 Ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">2. Dummy nozzle = 2 Ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">3. Taper seal ring = 2 Ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">4. Spiral wound gasket 4" 600# 316L = 4 Ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">5. Anti seize = 1 can.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">6. O-ring lube = 1 tube.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">7. Check valve = 2 Ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">8. Center ring = 4 Ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">9. Safety pin = 4 Ea.</span>', '2025-05-23 20:56:52', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-MEM-2400-01-12', 'ART-MEM-2400-01-12', 'MEMBRANE BANK 1', NULL, NULL, 'MEMBRANE BANK 1', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
