-- Inserting report ID 31032
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting Low BTU Flare Common Alarm (2XI-42', 'Instrument', 'CM', 'Under Monitoring', '2025-05-24', '<div>Troubleshooting Low BTU Flare Common Alarm (2XI-42458)</div><div><br></div><div>Observation:</div><div>Pilot 1 Low BTU: Indicator lamp (2XI-42413A) OFF. &gt;&gt; (Abnormal condition)</div><div>Pilot 2 Low BTU: Indicator lamp (2XI-42413B) ON.&nbsp; &nbsp;&gt;&gt; (Normal condition)</div><div><br></div><div>Verification: Requested Automation Technician support to verify the program logic.</div><div>Logic feedback checked from temperature elements: Set point for low BTU detection: 93 (Real value)</div><div>2TE-42500A: Feedback reading = 47.8 (Real value)</div><div>2TE-42500B: Feedback reading = 29.4 (Real value)</div><div><br></div><div>Findings: The Low BTU Flare Common Alarm (2XI-42458) was triggered because the temperature feedback from both thermocouples (2TE-42500A and 2TE-42500B) was below the set point.</div><div>This condition indicates an inadequate temperature to sustain proper combustion for the flare pilots.</div><div><br></div><div>Suspected Cause: The temperature readings are significantly lower than the set point. External factors such as adverse weather conditions (e.g., wind speed and direction) may be affecting the flame stability and temperature measurement.</div><div><br></div><div>Action Taken: Monitoring of temperature feedback from 2TE-42500A and 2TE-42500B continues, and observing weather conditions and their potential impact on flare operation.</div>', NULL, '2025-05-24 16:41:03', '2025-05-24 17:01:56', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-4240', 'GBS-2X-4240', 'FLARE IGNITION SYSTEM', NULL, NULL, 'FLARE IGNITION SYSTEM', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-05-24 16:41:03', '2025-05-24 17:01:56', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'SompongJ', NULL, 'EXTERNAL', '2025-05-24 16:41:03', '2025-05-24 17:01:56', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'KittisakP', NULL, 'EXTERNAL', '2025-05-24 16:41:03', '2025-05-24 17:01:56', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
