  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fire water pump performance test 2025 (P-5700)', 'Mechanic', 'PM', 'Completed', '2025-05-25', '<p><span style="background-color: rgb(255, 255, 0);">Fire water pump performance test 2025</span></p><p><br></p><p>1.Open Permit to Work for P-5700 Performance Test<br>2.Check Firewater package condition to ensure equipment readiness according to ART-OPS-ME-002 check list section 1-4 “Check list BEFORE startup”<br>3. Close firewater ring main isolation valve tag No. HV-17605<br>4. Start P-5700 firewater pump.<br>5. Perform firewater pump operational check.<br>6. Fully open manual shutoff valve tag No. HV-3652<br>7. Fully open manual control valve tag No. HV-3651<br>8. Fully close pressure control valve tag No. PCV-5700<br>9. Fully close manual shutoff valve tag No. HV-3647.<br>10. Record all data on Maximum flow condition.<br>11. Gradually increase header pressure by closing manual control<br>valve tag No. HV-3651 about 1 barg at a time.<br>12. Repeat step 9 and 10 until pump discharge pressure reach 11.2<br>barg (read from PIT-5700)<br>13. Open manual control valve tag No. HV-3651 (avoiding running on<br>shutoff head condition).<br>14. Stop P-5700 firewater pump.<br>15. Normalizing P-5700 firewater pump system</p>', NULL, '2025-05-25 18:35:02', '2025-05-26 17:48:14', 'PTTEP\\Art.MechBC', 'PTTEP\\art.mechcrane', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-5700', 'ART-P-5700', 'FIRE WATER PUMP', NULL, NULL, 'FIRE WATER PUMP', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tinnakorn S.', NULL, 'EXTERNAL', '2025-05-25 18:35:02', '2025-05-26 17:48:14', 'PTTEP\\Art.MechBC', 'PTTEP\\art.mechcrane');
