  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' Fire water pump performance test 2025 (P-5720)', 'Mechanic', 'PM', 'Completed', '2025-05-25', '<p><span style="background-color: rgb(255, 255, 0);">Fire water pump performance test 2025</span></p><p><br></p><p>1.Open Permit to Work for P-5720 Performance Test<br>2.Check Firewater package condition to ensure equipment readiness according to ART-OPS-ME-002 check list section 1-4 “Check list BEFORE startup”<br>3.Close Firewater ring main Isolation valve Tag. No. HV-3662 (Dwg.A-1-PP-PR-06-0440).<br>4.Start P-5720 firewater pump.<br>5.Perform Firewater pump operational check according to ART-OPS-ME-002 check list section 5-8 “Check list DURING pump operating”.<br>6.Record Vibration by Microlog Analyzer at Operating condition.<br>7.Fully open manual shutoff valve Tag. No. HV-3654 (Dwg.A-1-PP-PR-06-0440).<br>8.Fully open manual control valve Tag. No. HV-3653 (Dwg.A-1-PP-PR-06-0440).<br>9.Fully close pressure control valve Tag. No. PCV-5720 (Dwg.A-1-PP-PR-06-0440).<br>10.Fully close manual shutoff valve Tag. No. HV-3648 (Dwg.A-1-PP-PR-06-0440).<br>11.Record all data on Maximum flow condition according to P-5720 APP Operational Test Data Sheet as followings<br>• Record pressure on PIT-5720<br>• Record flow rate on FG-5720<br>• Record Engine speed on Engine control panel<br>• Record Engine cooling water pressure PG-5723<br>• Record Engine lube oil pressure on PG-5722<br>• Record Engine cooling water temperature on TG-5721<br>12.Gradually increase header pressure by closing manual control valve Tag. No.HV-3653 about 1 bar. at a time.<br>13.Repeat step 11 and 12 until pump discharge PIT-5720 reached 11.2barg.<br>14.Open manual control valve Tag. No.HV-3653 (avoiding running on Shutoff Head condition).<br>15.Stop P-5720 Firewater pump.<br>16.Normalizing P-5720 Firewater Pump system<br>17.Closed Permit to Work for P-5720 Performance Test</p>', NULL, '2025-05-25 18:36:41', '2025-05-26 17:48:05', 'PTTEP\\Art.MechBC', 'PTTEP\\art.mechcrane', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-5720', 'ART-P-5720', 'FIRE WATER PUMP', NULL, NULL, 'FIRE WATER PUMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
