-- Inserting report ID 31161
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP13: ELEC 8Y service campaign BC-23-402A', 'Electrical', 'PM', 'Complete', '2025-05-26', '<div>Electrical 8Year service campaign for Battery Charger BC-23-402A [24 Vdc] by vendor. (overall, 85% In progress)</div><div>&nbsp; &nbsp; - Replaced 33,000 µF capacitors (32 units) as part of the service campaign.</div><div>&nbsp; &nbsp; - Replaced AC fan for the thyristor bridge (1 unit).</div><div>&nbsp; &nbsp; - Cleaned components and tightened electrical connections.</div><div>&nbsp; &nbsp; - Conducted SCR measurements.&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Observed minor surface cracking on the bodies of thyristor bridge modules [V1–V6]. &nbsp;<br></div><div>&nbsp; &nbsp; - Performed transformer insulation and winding resistance measurements.</div><div>&nbsp; &nbsp; - Verified alarm settings and conducted functional tests for alarm operations and static load performance.</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - During testing, the <strong data-start="820" data-end="853">rectifier current limit alarm</strong> was triggered. However, the <strong data-start="882" data-end="929">output voltage did not decrease as expected</strong>, even when the simulated current reached <strong data-start="971" data-end="979">120%</strong> of the rectifier''s rated capacity (via mV signal to the measurement port). <strong data-start="1055" data-end="1095">Further verification is recommended.</strong><br></div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Detected a voltage drop exceeding 2% at load 120A, (48% of system capacity). <b>Further investigation is advised.</b></div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - At load 10A: float voltage 26.76V&nbsp;</div><div>&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - At load 40A: float voltage 26.60V&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - At load 100A: float voltage 26.30V&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - At load 120A: float voltage 26.21V&nbsp;</div><div>&nbsp; &nbsp; - Confirmed and verified system parameter settings.</div><div>&nbsp; &nbsp; - Performed functional testing post-maintenance; system is operating satisfactorily.</div><div><br></div><div>Remarks:&nbsp;System performance is acceptable post-maintenance; however, minor anomalies observed (thyristor surface condition, behavior of the rectifier current limit function and voltage drop under load) should be monitored and further evaluated.</div>', NULL, '2025-05-26 23:25:48', '2025-05-27 22:58:17', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-lead2', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-BC-23-402A', 'GBN-BC-23-402A', 'BATTERY CHARGER 24 VDC', NULL, NULL, 'BATTERY CHARGER 24 VDC', 'GBN-WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surapong', NULL, 'EXTERNAL', '2025-05-26 23:25:48', '2025-05-27 22:58:17', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-lead2');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kittipong', NULL, 'EXTERNAL', '2025-05-26 23:25:48', '2025-05-27 22:58:17', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-lead2');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'AEG', NULL, 'EXTERNAL', '2025-05-26 23:25:48', '2025-05-27 22:58:17', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-lead2');
