  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP13: ELEC 8Y service campaign BC-23-402B', 'Electrical', 'PM', 'Complete', '2025-05-27', '<div>Electrical 8Year service campaign for Battery Charger BC-23-402B [24 Vdc] by vendor. (overall, 93% In progress)</div><div>&nbsp; &nbsp; - Replaced 33,000 µF capacitors (32 units) as part of the service campaign.</div><div>&nbsp; &nbsp; - Replaced AC fan for the thyristor bridge (1 unit).</div><div>&nbsp; &nbsp; - Cleaned components and tightened electrical connections.</div><div>&nbsp; &nbsp; - Conducted SCR measurements.&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Observed minor surface cracking on the bodies of thyristor bridge modules [V1–V6]. &nbsp;<br></div><div>&nbsp; &nbsp; - Performed transformer insulation and winding resistance measurements.</div><div>&nbsp; &nbsp; - Verified alarm settings and conducted functional tests for alarm operations, including static load performance:</div> <ul data-start="784" data-end="979"> <li data-start="784" data-end="820">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- At load 10A: float voltage 26.71V&nbsp;</li></ul><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;At load 40A: float voltage 26.70V&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- At load 100A: float voltage 26.65V&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- At load 125A: float voltage 26.64V&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- At load 175A: float voltage 26.60V&nbsp;</div><div>&nbsp; &nbsp; - Confirmed and verified system parameter settings.</div><div>&nbsp; &nbsp; - Performed functional testing post-maintenance; system is operating satisfactorily.</div><div><br></div><div>Remarks:&nbsp;System performance is acceptable following maintenance. Minor surface anomalies identified on thyristor bridge components should be monitored and further evaluated.</div>', NULL, '2025-05-27 22:45:32', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-lead2', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-BC-23-402B', 'GBN-BC-23-402B', 'BATTERY CHARGER 24 VDC', NULL, NULL, 'BATTERY CHARGER 24 VDC', 'GBN-WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
