-- Inserting report ID 31208
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'DEP-5210 Perform top part overhaul and YPM.', 'Mechanic', 'PM', 'In Progress', '2025-05-27', '<p><b>Perform top part overhaul and YPM. (</b>Completed mechanical task PM.)</p><p><b>WORK SUMMARY:</b></p><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><br></div><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><i>&nbsp;</i><u>Diesel engine.</u> =&gt;&nbsp;Perform top part overhaul &amp; 1 YPM with Metro CAT. (78% Progress)</div><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><br></div><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><table width="628"></table>- Installed engine rocker arms, bridge, push rods and adjusted valve lash.<table width="628"></table>- Installed fuel injector line with new spares.<table width="628"></table>- Installed engine valve covers, exhaust manifolds and exhaust pipes.<table width="628"></table>- Installed the turbocharger and air intake line.</div><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><br></div><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><p><u>Cooling system.</u></p><p>- Inspected zinc anode in row water system, found deteriorate 2 ea. and replaced new. (wrench 7/8”)</p><p>- Inspect coolant line connection and hose OK.</p><p></p><p>- Checked and cleaned up cooling water strainers. Removed and replaced new gasket. (wrench 1 1/16”, 7/8” ¾” and ½”)</p><p><br></p><p><u>Fuel system.</u></p><p>- Checked for any leak no found leak.</p><p>- Drained sediment and water trap from fuel tank.</p><p>- Cleaned up fuel pre-filter (strainer (wrench15/16”, 1/2"))&nbsp; </p><p>- Cleaned up fuel pre-filter of diesel fuel storage tank. (wrench 1/2")&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p></p><p>- Cleaned flame arrester of diesel fuel storage tank.</p><p><br></p><p><u>Air induction system</u>.&nbsp;&nbsp;&nbsp;</p><p>- Inspected, cleaned Air intake filter and replace new primary air filter sheet (M80)</p><p>- Inspected air inlet system for any leaks no found leak.</p><p><br></p><p><u>Pump and gearbox</u><u>.</u></p><p>- Inspected coupling and lubricate universal joint with grease. (EP-2)</p><p></p><p>- Checked all coupling bolt tightness, all bolt were tighten. &nbsp;(Wrench 15/16” and Allen-key 14 mm.)&nbsp;</p><p><br></p><p><u>Air starting supply.</u></p><p>- Change lube oil of air compressor about 0.7 liters. (Compressor oil 100)</p><p>- Inspected and cleaned air inlet filter of compressor.</p><p>- Checked belt tension found normal no adjust.&nbsp;</p><p>- Cleaned the skid.</p><p><br></p></div><div ccp_infra_version="3" ccp_infra_timestamp="1748263674711" ccp_infra_user_hash="988116346" ccp_infra_copy_id="efb3769c-2375-47f3-a439-a918ef92808f" data-ccp-timestamp="1748263674711"><table width="628"></table></div>', NULL, '2025-05-28 10:33:30', '2025-05-28 15:06:35', 'PTTEP\\Mech_WS', 'PTTEP\\Bongkot.Valve', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-DEP-5210', 'GBN-DEP-5210', 'FIRE WATER PUMP PACKAGE', NULL, NULL, 'FIRE WATER PUMP PACKAGE', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nopporn P.', NULL, 'EXTERNAL', '2025-05-28 10:33:30', '2025-05-28 15:06:35', 'PTTEP\\Mech_WS', 'PTTEP\\Bongkot.Valve');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thapon W.', NULL, 'EXTERNAL', '2025-05-28 10:33:30', '2025-05-28 15:06:35', 'PTTEP\\Mech_WS', 'PTTEP\\Bongkot.Valve');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, '3 Metro CAT', NULL, 'EXTERNAL', '2025-05-28 10:33:30', '2025-05-28 15:06:35', 'PTTEP\\Mech_WS', 'PTTEP\\Bongkot.Valve');
