  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-9:Verify platform voltage low.', 'Instrument', 'CM', 'Complete', '2025-05-27', '<p>-Found platform voltage alarm low at the SCADA at night and then verify the voltage transducer found that input of voltage transducer(terminal 1,2) connect together with the power supply of the radio, when the radio working, found that the voltage swing around&nbsp; 27.2 - 24.8 vdc/2.3 A.</p><p>-Measure at terminal 3,4 of voltage transducer, not found voltage drop when the radio working, voltage around 27.75 - 26.6 vdc.&nbsp;</p><p>-Re-located wiring of the voltage transducer as follows</p><p>&nbsp; Old wiring of voltage transducer</p><p>&nbsp; &nbsp; Input, terminal 1,2 : connect from 24 vdc of the radio</p><p>&nbsp; &nbsp; Power supply, terminal 3,4 : connect from 24 vdc from RLY-19-600A</p><p>&nbsp; &nbsp; Output, terminal 5,6 : connect to the Motorola PLC</p><p>&nbsp; New wiring of voltage transducer</p><p>&nbsp; &nbsp; Input, terminal 1,2 : connect from 24 vdc from RLY-19-600A</p><p>&nbsp; &nbsp; Power supply, terminal 3,4 : connect from 24 vdc of the radio</p><p>&nbsp; &nbsp; Output, terminal 5,6 : connect to the Motorola PLC</p><p>-Measure voltage at the voltage transducer, terminal 1,2 found that voltage reading around 27.2 - 26.8 vdc, when the radio working 2.3 A.</p><p>-Keep monitoring.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/01%20Instrument%20Photos/01.Remote%20Platform/WP9/Verify%20platform%20voltage%20low%20on%2027%20May%2025?csf=1&amp;web=1&amp;e=V9pI3a">Verify platform voltage low on 27 May 25</a>', '2025-05-28 14:11:36', '2025-05-28 14:37:45', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
