BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Crane cannot hoist up and test.', 'Electrical', 'CM', 'Completed', '2025-05-29', '<p>T/S Crane cannot hoist up and test.</p><p>- The crane Robway system was found to have no alarm.</p><p>-&nbsp;Verified the hoist-up solenoid valve and found that it was not functioning due to the absence of a 24V DC power supply.</p><p>- Verified the Robway power supply to the solenoid valve and found a loose terminal connection due to improper cable installation.</p><p>- Reconnected the cable and tightened the terminals at both the Robway unit and the solenoid junction box.</p><p>- Performed crane function test; verified solenoid voltage = 24.15Vdc, confirmed that the solenoid valve is operating properly.</p><p>- Verified crane operation; found it functioning correctly with no alarms present.</p>', 'Found that the crane annunciator alarms were incorrect due to a PLC control alarm error, which requires further rectification.', '2025-05-29 21:03:57', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
