-- Inserting report ID 31323
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM 2HCV-12000N Troubleshoot choke valve stuck.', 'Mechanic', 'CM', 'Completed', '2025-05-28', '<p align="left">o&nbsp;&nbsp; Request to function test found choke valve can close and open, then try to function test 3 times to close and open found choke valve stuck close at 18% Choke (2/3 times).</p>  <p align="left">o&nbsp;&nbsp; Manual to close the choke valve found it fully closed (0%) then test the passing found choke valve is not passing.</p>  <p align="left">o&nbsp;&nbsp; Request MEI to verify <a name="_Hlk166168135">the command closed of solenoid of Actuator found that the pilot of command closed solenoid of Actuator is malfunction.</a></p>  <p align="left">o&nbsp;&nbsp; Disconnect the fitting and tubing of Actuator then remove the pilot.</p>  <p align="left">o&nbsp;&nbsp; Founded wiper stem nut damaged.</p>  <p align="left">o&nbsp;&nbsp; Remove cover plate and bonnet founded thrust bearing broken.</p>  <p align="left">o&nbsp;&nbsp; Replead bonnet and cover plate for hot spare.</p>  <p align="left">o&nbsp;&nbsp; Function test to opened and closed the choke valve found normal operate.</p>  Cleaning the working area.', NULL, '2025-05-30 16:16:36', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2HCV-12000N', 'GBS-2HCV-12000N', 'CHOKE VALVE', NULL, NULL, 'CHOKE VALVE', 'GBS-WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Apinan I.', NULL, 'EXTERNAL', '2025-05-30 16:16:36', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patawee J.', NULL, 'EXTERNAL', '2025-05-30 16:16:36', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
