-- Inserting report ID 31325
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM WPS-02: Sump tank pump cannot operate.', 'Mechanic', 'CM', 'Completed', '2025-05-30', '<p align="left">- Test run sump tank pump found pump does not operate</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Removed spool air drive found O-ring spool gas drive was dry </p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; due to condensate from UG mix with lubricant effected to spool stuck.</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Replaced O-ring spool gas drive and lubricate.</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Replaced lubricant in lubricator port.</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Test run sump pump are normal and not found leak. Found pump lost suction then removed &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;suction strainer found strainer was block then clean suction strainer. This case effected to pump run too long time effected to O-ring spool gas drive were deteriorate.</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Run sump pump are normal and not found leak at discharge pressure 28 bar.</p>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Clean up working area.', NULL, '2025-05-30 16:26:59', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-1245', 'GBS-2P-1245', 'SUMP TANK PUMP', NULL, NULL, 'SUMP TANK PUMP', 'GBS-WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Apinan I and Patawee J.', NULL, 'EXTERNAL', '2025-05-30 16:26:59', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
END $$;

