-- Inserting report ID 31363
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'LLC Skid Trial project', 'Electrical', 'OTH', 'Under Monitoring', '2025-05-29', '<p><b>-Project Start-Up Report – Assist LLC Unit. 29/05/25</b></p>  <p><b>&nbsp;Power Source: LV-SB-200/4A-05 (WP-30-200)</b></p>  <p><b>-</b><b> </b><b>Pressure Build-Up Issue</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>During initial start-up, the unit failed to build pressure beyond 5 bar.</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>Action: Requires further verification and troubleshooting to determine the root cause (e.g., mechanical restriction, valve malfunction, incorrect system configuration, or pump performance issue).</b></p>  <p><b>VFD and Motor Performance:</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>VFD Frequency Setpoint: 45 Hz</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>Measured Motor Current: 29 Amps</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>This represents approximately 80% of the motor’s full load current.</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>Motor Nameplate Data</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>Voltage: 3-phase, 380/660 VAC</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>Frequency: 50/60 Hz</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>Current: 37 A @ 380V, 21.3 A @ 660V</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>Power: 25 HP</b></p>  <p><b>Preliminary Observations:</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>The current draw at 45 Hz (29 A) seems proportionally high considering the motor is rated 37 A at 380V and 50 Hz.</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>This may indicate:</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>Mechanical load is heavier than expected.</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>System is operating inefficiently or under partial blockage.</b></p>  <p>o&nbsp;&nbsp;&nbsp; <b>Pump is not properly primed or cavitating.</b></p>  <p><b>&nbsp;</b></p>  <p><b>-Swapped two of the motor power cables at the VFD output to correct the motor rotation.</b></p>  <p><b>-Verified that the new motor rotation is clockwise, as required.</b></p>  <p><b>-Result the LLC unit start-up correctly.</b></p>', NULL, '2025-05-31 05:49:18', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-lead2', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-BE-3101', 'GBN-BE-3101', 'Pillow box bearing', NULL, NULL, 'Pillow box bearing', 'GBN-WP31', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yohun', NULL, 'EXTERNAL', '2025-05-31 05:49:18', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-lead2', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, '2 CR3 Vender', NULL, 'EXTERNAL', '2025-05-31 05:49:18', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-lead2', NULL);
