  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM 2X-4850: Perform 6MPM.', 'Mechanic', 'PM', 'Completed', '2025-05-31', '<p align="left">Perform 6MPM.</p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace lube oil gearbox with MOBIL SHC 630,<br>0.5 liter for:&nbsp; &nbsp;2P-4855 pH adjuster pump.</p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4856 Anti- scale pump.<u></u></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace oil at diaphragm housing pump with TOTAL Azolla ZS 10, 0.5 liter for:</p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4855 pH adjuster pump.</p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4856 Anti- scale pump.</p><p align="left">&nbsp;Cleaning (flush) Pump (2P-4857)<u></u></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; General visual check on the holding down bolt for corrosion.</p><p align="left"></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tightening and driving coupling check.</p><p align="left">&nbsp;&nbsp;Membrane Feed pump (2P-4854)</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Visual check pump coupling condition.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Suction/Discharge piping connection joints.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Pump’s motor mounting bolts.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Last running performance:</p><p align="left"></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Discharge pressure=43 bars.</p><p align="left">&nbsp;<u>Filters</u></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove and clean the filter nozzles.</p><p align="left">o&nbsp;&nbsp; 2 multi-media filters, 2F-4850A/B.</p><p></p><p align="left">o&nbsp;&nbsp; 2 Carbon filters, 2F-4851A/B.</p><p align="left"><u>Unit running and back in service</u></p><p align="left"></p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The unit running condition and all parameters are in normal.</p>', NULL, '2025-05-31 14:27:43', CURRENT_TIMESTAMP, 'PTTEP\\PataweeJi', NULL, false, 'G2S') RETURNING id INTO new_report_id;
