  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-11 : Verify platform voltage low', 'Electrical', 'CM', 'In Progress', '2025-05-31', '<p>WP-11 : Verify platform voltage low</p><ul data-start="81" data-end="428"><li data-start="81" data-end="125"><p data-start="83" data-end="125">- Verified low platform voltage at the PI.</p> </li> <li data-start="126" data-end="258"> <p data-start="128" data-end="258">- Identified the measurement point at the power supply for the radio and tapped into the supply source for the voltage transducer.</p> </li> <li data-start="259" data-end="328"> <p data-start="261" data-end="328">- No spare terminals available for the relocated measurement point.</p> </li> <li data-start="329" data-end="428"> <p data-start="331" data-end="428">- <span style="background-color: rgb(255, 255, 0);">Plan to relocate the measurement point during the next platform shutdown (Plan: TBC)</span></p></li></ul><p><br></p><p></p>', '<p><a href="https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/Forms/AllItems.aspx?id=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2F02%2DPBN%2DM%2F02%20MEI%2F19%20Photos%2F00%20Electrical%20Photos%2FWPs%20PICTURES%2FWP11%2FTELEMETRY%20BATTERY%2DSOLAR%2DCHARGER%2F2025%2D05%2D31%20Verify%20platform%20voltage%20low&amp;viewid=dce8e204%2D2273%2D4c5e%2Da20c%2Dcbf12e9b5007">https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/Forms/AllItems.aspx?id=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2F02%2DPBN%2DM%2F02%20MEI%2F19%20Photos%2F00%20Electrical%20Photos%2FWPs%20PICTURES%2FWP11%2FTELEMETRY%20BATTERY%2DSOLAR%2DCHARGER%2F2025%2D05%2D31%20Verify%20platform%20voltage%20low&amp;viewid=dce8e204%2D2273%2D4c5e%2Da20c%2Dcbf12e9b5007</a></p><p><br></p><p><br></p><p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/01%20Instrument%20Photos/01.Remote%20Platform/WP11/TS%20platform%20voltage%20low%20on%2031%20May%2025?csf=1&amp;web=1&amp;e=OOHX0T">TS platform voltage low on 31 May 25</a></p>', '2025-05-31 20:34:10', '2025-06-01 06:47:55', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
