-- Inserting report ID 31403
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'RP: Verify MAC-9095 fault alarm', 'Instrument', 'CM', 'Complete', '2025-05-31', '<p>Verify MAC-9095 fault alarm</p><p>&nbsp; &nbsp; - Observed that the loop current exceeded 20 mA upon activation, indicating a fault condition.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Replaced the unit with a new spare part (Item: 60.55.09.008.3 CALL POINT, P/N: WCP2A-R220SG-T200-03IS).<br></p><p data-start="326" data-end="497"> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Modified circuit board by replacing:</p><p data-start="326" data-end="497">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Resistor R1 from 220 ohm to 2.4K ohm</p><p data-start="326" data-end="497">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Resistor R2 from 220 ohm to 1.8K ohm</p><p data-start="587" data-end="707">&nbsp; &nbsp; - The device was tested and found to be functioning satisfactorily with the following results:</p><p data-start="587" data-end="707">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Loop current (Normal Condition): 4.05 mA</p><p data-start="587" data-end="707">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Loop current (Activated Condition): 9.25 mA</p><p data-start="587" data-end="707"><br></p><p data-start="587" data-end="707">Reference Values for Loop Current:</p><ul data-start="846" data-end="979"> <li data-start="846" data-end="873"> <p data-start="848" data-end="873">&nbsp;&nbsp;&nbsp;&nbsp;Open Circuit: &lt; 4.00 mA</p> </li> <li data-start="874" data-end="911"> <p data-start="876" data-end="911">&nbsp;&nbsp;&nbsp;&nbsp;Normal Condition: 4.10 to 7.99 mA</p> </li> <li data-start="912" data-end="949"> <p data-start="914" data-end="949">&nbsp;&nbsp;&nbsp;&nbsp;Alarm Condition: 8.00 to 19.99 mA</p> </li> <li data-start="950" data-end="979"> <p data-start="952" data-end="979">&nbsp;&nbsp;&nbsp;&nbsp;Short Circuit: &gt; 20.00 mA</p> </li> </ul><p data-start="981" data-end="1001"><span data-start="981" data-end="1001">Additional Note:</span></p><p data-start="587" data-end="707">   </p><ul data-start="1003" data-end="1051"> <li data-start="1003" data-end="1051"> <p data-start="1005" data-end="1051">&nbsp;&nbsp;&nbsp;&nbsp;Voltage drop at LED must be greater than 1.5 V</p> </li> </ul>', NULL, '2025-05-31 21:19:39', '2025-06-03 12:56:52', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-MAC-9095', 'GBN-MAC-9095', 'MANUAL ALARM CALL POINT DRAIN TANK DECK', NULL, NULL, 'MANUAL ALARM CALL POINT DRAIN TANK DECK', 'GBN-RP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anan', NULL, 'EXTERNAL', '2025-05-31 21:19:39', '2025-06-03 12:56:52', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surapong', NULL, 'EXTERNAL', '2025-05-31 21:19:39', '2025-06-03 12:56:52', 'PTTEP\\Bongkot.EI-lead2', 'PTTEP\\Bongkot.EI-Workshop');
END $$;

