  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS signal fluctuation PIT-84601C at HIPPS.', 'Electrical & Instrument', 'OTH ', 'Completed', '2025-06-01', '<p><b><u>Activity</u></b> <br class="Apple-interchange-newline"></p><p>TS signal fluctuation PIT-84601C at ZMS HIPPS.</p><p><br></p><p>Action</p><p>- After permit open, inhibit transmitter by 1st valve isolation.</p><p>- Then, vent pressure and 2 nd valve isolation.</p><p>- Connect with manual hand pump.</p><p>- Use 250 ohm resistor to check by hard protocol.</p><p>- Pressure simulation by hand pump.</p><p>- Perform "Zero" calibration and loop test.</p><p>- Compare local pressure values with DCS.</p><p>- All simulation signals are stable.</p><p>- Release manual pressure and flushing with process gas.</p><p>- Remove inhibit transmitter PIT-84601C.</p><p>- Normalized transmitter on monitoring.</p><p>- Finish.</p>', NULL, '2025-06-01 17:34:08', '2025-06-01 17:43:15', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
