  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C)T/S 2UCP-34600 The Welker Probe Auto Sampler', 'Instrument', 'CM', 'In Progress', '2025-06-01', '<p data-start="65" data-end="130" class="">(C) T/S 2UCP-34600 The Welker Probe Auto Crude Oil Sampler Leaking</p><p data-start="65" data-end="130" class=""><br></p><p data-start="65" data-end="130" class="">Issue:</p><p data-start="65" data-end="130" class="">The Welker probe condensate auto crude oil sampler was leaking at the top motor, and the auto-sampler failed to properly collect samples.</p><p data-start="65" data-end="130" class=""><br></p><p data-start="65" data-end="130" class="">Actions Taken:</p><p data-start="65" data-end="130" class="">Disassembled the Welker probe for inspection.</p><p data-start="65" data-end="130" class=""><br></p><p data-start="65" data-end="130" class="">Replaced the damaged O-ring on the piston, crown seal, and ferrule with new spare parts.</p><p data-start="65" data-end="130" class=""><br></p><p data-start="65" data-end="130" class="">Calibrated the unit and checked the external relief valve, which is now set at 750 psi and functioning correctly.</p><p data-start="65" data-end="130" class=""><br></p><p data-start="65" data-end="130" class="">Performed a functional test; the piston is now operating properly with no leaks observed.</p><p data-start="65" data-end="130" class=""><br></p><p data-start="65" data-end="130" class="">Next Steps:</p><p data-start="65" data-end="130" class="">Reinstall the Welker probe and perform a functional test by tomorrow.</p>', 'To order spare full fill our stock', '2025-06-01 18:38:07', '2025-06-03 08:26:52', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Supv', false, 'G2S') RETURNING id INTO new_report_id;
