  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Underwater CCTV malfunction', 'IT', 'CM', 'Completed', '2025-06-02', '<p>The underwater camera installed on the structure ran into a problem because the pipe that supported the camera''s weight and carried the cables broke. As a result, the camera detached from its mounting point. Fortunately, it didn’t drift away since it was still held in place by a sling cable.</p><p>Previously, the camera would swing back and forth due to the waves, causing the video footage to be unstable. To fix this, a stabilising bracket was added to keep the camera steady, which improved the video quality. However, after being hit repeatedly by strong waves, the pipe holding the camera couldn’t withstand the force and eventually broke. Informed the project owner.</p><p><br></p><p></p>', NULL, '2025-06-02 18:59:47', CURRENT_TIMESTAMP, 'PTTEP\\GBS.ICT-Engineer', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-QP-UTLG-TELE-CCTV', 'GBS-QP-UTLG-TELE-CCTV', 'CLOSED CIRCUIT TELEVISION SYSTEM (CCTV)', NULL, NULL, 'CLOSED CIRCUIT TELEVISION SYSTEM (CCTV)', 'GBS-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pitak k', NULL, 'EXTERNAL', '2025-06-02 18:59:47', CURRENT_TIMESTAMP, 'PTTEP\\GBS.ICT-Engineer', NULL);
END $$;

