  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Charge new battery (12 cells) at PSV workshop', 'Electrical', 'OTH', 'In Progress', '2025-06-03', '<p>Charged new battery (12 cells) at PSV workshop, details as follows;</p><p>Before battery charging data;</p><p>Cell 1 = 0.247&nbsp;mohm , 2.14 V</p><p>Cell 2 = 0.250 mohm , 2.14 V</p><p>Cell 3 = 0.261 mohm&nbsp;, 2.14 V</p><p>Cell 4 = 0.248 mohm&nbsp;, 2.15 V</p><p>Cell 5 = 0.224 mohm&nbsp;, 2.15 V</p><p>Cell 6 = 0.250 mohm&nbsp;, 2.15 V</p><p>Cell 7 = 0.217 mohm&nbsp;, 2.14 V</p><p>Cell 8 = 0.214 mohm&nbsp;, 2.15 V</p><p>Cell 9 = 0.220 mohm&nbsp;, 2.15 V</p><p>Cell 10 = 0.222 mohm&nbsp;, 2.14 V</p><p>Cell 11 = 0.253 mohm&nbsp;, 2.13 V</p><p>Cell 12 = 0.260 mohm&nbsp;, 2.14 V</p><p>Total voltage = 25.72 VDC</p><p>------------------------------------</p><p>- Charged in "BOOST" charge mode.</p><p>- The initial charging current is 105 A , then decreases to 70.7 A after 30 minutes.</p><p>- Voltage charging is 29.29 VDC.</p><p></p>', '<p><font color="#555555" face="Helvetica Neue, Helvetica, Arial, sans-serif">MATERIAL No. = 65.28.16.018.9</font></p><p><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Modifiers: Battery, Secondary(Rechargeable), Lead-Acid</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Description: BATTERY,LEAD ACID</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Sizing: 1360 AH</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Range: 2V</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">MFG. for parts: ENERSYS</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Model: DDm85-33</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Additional information: MAINTENANCE FREE VALVE REGULATED LEAD ACID&nbsp;</span><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">SEALED TYPE</span><br style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;"><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">Required certificate of conformity/compliance or&nbsp;</span><span style="color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;">traceability record to verify before receiving</span></p>', '2025-06-03 17:57:53', '2025-06-07 09:30:52', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
