-- Inserting report ID 31564
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'FGC1_Strtup-TS_Tripped_Surge & PT OSP', 'Turbine E&I', 'CM', 'In Progress', '2025-06-03', '<div>FGC#1 Shutdown, Verification, and Startup Troubleshooting</div><div>&nbsp;- FGC#1 experienced a lockout shutdown (LO SD) trigged by Surge Control and PT3/PT4 Overspeed conditions.</div><div>&nbsp;- While Surge Control Shut typically initiate cooldown stop (required 5 minutes of idle), but PT3 &amp;PT4 overspeed condition necessitated a lockout shutdown.</div><div>&nbsp;- However, we believe the PT over speed tripped may have been a consequence of the surge margin dropping significantly below the shutdown setpoint. The recorded surge margin was -24% well below the zero% threshold.</div><div><br></div><div><p>FGC#1 was tripped by Surge Control Shutdown and PT3 &amp; PT4 Overspeed tripped.</p><p>Tripped Time : 10:00:41 Jun,3 2025</p><p>Restart Time &nbsp;: 10:37 in the same day</p></div>', NULL, '2025-06-03 18:38:47', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A1210.PK', 'ART-PP-A1210.PK', 'APP FEED GAS COMPRESSOR TRAIN 1 PACKAGE', NULL, NULL, 'APP FEED GAS COMPRESSOR TRAIN 1 PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
