  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Monthly Vibration of May 2025', 'Mechanic', 'OTH', 'In Progress', '2025-06-03', '<p><u><b>Monthly Vibration of May 2025&nbsp;</b></u>(80 % in progress)</p><p>- Performed data record for gas cooler fan 1st train 1, A-3230A/B/C/D</p><p>- Performed data record for gas cooler fan 1st train 2, A-3330A/B/C/D</p><p>- Performed data record for gas cooler fan 1st train 3, A-3010A/B/C/D</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);"><b>Note:</b></u></p><p><span style="background-color: rgb(255, 255, 0);"><b>PP Air compressor (K-5310A/B/C)</b></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; - Microlog still can''t save parameter after re-install new vibration route, plan to contact engineer to verify.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><b>PP Gas cooler fan A-3330A</b></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; - BNC Channel 1 (upper fan bearing) malfunction =&gt; Microlog shown <b>" ICP open circuit, please check data cable and sensor connector"</b> and <b>" Input signal overload"&nbsp;</b></span></p><p><span style="background-color: rgb(255, 255, 0);"><b><br></b></span></p><p><b ><u style="background-color: rgb(0, 255, 0);">Note 2 :</u></b></p><p><span style="background-color: rgb(0, 255, 0);">- Prepared 16 ea. of stud bolts B7 size 7/8"x160 for P-4750B 2"#900 loading valve replacement. (Cut stud bolts 8 ea. due to over length from criteria.)</span></p>', NULL, '2025-06-03 18:47:53', '2025-06-03 18:53:10', 'PTTEP\\Bongkot.Valve', 'PTTEP\\Bongkot.Valve', false, 'G2N') RETURNING id INTO new_report_id;
