-- Inserting report ID 31584
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Daily EI Turbine activities_2025Jun04', 'Turbine E&I', 'OTH', 'In Progress', '2025-06-04', '<div>Daily EI Turbine activities_2025Jun04</div><div><br></div><div>Turbo packages site walk-around inspection. Completed</div><div>&nbsp; - All Compressor units FGC, SGC, and 2 Units of TG are properly running. (TG-1 Stopped)</div><div>&nbsp; - Gas Nomination 330 MMscfd</div><div>&nbsp;&nbsp;</div><div>FGC#1 Trip Investigation- Ongoing Verification. What is the possible root cause of the FGC#1 tripping by "Surge Control Shutdown"</div><div>&nbsp; - The primary suspected is the FIT-1210, which may be malfunctioning.</div><div>&nbsp; - A potential reading error could have been caused by a blocked or leaking impulse line manifold, leading to a drop differential pressure and triggering the shutdown (Flow suction was dropped, as well as the Surge margin dropped)</div><div>&nbsp; - We plan to inspect the impulse line and consider transmitter replacement during the next available maintenance window, currently scheduled for 2 - 22 September 2025, when the FGC#1 is expected to be voluntarily stopped.</div><div><br></div><div>Attending the Meeting with Corporate Team:&nbsp;Vibration Analysis SW System1 Extension for G2N and ART Solution</div><div>&nbsp; &nbsp;- The meeting request that ART-Turbine to collect BN-3500 Rack information of both FGC#1 &amp; FGC#2</div><div><br></div><div><br></div><div><br></div>', NULL, '2025-06-04 13:12:18', '2025-06-04 13:22:30', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'OTHER', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'TawatchaiP.', NULL, 'EXTERNAL', '2025-06-04 13:12:18', '2025-06-04 13:22:30', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
END $$;

