  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai', NULL, 'EXTERNAL', '2025-06-04 13:30:26', '2025-06-04 16:37:57', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
