  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot line break control at ZBV2', 'Electrical & Instrument', 'CM', 'Waiting for Material', '2025-06-05', '<p><b><u>Today Activity&nbsp;</u></b></p><p>Troubleshoot line break control at ZBV2</p><p><br></p><p><b><u>Action</u></b></p><p>Open JB and disconnect battery from JB.</p><p>Charge the battery at ITR room.</p><p>Verify the zone barrier surge protector.&nbsp;</p><p>Found that <span style="background-color: rgb(255, 255, 0);">zone barrier</span> was defective/ ground fault.</p><p>Plan to order spare parts.</p><p><br></p><p><b><u><br></u></b></p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (03.06.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot line break control at ZBV2</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Check marshaling cabinet at ITR room.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found 1 fuse is broken.</span></p><p><span style="background-color: rgb(255, 255, 0);">Open and Check Line break JB at valve pit.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found no LED display and no power supply at PLC unit.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found battery 3.4 VDC.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new spare fuse.</span></p><p><span style="background-color: rgb(255, 255, 0);">But fuse is broken again.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check and verify 24V cable at local and panel side.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found 24V cable is ground fault.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check SPD terminal continuity. (No ground fault)</span></p><p><br></p><p><br></p>', NULL, '2025-06-05 16:22:24', '2025-06-05 16:50:42', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
