  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'YPM on XV-5280', 'Instrument', 'PM', 'Complete', '2025-06-06', '<div>YPM on XV-5280 deluge system.</div><div><p>&nbsp;- PSH: 5284, function tested alarm with the CCR, Set/Reset: 0.49/0.38 brag.&nbsp;</p><p>&nbsp;- Found the solenoid valve of XV-5280 had a deteriorated internal O-ring. Replaced the solenoid valve with a new spare.</p><p>&nbsp;- Calibration checked all pressure gauge.</p><p>&nbsp;- Found that pressure gauge PI-5283 (downstream) was not indicating due to an internal of isolation valve stucked. Further verification required.</p><p>&nbsp;- Activated deluge valve via automation by energizing the solenoid valve. Confirmed proper operation.</p><p>&nbsp;- Leak checked, no leak point found.</p><p>&nbsp;- Cleaned stainer of pilot XV-5280.</p><p>&nbsp;- Pressure tested on air accummulator to ensured that maintain pressure 1 hour without air supply.</p></div>', NULL, '2025-06-06 16:29:18', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-XV-5280', 'GBN-XV-5280', 'DELUGE PACKAGE', NULL, NULL, 'DELUGE PACKAGE', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anuphan', NULL, 'EXTERNAL', '2025-06-06 16:29:18', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL);
