  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 2MPM ZMS instrument air compressor', 'Mechanic', 'PM', 'Completed', '2025-06-06', '<p>Performed Bi-Monthly PM Instrument Air Compressor "A-9200B".</p><p><u><br></u></p><p><u>Working Steps</u></p><p><br></p><p>- Checked and cleaned the air filter.</p><p>- Drained and topped up lube oil AZOLLA ZS 46 (4-Liters)</p><p>- Checked the belt condition and pulley alignment.</p><p>- Checked and tightened the belt tension.</p><p>- Checked and cleaned the radiator.</p><p>- Checked and tightened the loosening bolts and nuts.<br></p><p>- Checked any abnormality and air leakage.</p><p>- Housekeeping and test run.</p><p><br></p><p><u>Required Tools</u></p><p><u><br></u></p><p>Funnel</p><p>Drain Pipe<br>Drain Pail</p><p>Laser Alignment</p><p>Spanner Set</p><p>Screw Driver</p><p>Mallet</p><p>Snoop</p><p>PTFE tape</p><p>Cotton Rags</p>', NULL, '2025-06-06 17:48:49', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
