  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM Replace lube oil cooler fan bearing 2A-5525B', 'Mechanic', 'CM', 'Completed', '2025-06-06', '<p>1. Put new upper and lower bearing on New.</p><p>2. Install shaft with bearing on frame.</p><p>3. Adjust shaft leveling 89.7 degress then tighten bearing mounting.</p><p>4. Set shaft distance then tighten set screw on inner race bearing,&nbsp;</p><p>- Apply loctite.</p><p>5. Reinstall fan pulley and alignment with motor pulley.</p><p>6. Reinstall fan bleade and air shield.</p><p>7. check blade angle and tip clearance.</p><p>- 18 degrees and 2.0 cm as respectively.</p><p>8. Replace 4 each new V-belt and adjust belt tension.</p><p>9. Test run, Normal operation.</p><p><br></p><p><br></p>', NULL, '2025-06-06 17:58:27', CURRENT_TIMESTAMP, 'PTTEP\\KittipongSam', NULL, false, 'G2S') RETURNING id INTO new_report_id;
