  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TEK3200: F&G Test Procedure "C"', 'Instrument', 'PM', 'In Progress', '2025-06-06', '<p data-start="51" data-end="110">TEK3200: F&amp;G Test Procedure "C" (Overall Progress: 50%)</p><p data-start="112" data-end="145">Gas Detector Test Procedures:</p><ul data-start="147" data-end="322"><li data-start="147" data-end="235"><p data-start="149" data-end="235">&nbsp; &nbsp;- Found:&nbsp;The GD-72320 sensor showed low response sensitivity value 25 MV.</p></li><li data-start="236" data-end="322"><p data-start="238" data-end="322">&nbsp; &nbsp;- Action :&nbsp;Replaced the sensor with a new spare and performed re-calibration.</p><p data-start="238" data-end="322"><br></p></li></ul><p data-start="324" data-end="358">Heat Detector Test Procedures:</p><p></p><ul data-start="360" data-end="537"><li data-start="360" data-end="457"><p data-start="362" data-end="457">&nbsp; &nbsp;- Found:&nbsp;The fire dampers (FSL-42500, FSL-42502) did not fully close during activation.</p></li><li data-start="458" data-end="537"><p data-start="460" data-end="537">&nbsp; &nbsp;- Action :&nbsp;Exercised the fire damper flappers and applied lubrication.</p><p data-start="460" data-end="537"><br></p><p data-start="460" data-end="537">Spare part : Item 60.02.28.159.3 COMBUSTIBLE GAS SENSOR,P/N.006824-001.</p></li></ul>', '<span style="font-size: 14px;">Spare part : Item 60.02.28.159.3 COMBUSTIBLE GAS SENSOR,P/N.006824-001.</span>', '2025-06-06 18:15:39', '2025-06-07 15:15:47', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
