-- Inserting report ID 31714
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S dry gas seal  PDIT-3270 reading error', 'Instrument', 'CM', 'Complete', '2025-06-05', '<p data-start="45" data-end="133"><strong data-start="45" data-end="133">T/S Dry Gas Seal Filter Pressure Differential Transmitter (PDIT-3270) Reading Error.</strong></p> <ul data-start="135" data-end="650"> <li data-start="135" data-end="232"> <p data-start="137" data-end="232"><strong data-start="137" data-end="153">Found:</strong> The transmitter displayed a reading of 0.0 psi, while the HMI showed -3.6 psi.</p> </li> <li data-start="233" data-end="346"> <p data-start="235" data-end="346"><strong data-start="235" data-end="252">Action:</strong> Simulated a 4-20 mA signal to the analog I/O module and confirmed the readings were accurate.</p> </li> <li data-start="347" data-end="455"> <p data-start="349" data-end="455"><strong data-start="349" data-end="367">Function Test:</strong> Performed a functional test on the transmitter and confirmed it was operating normally.</p> </li> <li data-start="456" data-end="584"> <p data-start="458" data-end="584"><strong data-start="458" data-end="473">Inspection:</strong> Inspected the wiring and discovered the cable was pinched by the transmitter cover box, causing insulation damage.</p> </li> <li data-start="585" data-end="650"> <p data-start="587" data-end="650"><strong data-start="587" data-end="602">Resolution:</strong> Cut off the damaged cable and re-terminated it.</p> </li> </ul>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/01%20Instrument%20Photos/03.PP/PDIT-3270%20reading%20error?csf=1&amp;web=1&amp;e=xle0Zd">PDIT-3270 reading error</a>', '2025-06-06 18:30:21', '2025-06-06 18:38:57', 'PTTEP\\Turbine', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-K-3200-SE-DE', 'GBN-K-3200-SE-DE', 'DRIVE END DRY GAS SEAL', NULL, NULL, 'DRIVE END DRY GAS SEAL', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
