  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'QP; Perform mechanical MPM lifeboat', 'Mechanic', 'PM', 'Complete', '2025-06-11', '<p>Perform mechanical MPM lifeboat</p><p>-&nbsp; &nbsp; General check, condition and defective in lifeboat.</p><p>-&nbsp; &nbsp; Visual check level at lube oil engine, gear oil, diesel oil.</p><p>-&nbsp; &nbsp; Check and function exercise bilge pump.</p><p>-&nbsp; &nbsp; Visual inspection launching device.</p><p>-&nbsp; &nbsp; Greasing all moving parts.</p><p>-&nbsp; &nbsp; Function start engine by electrical motor, hydraulic / mechanical starter and test run 10 minute.</p><p>-&nbsp; &nbsp; Cleaning inside lifeboat.</p><p><br></p><table class="table table-bordered"><tbody><tr><td>Description&nbsp; /&nbsp; Master point</td><td>No.1</td><td>No.2</td><td>No.3</td><td>No.4</td></tr><tr><td><p>Pressure of air cylinder 1 (Psi)</p><p>Pressure of air&nbsp;cylinder 2 (Psig)</p></td><td><p>4000</p><p>4000</p></td><td><p>4000</p><p>4000</p></td><td><p>4000</p><p>4000</p></td><td><p>2600</p><p>3000</p></td></tr><tr><td>Fuel tank level (%)</td><td>95&nbsp;</td><td>75</td><td>80</td><td>85</td></tr><tr><td>Lube oil engine(%)</td><td>100</td><td>100</td><td>100</td><td>100</td></tr></tbody></table><p><br></p>', '<p>Master point No.3&nbsp;</p><p>- Expired drinking water.</p><p>- Unable to start engine with battery at first time but after start with Spring starter it can start with battery.&nbsp;</p><p><br></p><p>Master point No.4</p><p>- Unable to start engine with battery at first time but after start with Spring starter it can start with battery.</p><p>- Pressure of air cylinder lower than normal.</p><p>&nbsp;</p>', '2025-06-11 16:53:17', '2025-06-11 16:53:32', 'PTTEP\\Mech_WS', 'PTTEP\\Mech_WS', false, 'G2N') RETURNING id INTO new_report_id;
