  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S RVP AIT-1840 reading malfunction.', 'Instrument', 'CM', 'Completed', '2025-06-13', '<p>T/S  RVP AIT-1840 reading malfunction.</p><p>- Found AI1840_ANN (RVP Freezing Alarm) on 02/05/2025 - 21.05 in DCS&nbsp;</p><p><br></p><p><br></p><p>- Found RVP display Failure - Purge Pressure Out of Specification by Measure Value 4.5 psi (Range Spec 5-15 psi)</p><p>&nbsp;&nbsp;<br></p><p><br></p><p>- Try to reset cycle (SW2) and also reset system (SW1) but unit still failure.</p><p>- As Found N2 Purge Pressure was around 20 psi (1.3 bar) and observed pressure dropped to 17 psi in sometime.</p><p></p><p><br></p><p>- Found lock nut on adjust screw of regulator was loosen, then adjust regulator from 1.3 Bar to 1.6 Bar (23 psi), RVP is reading as normal around 11.19 psi</p><p>&nbsp;&nbsp;<br></p><p><br></p><p><br></p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FRVP%5FAE%2D1840%2F20250613%5FRVP%5FFreezing&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250613_RVP_Freezing - Picture</a><br></p>', '2025-06-13 18:17:14', '2025-06-13 18:50:50', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
