-- Inserting report ID 32052
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S HypoChlorinator A-4670 tripped by Low Air Flow', 'Instrument', 'CM', 'In Progress', '2025-06-14', '<p>266x199
T/S HypoChlorinator A-4670 tripped by Low Air Flow Blower-A Alarm (FAL = 500 NCMH).</p><p>- Found Low Air Flow BlowerA or B Alarm on HMI since 13/6/2025 - 8:19</p><p></p><p><br></p><p>- Connected Laptop via USB type-B for verify config parameter which found;</p><p>&nbsp;</p><p><br></p><p> </p><p>Pipe Size Diameter (ID) = 154.051 mm (6.06 inch)</p><p></p><p><br></p><p>Max Flow Range = 978.9999 NCMH (Normal Cubic Meter per Hour) or 576 SCFM</p><p><br></p><p></p><p><br></p><p>then changed Max Flow to 850 NCMH (500 SCFM) follow Eng-Calibration Data&nbsp; &nbsp;</p><p><br></p><p>- Perform Diagnostics Loop Test which found normal condition.</p><p>&nbsp;&nbsp;</p><p><br></p><p>- Function test by Blower-A (BM-4675 Lowest Efficiency), it able to make up flow around 480-500 NCMH&nbsp;</p><p>with out Low Air Flow Alarm, observed indicator is more than half scale (Analog Output 12 mA)&nbsp;</p><p></p><p><br></p><p>- Try to change Max Flow Range 850 NCMH back to As Found 978.999 NCMH and function test by Blower-A again that found Flow reading is around 480-500 NCMH same as recently but AO is below 12 mA cause to Low Air Flow Alarm and blower tripped. Suspected Flow in system migth be blocked or reduced from normal operation.</p><p></p><p><br></p><p>- Try to adjust Pipe Size Diameter from 154.051 mm (6 inch) to 180 mm (7 inch) for increasd volume flow,&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp;<br></p><p><br></p><p>- Function test by Blower-A (BM-4760), Flow reading is increase to 690 NCMH and AO is up to 15 mA</p><p>&nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p><p>- Fonction test by Blower-B (BM-4675), Flow reading is increase to 800 NCMH</p><p>&nbsp; &nbsp; &nbsp;&nbsp;</p><p><br></p><p>Hypochlorinator unit able to operated without Low Air Flow Blower Alarm, keep monitoring.</p><p><br></p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FHypoChloride%5FA%2D4670%2F20250613%2D14%5FHypo%5FLowAirFlow&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250613-14_Hypo_LowAirFlow</a><br></p>', '2025-06-14 09:27:35', '2025-06-15 17:52:25', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-4670', 'ART-A-4670', 'HYPOCHLORINATOR PACKAGE', NULL, NULL, 'HYPOCHLORINATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Chaowalit S.', NULL, 'EXTERNAL', '2025-06-14 09:27:35', '2025-06-15 17:52:25', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong I.', NULL, 'EXTERNAL', '2025-06-14 09:27:35', '2025-06-15 17:52:25', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
