  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2KPM on G-9110 Day 3', 'Mechanic', 'PM ', 'In Progress', '2025-06-14', '<p>Job Description : 2KPM on G-9110 Day 3</p><p><br></p><p>Job Steps :</p><p><br></p><p>- Performed electrical and process isolation.</p><p>- Removed rocker arms cover boxes and check the leakage and damage.</p><p>- Installed fly wheel turner and adjust the valves rocking position.</p><p>- Checked valve gap as per instruction manual. (0.016 in).</p><p>- Removed the old gaskets and installed the new ones at cover boxes.</p><p>- Checked the spark plug conditions and wiring conditions.</p><p>- Checked the alternator condition and inspected.</p><p>- Removed the belt and replaced with a new one of the alternator.</p><p>- Visual check around the generator and housekeeping.</p><p>- Performed de isolations and test run.</p><p><br></p><p>Status : ONLINE.</p>', NULL, '2025-06-14 16:20:04', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
