  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2025-06-14 16:20:04', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Junior', NULL, 'EXTERNAL', '2025-06-14 16:20:04', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL);
