-- Inserting report ID 32082
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM Perform 1Y PM Trolley hoist 2MHE-5521', 'Mechanic', 'PM', 'Completed', '2025-06-14', '<p>1.&nbsp;Check screw and bolts for tightening.</p><p>2.&nbsp;Check the trolley unit and load beam for corrosion.</p><p>3. Remove any deposits of dust.</p><p>4. Check the functioning of the brake. (Usually must be hold the load when stop&nbsp;</p><p>operation)</p><p>&nbsp; &nbsp; &nbsp;Function test</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Move forward OK</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Move backward OK</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Hoist up OK</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Hoist down OK</p><p>&nbsp; &nbsp; &nbsp;Function limit switch</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Move forward OK</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Move backward OK</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Hoist up OK</p><p>&nbsp; &nbsp; &nbsp; &nbsp; - Hoist down OK</p><p>5. Lubricate and clean the load chain.</p><p>6. Check the load chain for elongation and wear.</p><p>7. Check the suspension eye and load hook for cracks and deformation.</p><p>8. Check and lubricate the bearings of the chain pulleys.</p><p>9. Check/Change the oil in the lifting gearbox.</p><p>10. Check the trolley wheels for wear.</p><p>11. Check the teeth of the trolley wheels.</p><p>12. Check and lubricate on the driving pinions.</p><p>13. Check trolley push button pendant condition.</p><p><br></p>', '<p>Photo Link :&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/6.%20Picture/61.%20PPS%20Equipment%20Picture/Lifting%20gear/2MHE-5521/2025.06.14%20Perform%201Y%20PM?csf=1&amp;web=1&amp;e=cCboVk" style="background-color: rgb(255, 255, 255); font-size: 15px;">2025.06.14 Perform 1Y PM</a></p><p><br>Total Carter SY 220</p><p>Grease PTT EP-2</p><p><br></p><p>Monitor : Air supply hose kinked, But not found leak point.</p><br>', '2025-06-14 19:34:00', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2MHE-5521', 'GBS-2MHE-5521', 'TROLLEY HOIST 25MT', NULL, NULL, 'TROLLEY HOIST 25MT', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
