-- Inserting report ID 32184
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Hg Anlyzer AIT-1681 reading Err', 'Instrument', 'CM', 'In Progress', '2025-06-16', '<p>T/S Hg Anlyzer AIT-1681A (High Range) at MRU (Temporary Reading at Bottom of Vessel V-1120) reading error.</p><p>- Found AI1681 Freezing Alarm several time and Reading Value of AIT-1681A was decreased from 100 ug/m3 normal operation to 2 ug/m3 on 8/6/2025, 20:34 and VM-3000 (High Range Analyzer) is showing 2 ug/m3</p><p></p><p>- Verified condition of sampling from impulse line XSC-1121 (Bottom of Vessel V-1120) via temporary selector valve to Sample Conditioning System SCS-1120 (Stream-A / High Range) that found pressure and flow are normal.</p><p>- Trial to select mercury source from normal sampling point (Inlet MRU / Top of Vessel V-1120/30) which is higher than the value of temporary point (Bottom of V-1120/30), but reading value is still low. Then selected back to desired temporary point.</p><p>- Verified wiring terminal and tubing inside VM-3000 include sampling pump, found all condition is normal.&nbsp;</p><p>- Validated by MC-3000 Mercury Generator to VM-3000 (High Range) that found the result is too low and not linear.</p><p>Inprogress</p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FAnalyzer%5FOGC%5FGasCylinder%2FAIT%2D1681%5FHg%2F20250616%2D17%5FAIT%2D1681A%5FRd%5FErr&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250616_AIT-1681A_Rd_Err</a><br></p>', '2025-06-16 19:05:08', '2025-06-22 10:28:58', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-AT-1681A', 'ART-AT-1681A', 'ANALYSIS TRANSMITTER', NULL, NULL, 'ANALYSIS TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong I.', NULL, 'EXTERNAL', '2025-06-16 19:05:08', '2025-06-22 10:28:58', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
