-- Inserting report ID 32380
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting a Mercury Analyzer (2AIT-39913) ', 'Instrument', 'CM', 'In Progress', '2025-06-20', '<p>Troubleshooting a Mercury Analyzer (2AIT-39913)&nbsp;</p><p>1. Battery Replacement:</p><p>Issue: Low voltage of microprocessor battery at 3.2V (normal spec is likely 3.6V).</p><p>Action: Replaced battery with a new 3.6V one.&nbsp;</p><p>2. Cleaning Sampling Rotameter &amp; Optical Cell:</p><p>Issue: Clogged or dirty rotameter or optical cell could affect readings.</p><p>Action: Cleaning these components is essential. Ensure the rotameter is free of obstructions, and the optical cell is thoroughly cleaned</p><p>3. Assembly Check:</p><p>Issue: Incorrect positioning of components such as the sampling pump tubing, clamps, and ferrules could affect functionality.</p><p>Action: Reassembly in the correct position is essential. Check if the ferrules and clamps are tight, ensuring there are no air leaks or loose components.</p><p>4. Optical Bench Replacement:</p><p>Issue: Alarm indicating voltage over 8.5V (Spec is 5V) suggests a malfunction of the optical bench.</p><p>Action: Replacing the optical bench.</p><p>5. Display is Dark:&nbsp;</p><p>Issue: After powering on the unit, the display is not turning on.</p><p><br></p><p>- Under investigate</p>', NULL, '2025-06-20 17:31:56', '2025-06-20 17:35:35', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2AIT-39913', 'GBS-2AIT-39913', 'HG ANALYZER INDICATOR TRANSMITTER', NULL, NULL, 'HG ANALYZER INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-06-20 17:31:56', '2025-06-20 17:35:35', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ILAB FLUID Vendor.', NULL, 'EXTERNAL', '2025-06-20 17:31:56', '2025-06-20 17:35:35', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
END $$;

