  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PIG was transferred from WPS20', 'ROMO', 'ROMO', 'Completed', '2025-06-20', '<p>1.PIG was transferred from WPS20 to WPS15 using 200 liters of CI.</p><p>&nbsp;</p><p>2.Gas sampling during the operation. The results indicated CO2 at 27% and H2S concentration at 7 ppm.</p><p>&nbsp;</p><p>3.T/S SSV-G03 wing valve limit switch fault alarm.</p><p>-Found water inside the limit switch and fuse was blown.</p><p>Action:</p><p>-Cleared water from the limit switch and re-terminated cables</p><p>-The blown fuse was replaced with a new one.</p><p> -Function test was found to be operating properly.</p>', NULL, '2025-06-21 06:35:25', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong', NULL, 'EXTERNAL', '2025-06-21 06:35:25', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Katawoot', NULL, 'EXTERNAL', '2025-06-21 06:35:25', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL);
END $$;

