-- Inserting report ID 32401
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WPS20 SBT Operation', 'ROMO', 'ROMO', 'Completed', '2025-06-20', '<p>1.Collected a sample from the BKS-20L test separator and checked CO2 = 27% and H2S = 7 ppm.</p><p>2.Pigging operation was luncher&nbsp;from WPS20 to WPS15 using 200 liters of CI.</p><ul type="disc">  <li>Launched      the BIDI pig at 13:44, filled CI 200 L, and launched the Splash pig at      14:25.</li> </ul><p>  Pic :&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-20/2025/2025-06-20_Activity%20report/WPS-20%20Pig%20before%20launcher?csf=1&amp;web=1&amp;e=Cjk88S">WPS-20 Pig before launcher</a></p><p><br></p><ul type="disc">  <li>3.Cleaned      the test separator strainer parts (condensate) and found approximately 30%      blockage.</li> </ul><p>  </p><p>Pic: <a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-20/2025/2025-06-20_Activity%20report/WPS-20%20Clean%20strainer%20test%20separator%20condy%20parts?csf=1&amp;web=1&amp;e=AILYCQ">WPS-20 Clean strainer test separator condy parts</a></p><p><br></p><p>4.<span style="background-color: rgb(255, 255, 0);">T/S SSV-G03 </span>wing valve limit switch fault alarm.</p><p>-Troubleshot the BKS-20G wing valve (SSV-G03) due to a valve status fault when commanding open.</p><p>Action:</p><p>-Cleared water from the limit switch and re-terminated cables</p><p><span style="background-color: rgb(255, 255, 0);">-The blown fuse was replaced with a new one.</span></p><p></p><p>&nbsp;-Function test was found to be operating properly.</p><p>Pic: <a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-20/2025/2025-06-20_Activity%20report/WPS-20%20Troubleshoot%20SSV-G03%20(BKS-20G%20wing%20valve)?csf=1&amp;web=1&amp;e=0WeIVo">WPS-20 Troubleshoot SSV-G03 (BKS-20G wing valve)</a></p><p><br></p><ul type="disc">  <li>Surveyed      the water and diesel storage tanks.</li> </ul><p>  </p><p>Pic: <a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-20/2025/2025-06-20_Activity%20report/WPS-20%20Water%20and%20Diesel%20Storage%20tank?csf=1&amp;web=1&amp;e=Tkt3dH">WPS-20 Water and Diesel Storage tank</a></p><p><br></p>', NULL, '2025-06-21 06:50:41', '2025-06-21 18:28:34', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WP20', 'GBS-WP20', 'BONGKOT SOUTH WELLHEAD PLATFORM WPS20', NULL, NULL, 'BONGKOT SOUTH WELLHEAD PLATFORM WPS20', 'GBS-WP20', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong', NULL, 'EXTERNAL', '2025-06-21 06:50:41', '2025-06-21 18:28:34', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
