-- Inserting report ID 32403
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Continue_Troubleshooting a Mercury Analyzer (2AIT-', 'Instrument', 'CM', 'In Progress', '2025-06-21', '<div>Continue_Troubleshooting a Mercury Analyzer (2AIT-39913)_Continue day 2</div><div><br></div><div>1.Maintenance Actions:</div><div>- Replaced Membrane Pump</div><div>- Replaced Gold Trap</div><div>- Replaced Sampling Filter Element</div><div><br></div><div>2. Calibration Data Reconfiguration</div><div>- Calibration data was lost due to low microprocessor battery voltage.System calibration parameters were reconfigured.</div><div>- Checked Flows:</div><div>Heating Flow: 10.2 l/h&nbsp; (Acceptable Range: 7.0–13.0 l/h)</div><div>Sampling Flow: 40.2 l/h (Acceptable Range: 35.0–45.0 l/h)</div><div><br></div><div>3.Pre-Calibration Span Check repetibility</div><div>Target Concentration: 200 pgHg</div><div>Test Cycles: 12</div><div>Measured Results (pgHg):</div><div>333, 317, 306, 301, 298, 297, 295, 294, 295, 295, 293, 294</div><div>Average: 295.6 pgHg</div><div>Observation: Analyzer over-reported by approximately +48% prior to calibration.</div><div><br></div><div>4. 8-Point Calibration Performed</div><div>- Calibration Concentrations (pgHg): 0, 200, 400, 600, 800, 1000, 2000, 3000</div><div>- Calibration successfully covered low, medium, and high range concentrations, providing full-scale linearity.</div><div>- Calibration Curve Equation: Y = 0.0000902 + 0.00056X</div><div>- Calibration Linearity (R²): 0.99907 (Meets required accuracy threshold)</div><div><br></div><div>5. Post-Calibration Verification</div><div>- Span check repeated at 500 pgHg after calibration (Test 3 cycles). Measured Average Result: 513 pgHg&nbsp;</div><div>- Continue observing analyzer performance over the next 24–48 hours to ensure stability.</div>', NULL, '2025-06-21 14:01:14', '2025-06-23 09:25:00', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2AIT-39913', 'GBS-2AIT-39913', 'HG ANALYZER INDICATOR TRANSMITTER', NULL, NULL, 'HG ANALYZER INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-06-21 14:01:14', '2025-06-23 09:25:00', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ILAB FLUID Vendor.', NULL, 'EXTERNAL', '2025-06-21 14:01:14', '2025-06-23 09:25:00', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT');
