-- Inserting report ID 32412
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Reinstall regen gas blower', 'Mechanic', 'CM', 'Completed', '2025-06-25', '<p>21 June 2025</p><p>- Reinstall regen gas blower.</p><p><br></p><p>25 June 2025</p><p>- Replace incorrect material gasket.</p><p>&nbsp; &nbsp;1. RTJ R12 size 1/2"# 900/1500 = 5 ea. and apply JIMS.</p><p>&nbsp; &nbsp;2. RTJ R16 size 1"# 900/1500 = 1 ea. and apply JIMS.</p><p><br></p>', '<p>Reinstall regen gas blower after&nbsp;overhaul.</p><p><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">1. Set up lifting gear.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">2. Remove blind flange.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">3. Install regen gas blower.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">4. Install lube oil piping and apply JIMS.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">5. Install hob of regen gas blower.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">6. Install motor and alignment.</span></p><p><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">7.Started test motor direction.</span></p><p><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">8.</span><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">Replace lube oil gear box TERBIN46.and replace oil filter .</span><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);"><br></span><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">9. Torque coupling bolt 87.2 NM.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">10. Perform alignment and check end gap 34.2 mm. (TOHMAS coupling size 263)</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">- minimum end gap = 30.97 mm.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">- Normal end gap = 33.35 mm.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">- maximum end gap = 35.73 mm.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">11. Replace lube oil gear box TERBIN46.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><br></p>', '2025-06-21 16:07:05', '2025-06-25 13:46:06', 'PTTEP\\art.mechcrane', 'PTTEP\\Art.MechBC', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-B-2420', 'ART-B-2420', 'REGENERATION GAS BLOWER UNIT TRAIN 2', NULL, NULL, 'REGENERATION GAS BLOWER UNIT TRAIN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
