  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2UCP-5510 HMI Replacement and Logic Modification', 'Instrument', 'MD', 'In Progress', '2025-06-21', '<p data-start="68" data-end="148"><b>2UCP-5510 HMI Replacement and Logic Modification for VFD Replacement</b></p><p data-start="870" data-end="931">- Re-checking the Graphics of Existing HMI and New HMI</p><ul data-start="933" data-end="1418"><li data-start="933" data-end="1060"><p data-start="935" data-end="1060">- A thorough comparison between the graphical elements of the current 2UCP-5510 HMI and the proposed new HMI will be conducted.</p></li><li data-start="1061" data-end="1170"><p data-start="1063" data-end="1170">- Existing graphics will be evaluated for accuracy, clarity, and usability in relation to the new VFD system.</p></li><li data-start="1171" data-end="1294"><p data-start="1173" data-end="1294">- An assessment will be made to ensure the new HMI can handle the updated requirements and offer improved user interaction.</p></li><li data-start="1295" data-end="1418"><p data-start="1297" data-end="1418">- The goal is to identify any graphical discrepancies, missing elements, or areas that need additional visual enhancements.</p></li></ul><ul data-start="1462" data-end="1907"><li data-start="1462" data-end="1623"><p data-start="1464" data-end="1623">- The vendor will be expected to make these changes in a timely manner, ensuring the final HMI meets operational standards and user expectations.</p></li></ul><p data-start="1909" data-end="1967"><b>&nbsp;Recommendations for Additional Important Graphics</b></p><ul data-start="1969" data-end="2454"><li data-start="1969" data-end="2155"><p data-start="1971" data-end="2155">- During the review, recommendations will be made for adding key graphic elements that enhance functionality, improve user experience, and facilitate better monitoring of the VFD system.</p></li><li data-start="2156" data-end="2308"><p data-start="2158" data-end="2308">- Suggestions may include adding more intuitive symbols, clearer status indicators, and better visual feedback for system health, alarms, and operation.</p></li><li data-start="2309" data-end="2454"><p data-start="2311" data-end="2454">- Enhancements will focus on making the HMI more user-friendly, ensuring operators can quickly interpret the data and take action when necessary.</p></li></ul><p data-start="2456" data-end="2472"><br></p>', NULL, '2025-06-21 17:16:49', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL, false, 'G2S') RETURNING id INTO new_report_id;
