  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'G8930 can''t start with under RPM alarm Day 2', 'Electrical & Instrument', 'CM', 'In Progress', '2025-06-21', '<p><b><u>Today Activity:</u></b></p><p>G8930 can''t stop with under RPM alarm Day 2</p><p><b><u><br></u></b></p><p><b><u>Action</u></b></p><p>Replace new timing sensor</p><p>Install digital pressure gauge at doghouse regulator side.</p><p>Adjust fuel regulator 17Kpa to 15 Kpa.</p><p>Connect with laptop to monitor speed control and ignition control.</p><p>Test run with battery charger.</p><p>G8930 still can''t start without alarm.</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (20.06.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8930 can''t stop with low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Remove and check low RPM sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found dirty and few scratch.</span></p><p><span style="background-color: rgb(255, 255, 0);">Clean, re-install back and test run G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new sensor and test run G8930</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 under rpm alarm is cleared but can''t start without alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to troubleshoot tomorrow.&nbsp;</span></p><p><br></p><p><br></p>', NULL, '2025-06-22 11:05:55', '2025-06-22 18:38:42', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930-PACK', 'ATL-OC-G-8930-PACK', 'Gen, ZOC Gas Generator Package 3', NULL, NULL, 'Gen, ZOC Gas Generator Package 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nobel', NULL, 'EXTERNAL', '2025-06-22 11:05:55', '2025-06-22 18:38:42', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2025-06-22 11:05:55', '2025-06-22 18:38:42', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '18.71.91.013.3', 'G8930 can&#39;t start with under RPM alarm Day 2', '1', '2025-06-22 11:05:55', '2025-06-22 18:38:42', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
