  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'A-3330A Gas cooler fan Verify strange noise  ', 'Mechanic', 'CM', 'Complete', '2025-06-21', '<p>A-3330A gas cooler fan verify strange noise and Perform mechanical 6MPM</p><p>Found : Belt bad condition&nbsp;</p><p>Check pulley motor and fan normal&nbsp;&nbsp;</p><ul type="disc"><li>Visual general checked (screens, shaft and bearing); found all them are in good condition.</li></ul><p></p><ul type="disc"><li>Greased both bearing while running.</li><li>Alignment checked was found good condition</li><li>Replace new belt&nbsp;</li><li>Checked the tensioning of belt by used the tension measurement tools. (Frequency 32 Hz.)</li><li>Checked condition of anti-rotation was still in good condition.</li><li>Checked blades angle and blades tip gap</li><li>Checked bolts torque were still in specification as table below.</li><li>General cleaned and inspected.</li><li>Clean up working area.</li></ul><p><br></p><p></p><p></p><p><br></p><table border="1" cellspacing="0" cellpadding="0" align="left">  <tbody><tr>   <td width="81" valign="bottom">   <p align="right">Point&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; Blade</p>   </td>   <td width="54">   <p align="center">N</p>   </td>   <td width="54">   <p align="center">E</p>   </td>   <td width="54">   <p align="center">S</p>   </td>   <td width="54">   <p align="center">W</p>   </td>   <td width="92">   <p align="center">Remark</p>   </td>  </tr>  <tr>   <td width="81" valign="top">   <p>1</p>   </td>   <td width="54" valign="top">   <p align="center">15</p>   </td>   <td width="54" valign="top">   <p align="center">11</p>   </td>   <td width="54" valign="top">   <p align="center">23</p>   </td>   <td width="54" valign="top">   <p align="center">11</p>   </td>   <td width="92" rowspan="6">   <p align="center">STD.</p>   <p align="center">3-19 mm.</p>   <p align="center">¼” – ¾”</p>   </td>  </tr>  <tr>   <td width="81" valign="top">   <p>2</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>  </tr>  <tr>   <td width="81" valign="top">   <p>3</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>  </tr>  <tr>   <td width="81" valign="top">   <p>4</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>  </tr>  <tr>   <td width="81" valign="top">   <p>5</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>  </tr>  <tr>   <td width="81" valign="top">   <p>6</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>   <td width="54" valign="top">   <p align="center">-</p>   </td>  </tr> </tbody></table><p><br></p><p><br></p><ul type="disc"></ul>', NULL, '2025-06-22 17:33:18', '2025-06-22 18:19:49', 'PTTEP\\Mech_WS', 'PTTEP\\Mech_WS', false, 'G2N') RETURNING id INTO new_report_id;
