-- Inserting report ID 32517
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'G8930 can''t start with under RPM alarm Day 3', 'Electrical & Instrument', 'CM', 'In Progress', '2025-06-23', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot Gas Generator G-8930 cannot start.</p><p><br></p><p><b><u>Action</u></b></p><p>1.Adjust fuel pressure from 15kpa to 20kpa.</p><p>2.Connect to the AFI with laptop.</p><p>3.Generator Starting with Battery Bank 1 with Battery Starter.</p><p>4.Gas Generator still cannot start.</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G-8930 can''t stop with under RPM alarm Day 2</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Replace new timing sensor</span></p><p><span style="background-color: rgb(255, 255, 0);">Install digital pressure gauge at doghouse regulator side.</span></p><p><span style="background-color: rgb(255, 255, 0);">Adjust fuel regulator 17Kpa to 15 Kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">Connect with laptop to monitor speed control and ignition control.</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run with battery charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 still can''t start without alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (20.06.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8930 can''t stop with low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Remove and check low RPM sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found dirty and few scratch.</span></p><p><span style="background-color: rgb(255, 255, 0);">Clean, re-install back and test run G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new sensor and test run G8930</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 under rpm alarm is cleared but can''t start without alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to troubleshoot tomorrow.&nbsp;</span></p><p><br></p><p><br></p>', NULL, '2025-06-23 17:27:50', '2025-06-23 17:58:38', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
