BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2SDV-19981_Overhaul valve', 'Instrument', 'PM', 'Completed', '2025-06-24', '<p>09:30 - Preparing to support SNU to stroke test the valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2XA-19995 (Alarm All TEGs Not Run)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install line by-pass the SDV and open by-pass valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Platform live normaly</p><p><br></p><p>09:40 - Stroke test valve ESDV-19981 and perform overhaul</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Self isolation IG valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed the valve actuator</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Cleaning valve stem and valve body</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Installed a new actuator</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Check performance the solenoids</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced a new pressure gauge of IG</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Normalize IG valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Stroke test the valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Valve back to normal</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed all inhibit</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed line by-pass</p><p>10:30 - Job completed</p><p><br></p><p>Picture :&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-9/2025/2025-06-24_WPS-09_Activity%20picture/2025-06-24_WPS-09_2SDV-19981%20Valve%20overhaul?csf=1&amp;web=1&amp;e=71dUAB" style="background-color: rgb(255, 255, 255);"><u>2025-06-24_WPS-09_2SDV-19981 valve overhaul by SNU</u></a></p><p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-9/2025/2025-06-24_WPS-09_Activity%20picture/2025-06-24_WPS-09_2SDV-19981%20Valve%20overhaul?csf=1&amp;web=1&amp;e=71dUAB" style="background-color: rgb(255, 255, 255);"><u><br></u></a></p>', '<p>Link more picture:&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-9/2025/2025-06-24_WPS-09_Activity%20picture/2025-06-24_WPS-09_2SDV-19981%20Valve%20overhaul?csf=1&amp;web=1&amp;e=amZxOv">2025-06-24_WPS-09_2SDV-19981 valve overhaul by SNU team</a><br></p>', '2025-06-24 11:36:07', '2025-06-24 13:44:39', 'PTTEP\\GBS.Production-Oper', 'PTTEP\\GBS.Production-Oper', false, 'G2S') RETURNING id INTO new_report_id;
