-- Inserting report ID 32543
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C) WPS-19 Daily Activities Report.', 'ROMO', 'ROMO', 'Completed', '2025-06-24', '<p>WPS-19 Daily Activities Report.</p>  <p><span style="background-color: rgb(255, 255, 0);">7:40.</span>&nbsp;Top up VCI from 18.7% to 79.8% completed, VCI tote tank No.BS32012 remaining level 0% and plan to return to PPS this evening. Updated status to consumable file.</p><p><br></p>  <p><span style="background-color: rgb(255, 255, 0);">8:20</span>&nbsp;First Aid Inspection. It last inspection 31/4/25 return the first aid kit back to QPS</p>  <p>&nbsp;</p>  <p><span style="background-color: rgb(255, 255, 0);">8:25&nbsp;</span>Hydrocabon release survey no leak.</p>  <p>&nbsp;</p>  <p><span style="background-color: rgb(255, 255, 0);">9:00</span>.&nbsp;<span style="background-color: rgb(255, 0, 0);">T/S ACDB-410 Fault Alarm.</span></p>  <p>-Found HMI displayed fault alarm for ACDB-410.</p>  <p>-Check all breakers on ACDB-410 were checked and confirmed to be in the closed</p>  <p>-Check main 380Vac supply was measured and found to be at 0 volts.</p>  <p>-Root cause identified as no power supply from the generator. Under-voltage protection was activated, which triggered the alarm signal to the PLC.</p>  <p>-Pending job. It function test to be performed by supplying power from a mobile generator if required.</p>  <p>&nbsp;</p>  <p><span style="background-color: rgb(255, 255, 0);">11:00</span>&nbsp;Performed test separator level flushing.</p>  <p>&nbsp;</p>  <p><span style="background-color: rgb(255, 255, 0);">13:30</span>&nbsp;Perform sampling downstream of BK-S19-P during ramp-up for sand check.</p>  <p>-CHV @ 70%: No sand found.</p>  <p>-CHV @ 80%: No sand found.</p>  <p>-CHV @ 90%: Found some objects</p>  <p>&nbsp;</p>  <p><span style="background-color: rgb(255, 255, 0);">15:00</span>- Perform valve LO/LC check list.</p>  <p>&nbsp;-Perform routine monthly platform survey.</p>  <p>&nbsp;- Perform routine sump pump integrity test, good condition.</p>  <p>&nbsp;- Perform routine collect SRB sample.</p>  <p>&nbsp;- Perform routine test separator level flushing.</p>  <p>&nbsp;</p>', NULL, '2025-06-24 12:10:46', '2025-07-20 14:16:14', 'PTTEP\\GBS.Production-Oper', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WP19', 'GBS-WP19', 'BONGKOT SOUTH WELLHEAD PLATFORM WPS19', NULL, NULL, 'BONGKOT SOUTH WELLHEAD PLATFORM WPS19', 'GBS-WP19', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
