  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Samruay', NULL, 'EXTERNAL', '2025-06-24 12:10:46', '2025-07-20 14:16:14', 'PTTEP\\GBS.Production-Oper', 'PTTEP\\GBS.EI-Workshop');
