BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2SDV-19321 valve overhaul', 'Instrument', 'PM', 'Completed', '2025-06-23', '<p></p><p>09:30 - Preparing to shutdown platform and support SNU to stroke test the valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PALL-19812 (Fusible Plug)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PALL-19818 (Manual ESD Station)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PT-19201A (Export pipe line pressure)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PT-19201B (Export pipe line pressure)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2ZSH-19211A (Export Riser valve position)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2ZSH-19211B (Export Riser valve position)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2ZSH-19211C (Export Riser valve position)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2ZSH-19221 (not open status of receiving)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2ZSH-19212 (Tie-In valve not open)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PT-19223 (Receiving pipe line pressure)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2XS-19060B (Inter trip ESD-1)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2XS-19061B (Inter trip ESD-2)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2XS-19062B (Inter trip ESD-3A)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PT-19331 (IG pressure filter outlet)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PT-19325 (IG filter pressure)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inhibit 2PT-19107 (Test separator pressure)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install plug at vent port of 2ESDV-19212</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install plug at vent port of 2ESDV-19221</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Open 2" valve gas supply from Test separator to IG</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- WPS-11 Platform live normaly</p><p><br></p><p>10:40 - Stroke test valve 2SDV-19321 and perform overhaul</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Self isolation IG valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed the valve actuator</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Cleaning valve stem and valve body</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Installed a new actuator</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Check performance the solenoids</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced a new pressure gauge of IG</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Normalize IG valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Stroke test the valve</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Valve back to normal</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed all inhibit</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed all plug vent port</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed close valve gas supply from Test separator</p><p><br></p><p>11:40 - Valve 2SDV-19321 overhaul and function tests completed.</p><p><br></p>', NULL, '2025-06-24 13:41:17', '2025-06-24 13:43:53', 'PTTEP\\GBS.Production-Oper', 'PTTEP\\GBS.Production-Oper', false, 'G2S') RETURNING id INTO new_report_id;
