  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2ESDV-19221_Overhaul valve', 'Instrument', 'PM', 'Completed', '2025-06-24', '<p>11:20 &nbsp; - Preparing to stroke test 2ESDV-19212 and 2ESDV-19221.</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Inform CCR to shut all well at WPS-11</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Inhibit 2ZSH-19221 (Valve Not Open)</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Inhibit 2ZSH-19212 (Valve Not Open)</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Inhibit 2PT-19223 (Receiving pipe line pressure)</p><p>&nbsp;</p><p>11:30 &nbsp; - Stroke test valve 2SDV-19221</p><p>11:40 &nbsp;&nbsp;- Stroke test valve 2SDV-19212 and perform overhaul</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Self isolation IG valve</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Removed the valve actuator</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Cleaning valve stem and valve body</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Installed new internal parts actuator</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Check performance the solenoids</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Replaced a new pressure gauge of IG</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Normalize IG valve</p><p>14:50 &nbsp;&nbsp;- Stroke test the valve</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Valve back to normal</p><p> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Removed all inhibit</p><p>15:10&nbsp;&nbsp;&nbsp;- Inform CCR to normalized platform WPS-11.</p><p></p><p>15:15 &nbsp;&nbsp;- WPS-11 Platform resume and produce.</p><p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-9/2025/2025-06-24_WPS-09_Activity%20picture/2025-06-24_WPS-09_2SDV-19981%20Valve%20overhaul?csf=1&amp;web=1&amp;e=71dUAB"><u><br></u></a></p>', '<p>Link more picture:&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-9/2025/2025-06-24_WPS-09_Activity%20picture/2025-06-24_WPS-09_2ESDV-19221%20valve%20overhaul?csf=1&amp;web=1&amp;e=0IrAdh">2025-06-24_WPS-09_2ESDV-19221 valve overhaul</a><br></p>', '2025-06-24 15:17:49', '2025-06-24 21:47:18', 'PTTEP\\GBS.Production-Oper', 'PTTEP\\GBS.Production-Oper', false, 'G2S') RETURNING id INTO new_report_id;
