-- Inserting report ID 32569
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Download change gas metering valve.', 'Instrument', 'MD', 'Completed', '2025-06-24', '<p>Download change configuration setting of fuel gas metering valve.</p><div class="ewa-rteLine">- Change position error threshold and delay settings from 1%, 500 mSec to 5%,100 mSec as per standard value SIC00223.</div><div class="ewa-rteLine">- Functional test by command from control system.</div><div class="ewa-rteLine">- Start-up unit back to normal operation.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">Step to download.</div><div class="ewa-rteLine">1. connect laptop Back-up old setting by save from device to file menu.</div><div class="ewa-rteLine">2. Edit setting file and change parameter then save to new file with new setting.</div><div class="ewa-rteLine">3. Compare between new file and old file for confirm parameter changed.</div><div class="ewa-rteLine">4. Load setting file to device with new file setting.</div><div class="ewa-rteLine">5. Save file from device and compare and compare with new file with new setting the result must be not different.</div><div class="ewa-rteLine">6. Function test by control system and dis-connect laptop.</div><div class="ewa-rteLine"><p><br></p></div>', NULL, '2025-06-24 17:49:29', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2FCV-332102', 'GBS-2FCV-332102', 'FLOW CONTROL VALVE', NULL, NULL, 'FLOW CONTROL VALVE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Wiwat', NULL, 'EXTERNAL', '2025-06-24 17:49:29', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sorod', NULL, 'EXTERNAL', '2025-06-24 17:49:29', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL);
END $$;

