  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PP: TEK-3400 Unit water wash activity', 'Mechanic', 'PM', 'Complete', '2025-06-24', '<p>Perform Turbo compressor engine water wash</p><p>- Confirm isolation and Compressor/ Lube oil online complete</p><p>- Confirm all inhibited are correct and function before work task&nbsp;</p><p>- Disconnect all engine PCD line to proper containment&nbsp;</p><p>- Disassemble inlet screen and clear any block for water wash injector nozzle</p><p>- Take sample as marking point at Inlet screen and Inlet housing filter by Lab technician</p><p>- Execute engine water wash with mixed chemical, take first drain water sample and soaking as procedure require</p><p>- Perform water wash with pure nonionic water for 300L., Take final drain water sample.</p><p>- Engine clank dry process and reassemble engine PCD line to position</p><p>- General clean inlet screen housing reassembles screen to position</p><p>- Remove all isolation and inhibited to normal condition</p><p>- Perform line up and unit start firing with idle mode complete</p><p>- Perform unit normal stop and cooldown and CCR perform select to stand-by unit</p><p></p><p><br></p>', '<p><a href="https://pttep-my.sharepoint.com/:f:/p/bongkot_turbine-mech/EiStyjYvuexAtYOdrpxQICgBT3pYEk4Wus1dkzu322PdeA?e=A4bOD1">https://pttep-my.sharepoint.com/:f:/p/bongkot_turbine-mech/EiStyjYvuexAtYOdrpxQICgBT3pYEk4Wus1dkzu322PdeA?e=A4bOD1</a><br></p>', '2025-06-24 22:05:47', '2025-06-25 09:36:52', 'PTTEP\\Bongkot.turbine-Mech', 'PTTEP\\Bongkot.turbine-Mech', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TEK-3400', 'GBN-TEK-3400', 'TURBO COMPRESSOR TRAIN3', NULL, NULL, 'TURBO COMPRESSOR TRAIN3', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
