BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP: 13 T/S technical room temperature high ', 'Electrical', 'CM', 'Under Monitoring', '2025-06-24', '<p>The temperature reading at the HMI unit of the HVAC system inside the technical room was <strong data-start="142" data-end="153">28.7 °C</strong>.</p><p>- Verify found HVAC-23-410A/B refrigerant low.</p><p><br></p><p>&nbsp; &nbsp;- HVAC-23-410A</p><p>&nbsp; &nbsp; - Initial inspection revealed low pressure (LP) at 19 psi due to refrigerant seepage from the service valve port connection service hoses to both low and high-pressure ports.</p><p>&nbsp; &nbsp; - Refilled system with R134A refrigerant and fine tune system.</p><p>&nbsp; &nbsp; - Final system readings:&nbsp;<strong data-start="415" data-end="432">Low Pressure:</strong> 30 psi,&nbsp;<strong data-start="446" data-end="464">High Pressure:</strong> 150 psi,&nbsp;<strong data-start="479" data-end="507">Compressor Current :</strong> 5.2 A</p><p>&nbsp; &nbsp; - Repaired the leak at the service valve port.</p><p>- The SD-411A was found to be malfunctioning some time ago then inform the EI leader so a plan can be made to replace it with a new unit</p><p><br></p><p></p><div class="hlJJmd"><div class="D5aOJc Hapztf" jscontroller="ycXvHb" jsname="KfPmsf"></div><div class="Bmcqed" dir="ltr" jsname="AaF9Fc" soy-skip="" ssk="6:KYzJbc"><div jsaction="Raasr:bdSded;S2duZe:mAkLzf,BPNeHb,n3ah2d;ybxyWe:YHBut,L76sMb;ErIIx:BPNeHb,Eqdykf;nAuWDe:BPNeHb,xwRzhd;E2K7zf:SshWL;aa5XPc:Er30lb,UFDLdd;U9Zrx:kNWkF;PW9Uk:kNWkF;HgCKf:mtyjfe,GKgyhe;l2GTKd:kNWkF;wvqTJf:xWqg4c,UFDLdd;" jscontroller="qDN7de" jsmodel="v6qAXe" data-id="kvLWu"></div></div></div><div class="D5aOJc vJwDU" jscontroller="ycXvHb" jsname="lKng5e"></div><p>&nbsp;- HVAC-23-410B</p><p>&nbsp; &nbsp; - Initial inspection revealed low pressure (LP) at 25 psi due to refrigerant seepage from the service valve port connection service hoses to both low and high-pressure ports.</p><p>&nbsp; &nbsp; - Refilled system with R134A refrigerant and fine tune system.</p><p>&nbsp; &nbsp; - Final system readings:&nbsp;Low Pressure:&nbsp;30 psi,&nbsp;High Pressure:&nbsp;160 psi, Compressor Current :&nbsp;5.3 A</p><p>&nbsp; &nbsp; - Repaired the leak at the service valve port.</p><p><br></p><p>- Setpoint temperature was set to 22 °C. After system operation, the measured temperature at 22.2°C.</p><p><br></p>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/WPs%20PICTURES/WP13/HVAC/Technical%20room%20high%20temperature%2024-6-25?csf=1&amp;web=1&amp;e=aLK7Zn">Technical room high temperature 24-6-25</a>', '2025-06-24 22:25:45', '2025-06-25 09:18:11', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
