DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C) WPS-16 Activity report', 'ROMO', 'ROMO', 'In Progress', '2025-06-25', '<p>- We were on board 7 persons.</p><p>&nbsp;1) Nitipong D.PFO02/SM-EI.&nbsp;</p><p>&nbsp;2) Nopparat N.PFO2/SP</p><p>&nbsp;3) Charlit Y. PTTEP</p><p>&nbsp;4) Wanlopl A. PTTEP</p><p>&nbsp;5) Wasin R. Exon.</p><p>&nbsp;6) Henrik. Slb</p><p>&nbsp;7) Dylan. Slb</p><p>- Safety tools box talk and work scope/ work planning&nbsp;</p><p>&nbsp;Open work permit :</p><p><font color="#ff0000">+ HWP-2482 Flowline inspection campaign#2-25</font></p><p>&nbsp; &nbsp;-Visual and UTM on Prod. and Teat Header, flexible hoses.</p><p><font color="#ff0000">+ HWP-2484 GBS 3YPM Multiphase flow meter</font>, Required process isolation, depressurization and full drain.</p><p><span style="background-color: rgb(255, 255, 0);">PM Activities &gt;&gt;&gt;&gt; 15% Job in progress.</span></p><p>1.Transfer and set up materials, tools, and equipment.</p><p>2.Sampling downstream of <font color="#00ff00">BK-S16-J, BK-S16-L</font></p><p>Production Activities:</p><p>1.Routine activities completed.</p><p>&nbsp; &nbsp; &nbsp;-Platform survey.</p><p>&nbsp; &nbsp; &nbsp;-Flow line inspection.</p><p>2.Support PM team.</p><p>Route wells J and L to test separator for sampling.</p><p>- Water</p><p>- Condensate</p><p>- Gas</p><p>Purpose: To collect and analyze samples from Multiphase flow meter.</p><p><font style="background-color: rgb(255, 255, 0);">Maintenance activities:</font></p><p><span style="background-color: rgb(255, 0, 0);">1. T/S 2XV-26D15 stuck to close:&nbsp;</span></p><p>- Performed manual close and checked 24 VDC at the solenoid —&nbsp;0 voltage&nbsp;detected.It work perporly.</p><p>- Performed manual open and checked 24 VDC at the solenoid — voltage was present about&nbsp;26VDC. It work perporly.</p><p>- Released instrument gas from the actuator — valve did not close.</p><p>- Disconnected the IG vent at the valve and close command — solenoid released IG normally.</p><p>-&nbsp;<span style="background-color: rgb(255, 255, 0);">Exercise valve stuck and can not manual exercise valve because no stem to handling.</span> Inform CCR to <span style="background-color: rgb(0, 255, 0);">issue notification no : 100683986</span></p><p>&nbsp;</p><p><span style="background-color: rgb(255, 0, 0);">2. T/S Crane Robway alarm.</span></p><p>- Found Robway main load cell triggered a&nbsp;"Load on Hook"&nbsp;alarm, Load reading display was 4 tons, despite no actual load being present.</p><p>- Performed calibration on the main load cell. Reading from 4 tons to 0.3 tons.The <font style="background-color: rgb(0, 255, 0);">alarm was successfully cleared.</font></p><p><span style="background-color: rgb(255, 156, 0);">- Found Robway display screen is dim and unclear.&nbsp;Should be replace.</span></p><p>&nbsp;</p><p>See pictures as link:&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-16/2025/2025-06-25_WPS-16_Activity%20pictures?csf=1&amp;web=1&amp;e=1U42oc">2025-06-25_WPS-16_Activity pictures</a></p><p>                                                                                    </p><p>&nbsp;</p><p></p>', '<p>See pictures as link:&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/SA02Prod/15.%20Picture%20to%20report/WPS-16/2025/2025-06-25_WPS-16_Activity%20pictures?csf=1&amp;web=1&amp;e=1U42oc">2025-06-25_WPS-16_Activity pictures</a></p><p><span style="font-size: 15px;">- Found Robway display screen is dim and unclear. Should be replace.</span></p>', '2025-06-25 12:17:33', '2025-07-20 14:15:53', 'PTTEP\\GBS.Production-Oper', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2XV-26D15', 'GBS-2XV-26D15', 'XV,WELL 16D/B/C TO PROD MAN,ESD 2D,3B', NULL, NULL, 'XV,WELL 16D/B/C TO PROD MAN,ESD 2D,3B', 'GBS-WP16', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WP16', 'GBS-WP16', 'BONGKOT SOUTH WELLHEAD PLATFORM WPS16', NULL, NULL, 'BONGKOT SOUTH WELLHEAD PLATFORM WPS16', 'GBS-WP16', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
