  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP40:T/S 1PV-40115 not fully open', 'Instrument', 'CM', 'Complete', '2025-06-25', '<p data-start="89" data-end="124"><strong data-start="89" data-end="124">T/S 1PV-40115 Not Fully Opening</strong></p><p data-start="126" data-end="139"><strong data-start="126" data-end="139">Findings:</strong></p><ul data-start="141" data-end="741"> <li data-start="141" data-end="279"> <p data-start="143" data-end="279">- Positioner alarm code <strong data-start="165" data-end="173">GRGG</strong> detected, indicating "Travel or Cycle Limit Reached" and "Supply Pressure Low" (warning code <strong data-start="267" data-end="275">YYYG</strong>).</p> </li> <li data-start="280" data-end="407"> <p data-start="282" data-end="407">- Leak check using Snoopy identified leakage at the <strong data-start="332" data-end="346">stem valve</strong> and <strong data-start="351" data-end="370">diaphragm cover</strong>, specifically from above the stem.</p> </li> <li data-start="408" data-end="474"> <p data-start="410" data-end="474">- Rear positioner <strong data-start="426" data-end="441">lock washer</strong> found to be in poor condition.</p> </li> <li data-start="475" data-end="549"> <p data-start="477" data-end="549">- Corrosion found on positioner bolts and nuts; all cleaned accordingly.</p> </li> <li data-start="550" data-end="615"> <p data-start="552" data-end="615">- Replaced with a <strong data-start="568" data-end="586">new positioner</strong> and performed calibration.</p> </li> <li data-start="616" data-end="741"> <p data-start="618" data-end="741">- After replacement, the positioner displayed status code <strong data-start="674" data-end="682">GGGG</strong>, indicating <strong data-start="695" data-end="738">normal operation in analog command mode</strong>.</p> </li> </ul><p data-start="743" data-end="771"><strong data-start="743" data-end="771">Valve Actuator Overhaul:</strong></p><p>    </p><ul data-start="773" data-end="961"> <li data-start="773" data-end="805"> <p data-start="775" data-end="805">- Found <strong data-start="781" data-end="802">damaged diaphragm</strong>.</p> </li> <li data-start="806" data-end="870"> <p data-start="808" data-end="870">- Replaced with new <strong data-start="826" data-end="844">spare part kit</strong> (O-ring and diaphragm).</p> </li> <li data-start="871" data-end="899"> <p data-start="873" data-end="899">- Conducted function test.</p> </li> <li data-start="900" data-end="961"> <p data-start="902" data-end="961">- Performed leak test using Snoopy – <strong data-start="937" data-end="960">no leakage&nbsp;</strong></p></li></ul><p><br></p>', NULL, '2025-06-25 19:23:29', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP40', 'GBN-WP40', 'BONGKOT NORTH WELLHEAD PLATFORM WP40', NULL, NULL, 'BONGKOT NORTH WELLHEAD PLATFORM WP40', 'GBN-WP40', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN', 'GBN', 'BONGKOT NORTH FIELD', NULL, NULL, 'BONGKOT NORTH FIELD', NULL, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
