  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S WPS-5 crane could not operate.', 'Electrical', 'CM', 'In Progress', '2025-06-25', '<p>T/S WPS-5 crane could not operate.</p><p>&nbsp; &nbsp; - Found crane was motion cut like "Overload function" could not winch up and display not appeared.</p><p>&nbsp; &nbsp; - While verified found all safety barrier have no power supply due to fuse at Main board was blown.</p><p>&nbsp; &nbsp; - Found fuse at main board blown due to ATB barrier was defected. Replaced by the new one then all barriers have power supply.</p><p>&nbsp; &nbsp; - At ROBWAY display still no appeared. Replaced display barrier but still used existing adaptor, diaplay still not appeared.</p><p>&nbsp; &nbsp;</p><p><br></p><p>&nbsp; &nbsp; - Tried to bypass Hoist up solenoid valve for temporary use and function test completed(without safety function)</p><p>&nbsp; &nbsp; - To be continue by replace adaptor of display barrier tomorrow. If the troubleshooting not success, to be bypass and keep temporary use for transfer all Well service properties to WPS-10 and to be troubleshooting again.<br></p>', NULL, '2025-06-25 20:13:38', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-1506', 'GBS-2X-1506', 'PEDESTAL CRANE GBS-WP05', NULL, NULL, 'PEDESTAL CRANE GBS-WP05', 'GBS-WP05', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
