  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Daily EI Turbine activities_2025-Jun-25', 'Turbine E&I', 'OTH', 'In Progress', '2025-06-25', '<div>Daily EI Turbine activities_2025-Jun-25</div><div><div><br></div><div>Turbo packages site walk-around inspection.</div><div>&nbsp; - All Compressor units FGC, SGC, and 2 Units of TG are properly running. (TG-1 Stopped)</div><div>&nbsp; - Gas Nomination 330 MMscfd</div><div><br></div><div>Recalibrated PCV-1215 due to hunting at 50% range with 45 barg reading from PIT-1215.</div><div>&nbsp;- Calibrated result was acceptable. All points and reading feedback of the valve positioner reading OK.</div><div>&nbsp;- But found it hunting when put in online ( Onload controller ) ( Swap from PCV-1216 controlling to PCV-1215 controlling). The Hunting was found when the controlling setpoint was around 50%.</div><div><br></div><div>&nbsp;- So, this should be realigning the valve positioned or replaced with DVC-62000 if needed.&nbsp;</div></div>', NULL, '2025-06-26 08:25:38', '2025-06-26 08:26:10', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'OTHER', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'TawatchaiP.', NULL, 'EXTERNAL', '2025-06-26 08:25:38', '2025-06-26 08:26:10', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
