  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S PCV-1215 Hunting at 50% rannge', 'Turbine E&I', 'CM', 'In Progress', '2025-06-25', '<div>Recalibrated PCV-1215 due to hunting at 50% range with 45 barg reading from PIT-1215.</div><div>&nbsp;- Calibrated result was acceptable. All points and reading feedback of the valve positioner reading OK.</div><div>&nbsp;- But found it hunting when put in online ( Onload controller ) ( Swap from PCV-1216 controlling to PCV-1215 controlling). The Hunting was found when the controlling setpoint was around 50%.</div><div><br></div><div>&nbsp;- So, this should be performed to realign the valve the positioner or replaced with DVC-62000 if needed.&nbsp;</div><div><br></div><div>For Calibrated and stroking the valve, Due to the PCV-1215 is FieldBus. So it need to be change Mode from "Auto" to "OOS" ( Out of service).</div><div>&nbsp;- For calibrated, should be done mode changing in detail set up, Mode change.</div><div>&nbsp;- For stroking it is in the diagnostic for doing valve stroking.</div>', NULL, '2025-06-26 08:35:38', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PCV-1215', 'ART-PCV-1215', 'PRESSURE CONTROL VALVE', NULL, NULL, 'PRESSURE CONTROL VALVE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'TawatchaiP.', NULL, 'EXTERNAL', '2025-06-26 08:35:38', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL);
