-- Inserting report ID 32714
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Hydrocyclone ceramic liner replacement.', 'Mechanic', 'CM', 'Completed', '2025-06-26', '<p>Failure cause: Production request add hydrocyclone ceramic liner for increase flow and reduce&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; pressure differential.</p><p><br></p><p>1. Perform mechanical isolation.</p><p>&nbsp; &nbsp; - Spectacle bilnd size 2"# 300 = 3 flanges. (Wrench# 27 mm)</p><p>&nbsp; &nbsp; - Spectacle bilnd size 4"# 300 = 2 flanges. (Wrench# 32 mm)</p><p>&nbsp; &nbsp; - Spectacle bilnd size 6"# 300 = 1 flange.&nbsp; &nbsp;(Wrench# 32 mm)</p><p>2. Remove top cover size 24"# 300&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (Wrench# 60 mm.)</p><p>3. Remove dummy of hydrocyclone ceramic liner 4 ea.</p><p>4. Install new hydrocyclone ceramic liner 4 ea.</p><p>5. Clean and inspect internal vessel.</p><p>6. Reassembly all internal part and install top cover.</p><p>7. Apply JIMS.</p><p>&nbsp; &nbsp; - Spectacle bilnd size 2"# 300 apply torque 69 ft.lb.</p><p>&nbsp; &nbsp; - Spectacle bilnd size 4"# 300 apply torque 125 ft.lb.</p><p>&nbsp; &nbsp; - Spectacle bilnd size 6"# 300 apply torque 125 ft.lb.</p><p>&nbsp; &nbsp; - Top cover size 24"# 300 apply torque 1,175 ft.lb.</p><p>8. Housekeeping.</p><p>&nbsp; &nbsp;&nbsp;</p>', '<p>Picture attached link&nbsp;</p><p>https://pttep.sharepoint.com/sites/THART/Mechanic/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FMechanic%2FMechanical%20%28Most%20Updated%29%2F05%2E%20Picture%2F51%2E%20APP%20Equipment%2F02%20Main%20Deck%2FDesander%20HC%2D4005&amp;viewid=69417a80%2D5c8c%2D4085%2D8019%2D21267735720d</p><p><br></p><p>Consumable</p><p>1. SPW gasket size 2"# 300 = 6 ea.</p><p>2. SPW gasket size 4"# 300 = 4 ea.</p><p>3. SPW gasket size 6"# 300 = 2 ea.</p><p>4 Top cover gasket = 1 ea.</p>', '2025-06-26 19:10:46', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-HC-4005', 'ART-HC-4005', 'DESANDING HYDROCYCLONE VESSEL TRAIN 2', NULL, NULL, 'DESANDING HYDROCYCLONE VESSEL TRAIN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
