-- Inserting report ID 32748
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot Gas GeneratorG-8930 can''t start Day 6', 'Electrical & Instrument', 'CM', 'In Progress', '2025-06-27', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot Gas Generator G-8930 cannot start.</p><p><b><u>Action</u></b></p><p>-Adjust fuel pressure from 15kpa to 13kpa and test run. It is not ok.</p><p>-Adjust fuel pressure from 13kpa to 18kpa and test. It is not ok.</p><p>-Swiping GMC Controller from G-8925 to G-8930.</p><p>-Swiping Comp Ads Controller from G-8925 to G-8930.</p><p>-Perform test run but generator still cannot start.</p><p><br><u><b style="background-color: rgb(255, 255, 0);">History</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Gas Generator G-8930 cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);">1.Checked speed sensor condition and performed adjustment for speed sensor with mechanic team.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Test run the generator and rpm value reaches 160rpm and cannot start.</span></p><p><b><u><br></u></b></p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot Gas Generator cannot start.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Replace some control relay with new one for G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Top up Battery Acid and Prepare two new batteries for Battery Charging.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot Gas Generator G-8930 cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Adjust fuel pressure from 15kpa to 20kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Connect to the AFI with laptop.</span></p><p><span style="background-color: rgb(255, 255, 0);">3.Generator Starting with Battery Bank 1 with Battery Starter.</span></p><p><span style="background-color: rgb(255, 255, 0);">4.Gas Generator still cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G-8930 can''t stop with under RPM alarm Day 2</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Replace new timing sensor</span></p><p><span style="background-color: rgb(255, 255, 0);">Install digital pressure gauge at doghouse regulator side.</span></p><p><span style="background-color: rgb(255, 255, 0);">Adjust fuel regulator 17Kpa to 15 Kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">Connect with laptop to monitor speed control and ignition control.</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run with battery charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 still can''t start without alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (20.06.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8930 can''t stop with low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Remove and check low RPM sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found dirty and few scratch.</span></p><p><span style="background-color: rgb(255, 255, 0);">Clean, re-install back and test run G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new sensor and test run G8930</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 under rpm alarm is cleared but can''t start without alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to troubleshoot tomorrow.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><br></p>', NULL, '2025-06-27 18:31:31', '2025-07-02 11:44:53', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930-PACK', 'ATL-OC-G-8930-PACK', 'Gen, ZOC Gas Generator Package 3', NULL, NULL, 'Gen, ZOC Gas Generator Package 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2025-06-27 18:31:31', '2025-07-02 11:44:53', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Boom', NULL, 'EXTERNAL', '2025-06-27 18:31:31', '2025-07-02 11:44:53', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jack', NULL, 'EXTERNAL', '2025-06-27 18:31:31', '2025-07-02 11:44:53', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
END $$;

