-- Inserting report ID 32847
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot G-8925 trip by low RPM alarm Day 3', 'Electrical & Instrument', 'CM', 'In Progress', '2025-06-29', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot Gas Generator G-8925 trip by low RPM.</p><p><b><u>Action&nbsp;</u></b></p><p>-Checked resistance value and insulation resistance value for over speed sensor is good.</p><p>-Checked also resistance value and insulation resistance value for crank shaft speed sensor is not good result. IR value is 0.00MOhm @250vDC.</p><p>-Need to find out the grounded cable for crankshaft speed sensor.</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Gas Generator G-8925 trip by low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Replace new breather for both banks from mechanic team.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Checked all wiring connection concern with overspeed sensor and crankshaft speed sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">3.Replaced new crankshaft speed sensor with new one.</span></p><p><span style="background-color: rgb(255, 255, 0);">4.Incease fuel pressure from 11kpa to 13kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">5.Perform test run the generator with load share. After about 40minutes later, the generator rpm value reaches 1460 and trip by BOC reverse power.</span></p><p><span style="background-color: rgb(255, 255, 0);">6. Continue need to troubleshoot.</span></p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Gas Generator G-8925 trip by low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Perform proper cleaning the crankshaft speed sensor and installed back.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Replaced new speed sensor for overspeed protection because of defective.</span></p><p><span style="background-color: rgb(255, 255, 0);">3.Perform test run the Generator with load share. After about 45min running time, G-8925 trip by reverse power.</span></p><p><span style="background-color: rgb(255, 255, 0);">4.Need to test run with full load and need to monitor.</span></p>', NULL, '2025-06-29 17:09:57', '2025-07-02 10:53:56', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2025-06-29 17:09:57', '2025-07-02 10:53:56', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Stephen', NULL, 'EXTERNAL', '2025-06-29 17:09:57', '2025-07-02 10:53:56', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
