  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S  crane could not operate.', 'Electrical', 'CM', 'Completed', '2025-06-29', '<p>T/S WPS-5 crane could not operate. (Since 25-June-2025)</p><p>&nbsp; &nbsp; - Resumed normal operation of the hoist-up solenoid valve.</p><p>&nbsp; &nbsp; - Found that the crane was in motion cut-off mode, similar to an "overload function." Winching up was not possible, and the display did not appear.</p><p>&nbsp; &nbsp; - The ROBWAY display was still not functioning. Replaced the display barrier and adaptor board. After replacement, the display began working, but some display elements were still missing.</p><p>&nbsp; &nbsp; - Replaced the ROBWAY display with a new unit. The new display functioned properly.</p><p>&nbsp; &nbsp; - Crane function test completed successfully. No abnormalities or alarms found.<br></p>', '<p><span style="font-size: 14px;">Request to order BARRIER,QUAD SWITCH,ROBWAY,P/N.BARD1031Q, Item No. 36.94.10.016.3&nbsp;&nbsp;=&nbsp; 1 Ea.</span></p><p>Request to order&nbsp;DISPLAY,RCI-4100,ROBWAY,P/N.DISRCI4100, Item No.&nbsp;36.56.11.733.3&nbsp; =&nbsp; 1 Set.</p>', '2025-06-29 19:46:24', '2025-07-04 08:33:02', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
