  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG1 Enclosure Door Alarm time to times.', 'Instrument', 'CM', 'Completed', '2025-06-30', '<p data-start="356" data-end="500"><strong data-start="356" data-end="381">Description of Issue:</strong><br data-start="381" data-end="384"> During operation, the <strong data-start="406" data-end="450">Enclosure Door Alarm (AL_Encl_Door_Open)</strong> was observed to be active and could not be reset.</p> <p data-start="507" data-end="527"><strong data-start="507" data-end="525">Actions Taken:</strong></p><p data-start="507" data-end="527">- Conducted a <strong data-start="543" data-end="560">function test</strong> to verify the alarm signal.</p><p data-start="507" data-end="527">- Found the alarm <strong data-start="610" data-end="624">persisting</strong> despite all doors being closed.</p><p data-start="507" data-end="527"><strong data-start="662" data-end="700">- Replaced the magnetic sensor plate</strong> associated with the enclosure door.</p><p data-start="507" data-end="527">- Re-tested the function; <strong data-start="766" data-end="808">alarm cleared and reset was successful</strong>.</p><p data-start="507" data-end="527">- Performed a <strong data-start="827" data-end="857">changeover from TG3 to TG1</strong> – the alarm <strong data-start="870" data-end="890">did not reappear</strong> after the switch.</p><p data-start="915" data-end="928"><strong data-start="915" data-end="926">Result:</strong></p><p data-start="915" data-end="928">- Fault resolved by replacing the magnetic plate.</p><p data-start="915" data-end="928">- Alarm functionality is now normal.</p><p data-start="915" data-end="928">- No reoccurrence of alarm after TG3 to TG1 changeover.</p><p data-start="915" data-end="928"><br></p><p><br></p>', NULL, '2025-06-30 16:29:04', '2025-06-30 16:30:28', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\GBS.Turbine-Tech', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2TG-5510', 'GBS-2TG-5510', 'GAS TURBINE GENERATOR SOLAR TAURUS 70', NULL, NULL, 'GAS TURBINE GENERATOR SOLAR TAURUS 70', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
