-- Inserting report ID 32905
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot G-8925 trip by low RPM alarm Day 4', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2025-06-30', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot Gas Generator G-8925 trip by low RPM alarm.</p><p><b><u>Action</u></b></p><p>1.Checked the physical condition and continuity of speed sensor cable from GMC Controller to Crank Shaft Controller.</p><p>2.Checked techno meter condition. Found not good. So, replaced new techno meter.</p><p>3.Checked Insulation Resistance Test for the control cable from LCP control panel to GCP control panel.</p><p>4.Checked control relay condition and replaced two control relay for IC and GIR relay.</p><p>5.Test run the generator with load share about 120minutes.Running fine. But soft unload the generator time, air circuit breaker open directly.</p><p>6.Under Monitoring.&nbsp;</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><u style="box-sizing: border-box; color: rgb(0, 0, 0); font-family: Montserrat, Lato, &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Calibri, Arial, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal;"><b style="box-sizing: border-box; font-weight: 700;">History</b></u><u><b></b></u></span></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot Gas Generator G-8925 trip by low RPM.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Checked resistance value and insulation resistance value for over speed sensor is good.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Checked also resistance value and insulation resistance value for crank shaft speed sensor is not good result. IR value is 0.00MOhm @250vDC.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Need to find out the grounded cable for crankshaft speed sensor.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Gas Generator G-8925 trip by low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Replace new breather for both banks from mechanic team.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Checked all wiring connection concern with overspeed sensor and crankshaft speed sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">3.Replaced new crankshaft speed sensor with new one.</span></p><p><span style="background-color: rgb(255, 255, 0);">4.Incease fuel pressure from 11kpa to 13kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">5.Perform test run the generator with load share. After about 40minutes later, the generator rpm value reaches 1460 and trip by BOC reverse power.</span></p><p><span style="background-color: rgb(255, 255, 0);">6. Continue need to troubleshoot.</span></p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Gas Generator G-8925 trip by low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Perform proper cleaning the crankshaft speed sensor and installed back.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Replaced new speed sensor for overspeed protection because of defective.</span></p><p><span style="background-color: rgb(255, 255, 0);">3.Perform test run the Generator with load share. After about 45min running time, G-8925 trip by reverse power.</span></p><p><span style="background-color: rgb(255, 255, 0);">4.Need to test run with full load and need to monitor.</span></p>', NULL, '2025-06-30 19:38:29', '2025-07-02 10:55:22', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2025-06-30 19:38:29', '2025-07-02 10:55:22', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Stephen', NULL, 'EXTERNAL', '2025-06-30 19:38:29', '2025-07-02 10:55:22', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jack', NULL, 'EXTERNAL', '2025-06-30 19:38:29', '2025-07-02 10:55:22', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
END $$;

