BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'G8930 can''t start with under RPM alarm Day 6', 'Electrical & Instrument', 'CM', 'Completed', '2025-06-30', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot Gas Generator G-8930 cannot start.<b><u></u></b></p><p><b><u>Action</u></b></p><p>1.Replaced techno meter with new one and calibrate.</p><p>2.Connect to GMC Controller with laptop and perform auto calibration for actuator.</p><p>3.Adjust the fuel pressure from 13kpa to 15kpa and also perform exercise the fuel regulator.</p><p>4.Replaced one lube oil pressure switch with new one because of resistance value is 57 Ohm.</p><p>5.Perform test run with load share about 45mintues.Running fine.</p><p>6.Under Monitoring.</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot Gas Generator G-8930 cannot start.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Adjust fuel pressure from 15kpa to 13kpa and test run. It is not ok.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Adjust fuel pressure from 13kpa to 18kpa and test. It is not ok.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Swiping GMC Controller from G-8925 to G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Swiping Comp Ads Controller from G-8925 to G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Perform test run but generator still cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br><u><b>History</b></u></span></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Gas Generator G-8930 cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);">1.Checked speed sensor condition and performed adjustment for speed sensor with mechanic team.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Test run the generator and rpm value reaches 160rpm and cannot start.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot Gas Generator cannot start.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Replace some control relay with new one for G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Top up Battery Acid and Prepare two new batteries for Battery Charging.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot Gas Generator G-8930 cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1.Adjust fuel pressure from 15kpa to 20kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">2.Connect to the AFI with laptop.</span></p><p><span style="background-color: rgb(255, 255, 0);">3.Generator Starting with Battery Bank 1 with Battery Starter.</span></p><p><span style="background-color: rgb(255, 255, 0);">4.Gas Generator still cannot start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G-8930 can''t stop with under RPM alarm Day 2</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Replace new timing sensor</span></p><p><span style="background-color: rgb(255, 255, 0);">Install digital pressure gauge at doghouse regulator side.</span></p><p><span style="background-color: rgb(255, 255, 0);">Adjust fuel regulator 17Kpa to 15 Kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">Connect with laptop to monitor speed control and ignition control.</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run with battery charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 still can''t start without alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (20.06.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8930 can''t stop with low RPM alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Remove and check low RPM sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found dirty and few scratch.</span></p><p><span style="background-color: rgb(255, 255, 0);">Clean, re-install back and test run G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new sensor and test run G8930</span></p><p><span style="background-color: rgb(255, 255, 0);">G8930 under rpm alarm is cleared but can''t start without alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to troubleshoot tomorrow.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><br></p>', NULL, '2025-06-30 19:52:02', '2025-08-09 11:22:45', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI', false, 'ATL') RETURNING id INTO new_report_id;
