  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2025-06-30 19:52:02', '2025-08-09 11:22:45', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Stephen', NULL, 'EXTERNAL', '2025-06-30 19:52:02', '2025-08-09 11:22:45', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
