  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify Fire pump shows Fuel Tank High Level', 'Instrument', 'CM', 'In Progress', '2025-07-02', '<p><b>Verify Fire pump package shows Fuel Tank High Level alarm time to time.</b></p><p>- Verified event log of LIT-5740, Found<span style="background-color: rgb(255, 255, 0);"> Fault&nbsp;&nbsp;EOP &lt; Probe Length</span> and <span style="background-color: rgb(255, 255, 0);">Warning&nbsp;EOP Too Low</span> some time.&nbsp;</p><p></p><p><br></p><p>- Cause to sent 22mA to PLC when transmitter fault.</p><p></p><p><br></p><p>- Set PV Alarm type from 22 mA to Hold (Hold Last Value)</p><p>Fuel Tank High Level Alarm = 99%</p><p>Fuel Tank Low Level Alarm = 50%</p><p><span style="background-color: rgb(255, 156, 0);">Temporarily prevent a spurious alarm from level transmitter fault.</span></p><p></p><p><br></p><p>- Verified level reading by drain diesel oil, Found level from 79% to about 34% transmitter reading normal but below about 34% Transmitter Fault EOP &lt; Probe Lenght also.</p><p></p><p><br></p><p>- To be replaced with a new level transmitter.</p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%20APP%2FFire%20Water%20Pump%2FA%2D5740%5FAPP%2DLD%5FWest%2FLIT%2D5740%202%20Jul%2025&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067" target="_blank">Link More Photos</a><br></p>', '2025-07-02 15:23:34', '2025-07-07 16:27:49', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\WinyooN', false, 'ART') RETURNING id INTO new_report_id;
