  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Winyoo N.', NULL, 'EXTERNAL', '2025-07-02 15:23:34', '2025-07-07 16:27:49', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\WinyooN');
