-- Inserting report ID 32980
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting 2PIT-37529 Reading Error', 'Instrument', 'CM', 'Completed', '2025-07-02', '<p data-start="77" data-end="129"><strong data-start="77" data-end="129">Troubleshooting 2PIT-37529 Reading Error</strong></p> <ul data-start="131" data-end="854"> <li data-start="131" data-end="321"> <p data-start="133" data-end="321"><strong data-start="133" data-end="154">Issue Identified:</strong><br data-start="154" data-end="157"> Transmitter 2PIT-37529 has a configured range of 0–70 bar. However, it was consistently reading approximately 23 bar while the actual process pressure was 51 bar.</p><p data-start="133" data-end="321"><br></p> </li> <li data-start="323" data-end="516"> <p data-start="325" data-end="516"><strong data-start="325" data-end="348">Initial Diagnostic:</strong><br data-start="348" data-end="351"> Performed span check by applying 70 bar pressure using a pump. Transmitter still read 23 bar, indicating malfunction. Recalibration was attempted but unsuccessful.</p><p data-start="325" data-end="516"><br></p> </li> <li data-start="518" data-end="699"> <p data-start="520" data-end="699"><strong data-start="520" data-end="542">Corrective Action:</strong><br data-start="542" data-end="545"> Removed and replaced the faulty transmitter with a new unit. Performed calibration check with CCR – all readings were accurate and within specification.</p><p data-start="520" data-end="699"><br></p> </li> <li data-start="701" data-end="854"> <p data-start="703" data-end="854"><strong data-start="703" data-end="719">Final Check:</strong><br data-start="719" data-end="722"> New transmitter installed and online. No leakage detected. Transmitter is now reading actual process pressure correctly at 51 bar.</p></li></ul>', NULL, '2025-07-02 16:20:13', '2025-07-02 17:12:24', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2PIT-37529', 'GBS-2PIT-37529', 'PRESSURE INDICATOR TRANSMITTER', NULL, NULL, 'PRESSURE INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-07-02 16:20:13', '2025-07-02 17:12:24', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'WiwatK', NULL, 'EXTERNAL', '2025-07-02 16:20:13', '2025-07-02 17:12:24', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
