  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'YPM 2TR-6808 and ACDB-6817 and test function.', 'Electrical', 'PM', 'Completed', '2025-07-02', '<div>YPM 2TR-6808 and ACDB-6817 and test function.</div><div><p>- Performed Transformer tightening and cleaning.</p><p>- Performed Transformer insulation test.</p><p>- Performed Transformer measured winding resistance.</p><p>- Performed Transformer test function.</p><p>- Performed ACDB-6817 tightening and cleaning.</p><p>- Performed ACDB-6817 insulation test.</p><p>- Performed ACDB-6817 all CBs trip test function.</p><p>- Performed MCC, F-504 tightening and cleaning contact finger and lubrication.</p><p>- Performed MCC, F-504 CBs earth leak trip test function.</p><p>- Inspection confirmed the transformer and ACDB-6817 is operating normally, with no active alarms.<br></p></div>', NULL, '2025-07-02 18:30:59', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
