  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Meeting Summary AGD Function for AWPs', 'Automation', 'OTH', 'Completed', '2025-07-02', '<div>Meeting Summary: Acoustic Gas Detector (AGD) Function for AWPs</div><div>Conducted a meeting with the ART site team, EMX/E, and Engineer SSHE to discuss the function of Acoustic Gas Detectors (AGDs) for AWPs platforms. Key conclusions are as follows:</div><div>- AWP34 to 42: Agreed to use AGD for trip function, as per PEGS document 11056-STD-6-SAF-001-R00.</div><div>- AWP11 to 17: Agreed to use AGD for alarm function only.</div><div>- AWP1 to 33: If AGD is required for trip platform, MOC will be issued on a case-by-case from Production Eng.</div><div>- Prefer to standardize AGD timer settings, 5 minutes for alarm (Flashing Beacon/Siren) and15 minutes for trip (ESD1)</div><div>- Issued MOM for follow-up actions.</div><div>As link:&nbsp;<a href="https://pttep.sharepoint.com/:f:/s/THART/El-h6zP3BP5KhfSfJuZhLG4BlGGUmda3YT8fVjumTdWCyw?e=UMrW1f">2025</a></div><div><br></div>', NULL, '2025-07-02 19:00:41', '2025-07-02 23:51:53', 'PTTEP\\Art.Automation', 'PTTEP\\Art.Automation', false, 'ART') RETURNING id INTO new_report_id;
