  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM:2HV-25B04 T/S choke valve passing in close.', 'Mechanic', 'CM', 'Completed', '2025-07-02', '<p>2HV-25B04:&nbsp; T/S choke valve passing in close&nbsp;position.</p><p align="left">o&nbsp;&nbsp; Check choke valve body leak. ( Not found leak)</p><p align="left">o&nbsp;&nbsp; Check stem seal leak at pressure 66.9 bar. ( Not found leak)</p><p align="left">o&nbsp;&nbsp; Remove bonnet from choke valve body.</p><p align="left">o&nbsp;&nbsp; Found seat and Extl floating sleeve was damaged.</p><p align="left">o&nbsp;&nbsp; Clean up choke valve body.</p><p align="left">o&nbsp;&nbsp; Replace new seat (28) and T seal / back up seal (3/4).</p><p align="left">o&nbsp;&nbsp; Replace Extl floating sleeve (29)and T seal (12).</p><p align="left">o&nbsp;&nbsp; Install bonnet to choke valve body and caps crew torque 277 N.m</p><p align="left">o&nbsp;&nbsp; Check choke valve body leak. </p><p align="left">o&nbsp;&nbsp; Check stem seal leak. </p><p align="left">o&nbsp;&nbsp; Manual close valve until stem fully seat by push solenoid.</p><p>                      </p><p align="left">o&nbsp;&nbsp; Test passing. Shut in pressure 75.2 bar. ( Not found passing)&nbsp;</p>', NULL, '2025-07-03 08:08:49', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2HV-25B04', 'GBS-2HV-25B04', 'VALVE CHOKE WH15B TO PROD AND TEST MAN', NULL, NULL, 'VALVE CHOKE WH15B TO PROD AND TEST MAN', 'GBS-WP15', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patawee J.', NULL, 'EXTERNAL', '2025-07-03 08:08:49', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Direk T.', NULL, 'EXTERNAL', '2025-07-03 08:08:49', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
