  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM;Remover membrane element to internal leak.', 'Mechanic', 'CM', 'In Progress', '2025-07-03', '<p>2MS-3730; Remover membrane element to internal leak.</p><p align="left">o&nbsp;&nbsp; Removed the permeate line.</p><p align="left">o&nbsp;&nbsp; Removed the Taper-Lok flange.</p><p align="left">o&nbsp;&nbsp; Removed 1<sup>st</sup> and 2<sup>nd</sup> CO2 membrane air liquid for tube 2 (S) and 11 (S).</p><p align="left">o&nbsp;&nbsp; Clean up tube &amp; flange seal surface.</p><p align="left">o&nbsp;&nbsp; Check tightens at socket head cap screw ok.</p><p align="left">o&nbsp;&nbsp; Check parker polypak seal found parker polypak seal damage.</p><p align="left">o&nbsp;&nbsp; &nbsp;Replaced parker polypak seal new and reduce diameter seal plug from 201.56mm to 200.5mm (Tube 2) and from 201.56mm to 200.76mm (Tube 11)</p><p align="left">o&nbsp;&nbsp; Clean up tube.</p><p align="left">o&nbsp;&nbsp; Re-install CO2 membrane air liquid for tube 2 (S) and 11 (S).</p><p align="left">o&nbsp;&nbsp; Reinstalled the Taper-Lok flange. </p><p align="left">o&nbsp; &nbsp;Torque value as air liquid specification.</p><p align="left">o&nbsp; &nbsp;Apply Molycote 1000 (ecoefficiency 0.125)</p><p align="left">o&nbsp; &nbsp;Tighten tube flanges at 216 Nm </p><p align="left">o&nbsp;&nbsp; Reinstalled the permeate line. </p><p align="left">o&nbsp; &nbsp;Torque value as Jim specification.</p><p align="left">o&nbsp; &nbsp;Apply Molycote 1000 (ecoefficiency 0.125) </p><p align="left">o&nbsp; &nbsp;Tighten flange at 230 Nm.</p><p>                                      </p><p align="left">o&nbsp; &nbsp;Clean working area.</p>', NULL, '2025-07-03 18:45:25', '2025-07-04 08:11:00', 'PTTEP\\PataweeJi', 'PTTEP\\PataweeJi', false, 'G2S') RETURNING id INTO new_report_id;
