BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TEG unit voltage dropped and recover time to t', 'Electrical', 'CM', 'Under Monitoring', '2025-07-03', '<div class="ewa-rteLine">T/S TEG unit voltage dropped and recover time to time.</div><div class="ewa-rteLine">-	Found minimum voltage dropped at 20.9Vdc and recovered to 26.9Vdc.</div><div class="ewa-rteLine">-	Verified all TEG condition and found normal.</div><div class="ewa-rteLine">-	Verified load equipment inside battery charger box and tested by disconnected EFM relay. TEG voltage was stable. Suspected EFM defect.</div><div class="ewa-rteLine">-	Suspected load of platform shorted circuit, to request platform shutdown and verify earth fault next time.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></div>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F2%5FAWP%2D%2FAWP%5FPHASE1A%20%281%2D6%29%2FAWP6%2F02%20DC%20System%2FTS%20TEG%20unit%20voltage%20dropped%203Jul25&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067" target="_blank">Link more photos</a><br></p>', '2025-07-03 19:04:58', '2025-08-03 11:10:29', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
