  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'BC AWP-30 to verify gas leak at PV-7190', 'Mechanic', 'CM', 'Completed', '2025-07-03', '<p>Failaure cause: Unit stop due to gas leak at PV-7190.</p><p><br></p><p>1. Found gas leak at pressure pilot regulator of PV-7190.</p><p>2. Verify and found damage at body of pilot regulator, assume againg and vibration cause daamged.</p><p>3. Replace new pressure pilot regulator.</p><p>4. Restart BC for observe leak, not found leak.</p><p>5. Found PDIT-30627 reading error. Verify and plan to calibrate next visit.</p><p>6. Found LT-30610 reading error and no signal. Verify and plan to calibrate next visit.</p><p>6. Housekeeping.</p>', '<p>Spare part</p><p>Pressure pilot regulator of PV-7190&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 1 ea.</p><p><br></p><p><br></p>', '2025-07-04 08:35:26', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL, false, 'ART') RETURNING id INTO new_report_id;
