-- Inserting report ID 33119
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'SPP: Verify UPS-80-400B unit low batt volt alarm c', 'Electrical', 'CM', 'Under Monitoring', '2025-07-05', '<p>Verify UPS-80-400B unit low batt volt alarm come and clear. note: low batt volt alarm set at 227 Vdc</p><p>&nbsp; &nbsp; - Conducted full-day monitoring of UPS-80-400B; no low battery voltage alarm was observed or activated during this period.</p><p>&nbsp; &nbsp; - Inspected all loop connections and main feeder; found to be in normal and secure condition.</p><p data-start="591" data-end="648">&nbsp; &nbsp; - Attempted to simulate potential root causes of the alarm:</p><p> </p><ul data-start="653" data-end="830"> <li data-start="653" data-end="723"> <p data-start="655" data-end="723">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - No abnormal conditions or issues were identified during simulations.</p> </li> <li data-start="728" data-end="830"> <p data-start="730" data-end="830">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Simulated AC low voltage at 360/342 VAC (nominal 372 VAC); UPS DC output remained stable at 238 VDC.</p><p data-start="730" data-end="830"><br></p><p data-start="730" data-end="830">Noted a voltage drop to 366–368 VAC on ESS-SB-900 (as measured on all UPS unit B) during operation of air compressor units K-8710B and KM-8410 under on-load condition.</p><p data-start="730" data-end="830">&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;This condition may potentially relate to the alarm and should be verified further.</p><p data-start="730" data-end="830"><br></p></li><li data-start="1122" data-end="1155"><p data-start="1124" data-end="1155">Continue monitoring the system.</p> </li><p data-start="730" data-end="830"> </p><li data-start="1156" data-end="1277"> <p data-start="1158" data-end="1277">&nbsp; &nbsp; - Re-assess the abnormal voltage condition during the actual occurrence of the low battery voltage alarm, if it reappears.</p></li><p data-start="730" data-end="830"><br></p></ul>', NULL, '2025-07-05 19:28:03', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-BC-80-400B', 'GBN-BC-80-400B', '24 VDC BC FOR INSTRUMENT SYSTEM SPP', NULL, NULL, '24 VDC BC FOR INSTRUMENT SYSTEM SPP', 'GBN-SPP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surapong', NULL, 'EXTERNAL', '2025-07-05 19:28:03', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL);
