-- Inserting report ID 33183
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S G-03 mobile generator alarm of alternator. Fau', 'Electrical', 'CM', 'Completed', '2025-07-06', '<p>T/S G-03 mobile generator alarm of alternator. Fault.</p><p>- Found air shut off valve does not function during starting.</p><p>- Measured the battery voltage., Found voltage about 13.0 Vdc.</p><p>- Found RL9 base terminal damaged. (Relay to cutoff air shutoff valve)</p><p>- Measured voltage at RL6 terminal 11 and RL9 terminal 12(NC)., Found both voltages drop to 11.8 Vdc.</p><div class="ewa-rteLine">- Replaced RL9 base relay terminal, then Found air shut off valve function as normal and mobile&nbsp; &nbsp; &nbsp; &nbsp; generator can be started.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span></div><div class="ewa-rteLine"><span style="font-size: 14px;">- After the mobile generator successfully started, it was found that the alternator was not charging.</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">- Upon inspection, the carbon brush of the alternator was found to be damaged.</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">- Replaced the alternator with a new unit and performed a functional test.</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">- After-replacement voltage readings:</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">&nbsp; B+ / B- = 14.04 V</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">&nbsp; CH / G = 14.32 V</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">&nbsp; D+ / G = 14.33 V</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span><span style="font-size: 14px;">&nbsp; Battery charging voltage = 13.60 V / 4.2 A</span></div><div class="ewa-rteLine"><span style="font-size: 14px;"><br></span></div><p><br></p>', NULL, '2025-07-06 19:06:40', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-G-03', 'ART-G-03', 'MOBILE GENERATOR #3', NULL, NULL, 'MOBILE GENERATOR #3', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saralrat K.', NULL, 'EXTERNAL', '2025-07-06 19:06:40', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Supakon S.', NULL, 'EXTERNAL', '2025-07-06 19:06:40', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL);
END $$;

