  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM EL 24VDC Battery Charger of WPS09_500586707', 'CONCOR', 'PM', 'Completed', '2025-07-06', '<div>"Perform maintenance and inspection as follow;</div><div>Battery</div><div>&nbsp;1. Check all around the battery box for any sign of damage.&nbsp;</div><div>&nbsp;2. Visually inspect battery each cell for external condition.</div><div>&nbsp;3. Verify tightness of battery main cable and cross bars.</div><div>&nbsp;4. Clean up and apply grease on the battery poles to prevent corrosion.&nbsp;</div><div>&nbsp;5. Measure and record data each batteries cell (see below recording)</div><div>&nbsp; &nbsp;- 2BAT-19-440A output = 27.20 Vdc. / 17.90 Amps.</div><div>&nbsp; &nbsp;- 2BAT-19-440B output = 27.10 Vdc. / 18.60 Amps.</div><div><br></div><div>Solar Array</div><div>1. Check all around the Solar array for any sign of damage.&nbsp;</div><div>&nbsp;2. Verify tightness of all electrical connections and power cables condition.</div><div>&nbsp;3. Junction boxes inspection and tightening check inside connection</div><div>&nbsp;4. Gently clean solar array by soft cloth as much as possible.</div><div>&nbsp;5. Measure and record output data each panel (see below recording)</div><div>&nbsp; &nbsp;- 2SP-19-440A output = 39.0 Vdc. / 5.70 Amps.</div><div>&nbsp; &nbsp;- 2SP-19-440B output = 39.0 Vdc. / 6.20 Amps.</div><div>&nbsp; &nbsp;- 2SP-19-440C output = 38.50 Vdc. / 5.80 Amps.</div><div>&nbsp; &nbsp;- 2SP-19-440D output = 38.50 Vdc. / 5.60 Amps."</div><div><br></div>', NULL, '2025-07-07 16:56:31', CURRENT_TIMESTAMP, 'PTTEP\\GBS.CONCOR-Supv', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WP09-UTL-ELEC-PWD', 'GBS-WP09-UTL-ELEC-PWD', 'POWER DISTRIBUTION WPS09', NULL, NULL, 'POWER DISTRIBUTION WPS09', 'GBS-WP09', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
