  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Investigate USDR-ART-2025-007 AWP07 ESD1.', 'Electrical', 'CM', 'In Progress', '2025-07-07', '<div class="ewa-rteLine">Investigate USDR-ART-2025-007 AWP07 ESD1 by Loss of power.</div><div class="ewa-rteLine">- Force open SDV-07002, SDV-07221, closed vent manual valve of test Sep.</div><div class="ewa-rteLine">- Shutdown platform for verifying for equipment damaged.</div><div class="ewa-rteLine">- Checked DC-DC Converter found status LED showed normal voltage out = 24.2V.</div><div class="ewa-rteLine">- Checked&nbsp;VSM Voltage sensing module found LED showed normal.</div><div class="ewa-rteLine">- Checked battery and load magnetic contactor inside side VR-07-440 and DCDB-07-440, found normal.</div><div class="ewa-rteLine">- Checked interposing relay R03 at JBN-07-002, found normal coil resistance = 0.69 M ohm. voltage drop @ 23.29 V.</div><div class="ewa-rteLine">- Resumed platform and removed forcing open SDV-07002, SDV-07221 and vent manual valve Test Sep.</div><div class="ewa-rteLine">- Under monitoring.</div>', NULL, '2025-07-07 18:50:40', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP07-ELE', 'ART-WP07-ELE', 'ELECTRICAL SYSTEM', NULL, NULL, 'ELECTRICAL SYSTEM', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
