-- Inserting report ID 33274
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify choke valve passing HV-05M1', 'Mechanic', 'CM', 'Completed', '2025-07-07', '<p></p><p><u>Inspect internal part of choke valve due to erosion.</u></p><p>03/07/2025</p><p>- Remove valve actuator.<br>- Remove valve bonnet.<br>- Remove plug and cage of choke valve for inspect. Found Plug eroded 10% , Cage eroded 10 %, Valve body inside 10%.</p><p><br></p><p>04/07/2025</p><p>- Remove choke valve From HV-05Q1 to install at HV-05M1.</p><p>- Choke valve HV-05Q1 install blind flange 3" 1500#.&nbsp;</p><p>- Pressure test 69 barge., No found leak.</p><p>-&nbsp;Stroke test choke valve HV-05M1. Found valve passing.</p><p><br></p><p>06/07/2025</p><p><u>Replace internal part HV-05M1.</u></p><p>-&nbsp;&nbsp;Remove valve''s actuator.</p>-&nbsp;&nbsp;Remove valve''s bonnet. Found bolt of bonnet corroded and expanded bolt.<p></p><p></p><p>-&nbsp; Can''t unscrew the bolt because the tool is small 1/2 inch drive socket.</p><p><br></p><p>07/07/2025</p><p><u>Replace internal part HV-05M1.</u></p><p>-&nbsp; Remove bolt''s bonnet by using larger tools 3/4 inch drive socket.</p><p>-&nbsp; Remove plug and cage of choke valve for inspect. Found Plug eroded 10% , Cage eroded 50 %, Valve body inside 100%.</p><p>- Replace new seal kit and all internal part.</p><p>- Install bonnet and torque 197 ft.lb.<br>- Install back actuator.<br>- Calibrate and function test valve. Found normal.</p><p></p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/Mechanic/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FMechanic%2FART%2DMECH%2DSMART%2DDMS%2FValve%2FPicture%2FAWP%2D05%2F2025%2E07%2E07%20HV%2D05M&amp;viewid=69417a80%2D5c8c%2D4085%2D8019%2D21267735720d">https://pttep.sharepoint.com/sites/THART/Mechanic/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FMechanic%2FART%2DMECH%2DSMART%2DDMS%2FValve%2FPicture%2FAWP%2D05%2F2025%2E07%2E07%20HV%2D05M&amp;viewid=69417a80%2D5c8c%2D4085%2D8019%2D21267735720d</a><br></p>', '2025-07-08 10:58:10', '2025-07-08 11:13:36', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane', false, 'ART') RETURNING id INTO new_report_id;
