  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting Valve 2LV-50202B Passing I', 'Instrument', 'CM', 'In Progress', '2025-07-09', '<p>Troubleshooting Report: Valve 2LV-50202B Passing Issue</p><p>- Identified issue: Valve 2LV-50202B was found to have internal leakage (bad passing).</p><p>- Action taken: The valve was disassembled for inspection. The plug valve was found to be corroded. The corroded plug valve was sent to the mechanical workshop for grinding and refurbishment.</p><p>- Next Steps: Reassembly of the valve is scheduled for tomorrow, following completion of mechanical work.</p><div><br></div>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/032%20DBS_MEI/3214%20Photo,%20Picture/INSTRUMENT/PPS/2LV-50202B?csf=1&amp;web=1&amp;e=9uKiif">2LV-50202B</a>&nbsp; &nbsp;&lt;&lt;&nbsp; "Click the link to view more pictures"', '2025-07-09 10:52:12', '2025-07-09 14:41:36', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
