  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify open drain caisson pump malfunction.', 'Mechanic', 'CM', 'Completed', '2025-07-09', '<p>On 09 Jul 2025.</p><p>Verify open drain caisson pump malfunction.</p><p>- Running tested found pump not running.</p><p>- Removed pump to W/S and disassembly for investigation found "Removable Pilot Sleeve Assmbly" damaged.</p><p>- Replaced "Removable Pilot Sleeve Assmbly" and Diaphragm.</p><p>- Assembly pump and running test at W/S condition satisfy.</p><p>- Reinstalled pump at worksite.</p><p>- Running tested working porperly but can''t build up pressure.</p><p>- Cleaned up suction strainer (Found 80% Block)</p><p>- Running tested working porperly but can''t build up pressure.</p><p>- Try to supply by fresh water into suction line found Pump running porperly and can build up pressure to 7-8 Bar.</p><p>- Expected the problem from foot valve on suction line.</p><p><br></p><p>On 10 Jul 2025.</p><p>- Asked operation to Running tested found working porperly and can build up pressure.</p><p>- Job completed.</p>', NULL, '2025-07-10 16:00:39', '2025-07-10 17:17:29', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC', false, 'ART') RETURNING id INTO new_report_id;
