  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace Bladder rubber diaphragm of Bladder Tank A', 'Mechanic', 'CM', 'Completed', '2025-07-11', '<p>&nbsp;Process isolation and drain out water inside the tank.</p><p>&nbsp;Disconnect bladder tank assembly and piping connection.</p><p>&nbsp;Remove out Bladder rubber diaphragm from the tank.</p><p>&nbsp;Replace Bladder rubber diaphragm.</p><p>&nbsp;Connect bladder tank assembly and piping connection.</p><p>&nbsp;Fill up air pressure to Bladder tank T-9950A = 1.80 bar-g and Check leak.</p><p>&nbsp;Housekeeping on working area.</p>', NULL, '2025-07-11 08:10:16', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
