-- Inserting report ID 33497
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'X-17-1003 WP-17 BC Preservation and Motball 6Month', 'Mechanic', 'PM', 'Complete', '2025-07-06', '<div>WP-17: Booster compressor</div><div>Performed interval preservation volunteer shutdown and motball 6 Month.</div><div><br></div><div>6 July 2025, (20% Progress)</div><div><p>&nbsp;1 Mech + 4 BC Major.                                   </p><div data-ogsc="black">&nbsp;- Confirm Isolation point and make sure zero pressure in unit.                                </div><div data-ogsc="black">&nbsp;- Installed 2 Ea. battery terminals and connect terminals wiring.                                </div><div data-ogsc="black">&nbsp;- Upload (Backup) Program PLC &amp; PV.                                 </div><div data-ogsc="black">&nbsp;- Apply anti-seize on all secure bolts of Junction Boxes.                                   </div><div data-ogsc="black">&nbsp;- Wrap Denso tape to conduit connector.                                   </div><div data-ogsc="black">&nbsp;- Plastic sheet wrapping on all Instrument end-devices, Control valves, Control panel,</div><div data-ogsc="black">&nbsp; &nbsp;all valves stems and Junction Boxes."</div><div data-ogsc="black"><br></div><div data-ogsc="black">7 Jul 2025, (40% Progress)</div></div><div>&nbsp;4 BC Major.&nbsp;</div><div><div data-ogsc="black" data-olk-copy-source="MessageBody">&nbsp;- Apply VCI on engine valve internal parts including rocker arms and push rods by spray.</div><div data-ogsc="black">&nbsp;- Apply VCI mixture into each spark plug hole.                                  </div><div data-ogsc="black">&nbsp;- Apply VCI mixture into intake manifold.                                 </div><div data-ogsc="black">&nbsp;- Open side cover, apply VCI on all internal part surface by spray.</div><div data-ogsc="black">&nbsp;- Test and Calibration all PT DPT and DPS.</div><div data-ogsc="black"><br></div><div data-ogsc="black">8 Jul 2025, (60% Progress)</div><div data-ogsc="black">&nbsp;1 Mech + 4 BC Major.&nbsp;</div><div data-ogsc="black"><div data-ogsc="black" data-olk-copy-source="MessageBody">&nbsp;- Apply VCI on internal surface of starting gas system by spray.</div><div data-ogsc="black">&nbsp;- Apply VCI on internal parts surface in crankcase by spray.</div><div data-ogsc="black">&nbsp;- Fill up lube oil (30L) and VCI (1L) into compressor crankcase.</div><div data-ogsc="black">&nbsp;- Remove all valves and valve caps to perform visual inspection and cleanup of both throws.</div><div data-ogsc="black">&nbsp;- Apply VCI on internal parts including cylinder assembly of both throws.</div><div data-ogsc="black">&nbsp;- Apply VCI on all valves &amp; valve caps                                    </div><div data-ogsc="black">&nbsp;- Apply VCI into force feed lubricator box by spray.                                  </div><div data-ogsc="black">&nbsp;- Manuals operate pre-lube pump to check its functions.                                </div><div data-ogsc="black">&nbsp;- Function test all instrument devices as applicable. </div><div data-ogsc="black"><br></div><div data-ogsc="black">9 Jul 2025, (80% Progress)</div><div data-ogsc="black">&nbsp;1 Mech + 4 BC Major.</div><div data-ogsc="black">&nbsp;- Apply grease on Shutdown Valve (? 3-5 Stoke).                            </div><div data-ogsc="black">&nbsp;- Preservation cooler fan shaft with Denso Tape.</div><div data-ogsc="black">&nbsp;- Apply VCI mixture 50% with Lube Oil into pipeline and vessels by spray.</div><div data-ogsc="black">&nbsp;- Apply electrical grease on flex-conduit connectors.</div><div data-ogsc="black">&nbsp;- Apply anti-seize on all secure bolts of Junction Boxes.</div><div data-ogsc="black">&nbsp;- Function test all instrument devices LT. and wrapping all devices.</div><div data-ogsc="black">&nbsp;- Plastic sheet wrapping on Control panel.</div><div data-ogsc="black">&nbsp;- Installed tarpaulin on BC unit.&nbsp;</div><div data-ogsc="black"><br></div><div data-ogsc="black">10 Jul 2025, Completed.</div><div data-ogsc="black">&nbsp;1 Mech + 3 BC Major.</div><div data-ogsc="black">&nbsp;- Continue installed tarpaulin on BC unit.</div><div data-ogsc="black">&nbsp;- Prepare tools and parts for transfer to next plan PM.</div><div data-ogsc="black">&nbsp;- Housekeeping working area. </div></div></div>', NULL, '2025-07-11 10:18:01', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-X17-1003.PK', 'GBN-X17-1003.PK', 'BOOSTER COMPRESSOR PACKAGE GBN-WP17', NULL, NULL, 'BOOSTER COMPRESSOR PACKAGE GBN-WP17', 'GBN-WP17', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nopporn P. + 4 BC Major', NULL, 'EXTERNAL', '2025-07-11 10:18:01', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL);
END $$;

