DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PP: Electrical YPM condensate heater E-3160', 'Electrical', 'PM', 'In Progress', '2025-07-11', '<p>Electrical YPM condensate heater E-3160 and performance test.</p><p>&nbsp; &nbsp; -&nbsp;Cleaning and Inspection</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Heater, feeder, and control panel cleaned.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Terminal connections checked and tightened.</p><p>&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;- Visual inspection for signs of damage or wear completed.</p><p>&nbsp; &nbsp; -&nbsp;Insulation Resistance Test at&nbsp;1000 V, Reference: Minimum acceptable insulation resistance for heaters is 100 Megaohm (refer to PEGS).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Measured values:&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Step 1: 3.60 Megaohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Step 2: 6.12 Megaohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Step 3: 2.13 Megaohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Step 4: 1.75 Megaohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong data-start="873" data-end="882">Note:</strong> All readings are below the acceptable threshold. Follow-up action recommended.</p><p>&nbsp; &nbsp; -&nbsp;Temperature Controller Verification</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;Observed discrepancies between sensor and controller readings:</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp;TSH-1 (Step 1): Sensor 21.2 °C, Controller 18.6 °C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;TSH-2 (Step 2): Sensor 22.4 °C, Controller 18.8 °C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;TSH-3 (Step 3): Sensor 20.2 °C, Controller 18.6 °C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;TSH-4 (Step 4): Sensor 34.9 °C, Controller 19.5 °C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<strong data-start="1345" data-end="1354">Note:</strong> Controllers consistently show lower temperatures than sensors; calibration or verification required.</p><p><br></p><h3 data-start="1462" data-end="1478"><br></h3>', '<div>Remarks:</div><div>- Heater insulation resistance is below standard; further inspection or repair needed.</div><div>- Temperature controllers need calibration or sensor checks due to reading discrepancies.</div>', '2025-07-11 20:43:19', '2025-07-11 20:44:51', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
