  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced mechanical seal and bearing NDE P-4510', 'Mechanic', 'CM', 'Completed', '2025-07-12', '1. Removed guard coupling, spacer coupling, and mechanical seal piping.<br>2. Removed guard fan and fan NDE.<br>3. Before measurement check shaft End play = 0.06 mm.<br>4. Before measurement check lift DE bearing = 0.05 mm.<br>5. Before measurement check lift NDE bearing = 0.25 mm.<br>6. Before measurement check D.B.F.F = 299.40 mm.<br>7.Removed housing bearing NDE.<br>8 Removed bearing NDE.<br>9.Removed old NDE mechanical seal.<br>10.Install a new NDE mechanical seal.<br>11.Install new bearing NDE. (Black to Black)<br>12.Install housing bearing NDE<br>13.Install fan and guard NDE.<br>14.After measurement check shaft End play = 0.04 mm.<br>15.After measurement check lift DE bearing = 0.03 mm.<br>16.After measurement check lift NDE bearing = 0.04 mm.<br>17.After measurement check D.B.F.F = 299.45 mm.<br>18.Install spacer coupling.<br>19.Shaft alignment.<br>20.Install guard coupling.<br>21.Install mechanical seal piping all.<br>22.flushing inside pump by water before running pump.<br>23.Top up Barrier seal port NDE = 75%<br>24. Top-up Lube oil T46 DE and NDE bearing.<br>25. MRT pump after repair found normal.<br><br>', 'N/A', '2025-07-13 07:24:21', '2025-07-13 18:04:12', 'PTTEP\\art.mechcrane', 'PTTEP\\art.mechcrane', false, 'ART') RETURNING id INTO new_report_id;
