  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM: 2P-5890 Aviation Fuel Pump Perform 6MPM.', 'Mechanic', 'PM', 'Completed', '2025-07-13', '<p>&nbsp;2P-5890 Aviation Fuel Pump Perform 6MPM.</p><p>- Supply outlet valve condition, operation and condition check.</p><p>- Bonding wire between tank and system pipe work condition check.</p><p>- Suction fuel hose and coupling.</p><p>- Remove, check and clean the inlet strainer (Condition: good and clean).</p><p>- Replace gear oil with Total CARTER SY 220, Q’ty 1.1 liter.</p><p align="left">- Check the coupling condition for cracks, broken or deterioration. (all good)</p><p align="left">- Coupling bolts check and torque appropriately (23Nm.)</p><p>- Turn coupling by hand, freely</p><p align="left">- Check foundation holding down bolts tighten.</p><p align="left">- Retighten the foundation bolts of gear box.</p><p>- Retighten the foundation bolts of pump.</p><p align="left">- Start with Remote mode.</p><p align="left">- Push start at QPS side.</p><p align="left">- 2SOV-58852 switch to open position.</p><p align="left">- Pump running.</p><p align="left">- No abnormal condition and strain noise.</p><p align="left">- No leakage.</p><p>            </p><p align="left">- Discharge pressure 5-7 bar.</p><p align="left">- Pump package clean and tidy.</p>', NULL, '2025-07-13 14:41:21', CURRENT_TIMESTAMP, 'PTTEP\\PataweeJi', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5890', 'GBS-2P-5890', 'AVIATION FUEL PUMP', NULL, NULL, 'AVIATION FUEL PUMP', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patawee J', NULL, 'EXTERNAL', '2025-07-13 14:41:21', CURRENT_TIMESTAMP, 'PTTEP\\PataweeJi', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surachai J.', NULL, 'EXTERNAL', '2025-07-13 14:41:21', CURRENT_TIMESTAMP, 'PTTEP\\PataweeJi', NULL);
