  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG#1 As found check Engine aft mount for referent', 'Turbine Mech', 'OTH', 'Completed', '2025-07-14', '<p>&nbsp;As found measurement Engine aft mount for referent.</p><p>- T= 18.615 "</p><p>- D1 = T-10.89" = 18.615 - 10.89 = 7.725 "</p><p>- D2 = T-9.63" = 18.615- 9.63 = 8.935"&nbsp;</p><p><br></p><p>Formular : R = D1 + D2 / 2&nbsp;</p><p>Results :&nbsp; &nbsp;R = 7.725 + 8.935 / 2&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;<b>R =&nbsp; 8.33 "</b></span></p><p>Remarks : <b style="background-color: rgb(255, 255, 0);">Spec R = 8.5"</b></p>', NULL, '2025-07-14 13:54:49', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechTurbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Somsak Pa.', NULL, 'EXTERNAL', '2025-07-14 13:54:49', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechTurbine', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Vorawit L.', NULL, 'EXTERNAL', '2025-07-14 13:54:49', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechTurbine', NULL);
END $$;

