  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM Replace corroded stud bolts valve bonnet 2"#600', 'Mechanic', 'CM', 'Completed', '2025-07-14', '<p>Replace corroded stud bolts at valve bonnet line 2"-NG-236116-F01S. (1 ea.)</p><p>&nbsp; - 2F-3630B Adsorber Dust Filter B. (Valve location at main deck fuel gas skid.)</p><p>&nbsp; - Note : Reference Anomaly report WO# 500633053, 2024 Inspection campaign, anomaly report follow&nbsp;</p><p>As found:&nbsp;</p><p><font color="#0000ff">Stub bolt condition onsite should be replace 3 ea. as the picture shows</font></p><p>Globe valve 2"#600</p><p>Activity:&nbsp;</p><p>1. Remove paint and 3 each of nut. ( one by one)</p><p>2. Visua check stub bolt condition and spec.&nbsp;</p><p>3. Apply anti-seize and retighten.</p><p>4. apply torque 78 ft-lb. (105 Nm.)</p><p>5. Pressure leak test. No leak</p><p><br></p><p>Note:&nbsp; Stub size: 5/8"&nbsp; Nut size: 1-1/16"</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Bonnet Bolt: A193-B7</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Bonnet Nut: A194-2H</p><p><br></p>', NULL, '2025-07-14 14:00:27', '2025-07-14 17:00:51', 'PTTEP\\KittipongSam', 'PTTEP\\GBS.Turbine-Mech', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2F-3630.PK', 'GBS-2F-3630.PK', 'ADSORBER DUST FILTER PACKAGE', NULL, NULL, 'ADSORBER DUST FILTER PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
