  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS control panel''s pilot lamp error in guard house', 'Electrical & Instrument', 'CM', 'Completed', '2025-07-14', '<h3 class="modal-title displayform"><p><u>Today Activity</u></p><p>Troubleshoot pilot lamps error on control panel in security guard house building electrical room.</p><p><br></p><p><u>Action</u>&nbsp;</p><p>- Found power signal pilot lamp on ACDB-8107 was defective.</p><p>- Replace new and back to normal.</p><p>- Found another pilot lamp for fault signal on ACDB-8108 was abnormal condition.</p><p>- Lamp was ON even there was no breaker fault.</p><p>- Found fuse was broken and replace new one, but lamp was still ON.</p><p>- Then, checked loop terminals for fault alarm on breakers.</p><p>- Found QF12 breaker had wrong termination for fault signal looping. (NC to NO)</p><p>- Corrected termination on QF-12 breaker.</p><p>- Function breaker fault to check fault alarm activation.</p><p>- Back to normal and fault alarm can be monitored properly.</p><p><br></p></h3>', NULL, '2025-07-14 18:13:09', '2025-07-15 06:52:28', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
