  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'QP: Replace PT-6215 due to manifold valve corroded', 'Instrument', 'CM', 'Complete', '2025-07-16', '<p>Replacement of Pressure Transmitter PT-6215</p><p>&nbsp; &nbsp; - PT-6215 was found to be defective due to a corroded manifold valve.&nbsp;</p><p>&nbsp; &nbsp; - Replaced PT-6215 with a new pressure transmitter as per the following specifications:</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;<span data-start="483" data-end="493">Brand:</span> ROSEMOUNT</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;<span data-start="510" data-end="520">Model:</span> 3051TG3A2B21AKDM5C1</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;<span data-start="547" data-end="569">Calibration Range:</span> 0 to 700 psi (Normal Operating Range: 0 to 15 bar)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;- Conducted a functional test in coordination with CCR. The transmitter performed satisfactorily, and the test results were within acceptable parameters.</p><p><br></p><p data-start="777" data-end="800"><span data-start="777" data-end="798">Notes:</span></p><p> </p><ul data-start="801" data-end="924"> <li data-start="801" data-end="852"> <p data-start="803" data-end="852">Field working voltage measured at <span data-start="837" data-end="850">19.74 VDC</span></p> </li> <li data-start="853" data-end="924"> <p data-start="855" data-end="875">Terminal voltages:</p> <ul data-start="878" data-end="924"> <li data-start="878" data-end="900"> <p data-start="880" data-end="900"><span data-start="880" data-end="888">+/E:</span> 23.05 VDC</p> </li> <li data-start="903" data-end="924"> <p data-start="905" data-end="924"><span data-start="905" data-end="913" >-/E:</span> 3.27 VDC</p></li></ul></li></ul>', NULL, '2025-07-16 18:57:16', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-PT-6215', 'GBN-PT-6215', 'PRESSURE TRANSMITTER', NULL, NULL, 'PRESSURE TRANSMITTER', 'GBN-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Prin', NULL, 'EXTERNAL', '2025-07-16 18:57:16', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL);
