-- Inserting report ID 33865
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM 2A-5525A Replace shaft and bearing&4KPM', 'Mechanic', 'CM', 'Completed', '2025-07-16', '<p><b>Running hour:</b> 3,734 hrs.</p><p><b>As found:&nbsp;</b></p><p>Abnormal noise was detected while the unit was running.</p><p>It was found that the shaft is worn out at the bearing inner race</p><p>The set screw was loose, causing the inner race and shaft to rotate independently.</p><p><br></p><p><b>Remedy:&nbsp;</b></p><p>1. Replace new shaft and upper/lower bearing.</p><p>2.<b>&nbsp;</b>Adjust the shaft to a 90-degree angle.</p><p>3. Reinstall the fan taper bush onto the fan hub. Adjust the distance accordingly.</p><p>4. Reinstall the fan pulley and align it with the motor pulley.</p><p>5. Reinstall existing V-belt and adjust tension.</p><p>6. Test run, normal running.</p><p><br></p><p>The lube oil cooler 2A-5525B is now in normal running condition.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', NULL, '2025-07-16 22:50:07', '2025-07-17 00:05:02', 'PTTEP\\KittipongSam', 'PTTEP\\KittipongSam', false, 'G2S') RETURNING id INTO new_report_id;
