-- Inserting report ID 33890
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot valve greasing tool malfunction', 'Mechanic', 'CM', 'Completed', '2025-07-17', '<p>Troubleshoot valve greasing tool malfunction:<br><br></p><p>Action,</p><p>1-&nbsp; Removed air motor assembly.</p><p>2-&nbsp; Removed coupling V-Retainer.</p><p>3.&nbsp; Removed hydraulic reservoir assembly.</p><p>4.&nbsp; Removed early style air piston.</p><p>5.&nbsp; Check and clean the air piston.</p><p>6.&nbsp; Replace o ring and back up washer of air piston.</p><p>7.&nbsp; Check the spring washer tension.</p><p>8.&nbsp; Removed hydraulic body assembly.</p><p>9.&nbsp; Checked the relief valve assembly.</p><p>10. Removed reservoir cap.</p><p>11. Replaced new o ring of reservoir cap.</p><p>12. Removed and checked the diaphragm.</p><p>13. Reinstall hydraulic body assembly.</p><p>14. Reinstall air piston assembly.</p><p>15. Top up hydraulic oil.</p><p>16. Checked the air line for leakage.</p><p>17. Function test for pump.</p><p>18. Check that all connection are tight for hydraulic leakage.</p><p>19. Place pump on horizontal position.</p><p>20. Reinstall sealant barrel.</p><p>21. Set air supply pressure to 4-6 bar.</p><p>22. Move pump treadle to release position.</p><p>23. Perform function test for valve greasing tool.</p><p>24. Housekeeping around the working area.</p><p><br></p><p><br></p><p><br></p><p><br></p>', 'Replaced new O-ring of air piston and back up washer of hydraulic body.', '2025-07-17 17:33:40', '2025-07-22 07:10:49', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
