  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neymar', NULL, 'EXTERNAL', '2025-07-17 17:33:40', '2025-07-22 07:10:49', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec');
