-- Inserting report ID 33968
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TEK-3200, Performed crank soak wash on 18 Jul 2025', 'Mechanic', 'OTH', 'Complete', '2025-07-18', '<ul type="disc">  <li>TEK-3200, Performed engine crank soak wash and firing      the unit. <span style="background-color: rgb(255, 255, 0);">(For engine change out)</span></li><li><br></li>  <li>-&nbsp; Prepared equipment and tools to perform crank soak      wash by follow up&nbsp;<i>PROCEDURE.</i></li>  <li>-&nbsp; Request laboratory technician to took sample before      and after crank soak wash.</li>  <li>-&nbsp; Performed solution wash 2 times.</li>  <li>-&nbsp; Kept 30 minutes for soaking time.</li>  <li>-&nbsp; Performed rinse water wash 4 times. (300 Litters).</li>  <li>-&nbsp; Purged crank for 2 times for crank drying about 10      minutes.</li>  <li>-&nbsp; Reinstalled all accessories and parts back to their      normal conditions.</li>  <li>-&nbsp; General cleaned and cleaning inside the enclosure /      air inlet filter room.&nbsp;</li>  <li>-&nbsp; Started the engine for firing about 15 minutes.</li>  <li>-&nbsp; Unit stop and keep stand by.,R/H. 47,564.7 hrs.</li> </ul>  <p>&nbsp;</p>  <p>&nbsp;The results of Chloride content on Stainless Steel Surface of&nbsp;Turbo Compressor train#1 (TEK-3200)&nbsp;</p><p><br></p>  <table border="0" cellspacing="0" cellpadding="0" width="337">  <tbody><tr>   <td width="270" nowrap="">   <p align="center">Sample Point</p>   </td>   <td width="67" nowrap="">   <p align="center">Cl-(µg/cm2)</p>   </td>  </tr>  <tr>   <td width="270" nowrap="">   <p align="center">Air Inlet&nbsp;before cleaning</p>   </td>   <td width="67" nowrap="">   <p align="center">2.74</p>   </td>  </tr>  <tr>   <td width="337" nowrap="" colspan="2">   <p align="center">&nbsp;</p>   </td>  </tr>  <tr>   <td width="270" nowrap="">   <p align="center">Area below rotor&nbsp;before   cleaning</p>   </td>   <td width="67" nowrap="">   <p align="center">1.11</p>   </td>  </tr>  <tr>   <td width="270" nowrap="">   <p align="center">Area below rotor&nbsp;after   cleaning</p>   </td>   <td width="67" nowrap="">   <p align="center">0.96</p>   </td>  </tr>  <tr>   <td width="337" nowrap="" colspan="2">   <p align="center">&nbsp;</p>   </td>  </tr>  <tr>   <td width="270" nowrap="">   <p align="center">Area rotor&nbsp;before cleaning</p>   </td>   <td width="67" nowrap="">   <p align="center">2.17</p>   </td>  </tr>  <tr>   <td width="270" nowrap="">   <p align="center">Area rotor&nbsp;after cleaning</p>   </td>   <td width="67" nowrap="">   <p align="center">0.82</p>   </td>  </tr> </tbody></table>  <p>&nbsp;</p>  <p>Remark : (Criteria) Chloride content is not over <span style="background-color: rgb(255, 255, 0);">20 ug/cm2</span></p>', NULL, '2025-07-18 19:05:14', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TEK-3200', 'GBN-TEK-3200', 'TURBO COMPRESSOR TRAIN1', NULL, NULL, 'TURBO COMPRESSOR TRAIN1', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
