  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S flow transmitter at G-8930.', 'Electrical & Instrument', 'CM', 'Completed', '2025-07-19', '<h3 class="modal-title displayform"><p><u>Today Activity</u></p><p>Electrical isolation/deisolation G8930 to troubleshoot FIT-89300 error.</p><p><br></p><p><u>Action</u>&nbsp;</p><p>- Inform CCR and electrical isolation/ deisolation for G-8930.</p><p>- Record in electrical isolation log record.</p><p>- Checked flow transmitter value in generator stopped time.</p><p>- Found transmitter showed 2.9 SCFM.</p><p>- Performed process isolation by opt team.</p><p>- Checked LOPC at transmitter flange. (No seeping)</p><p>- Isolated manifold of transmitter and open equalizing valve.</p><p>- Checked transmitter mA with hart protocol.</p><p>- Vent trapped pressure of transmitter.</p><p>- Values are not stable.</p><p>- Performed zero calibration and check</p><p>- Then, service operation of transmitter and checked again zero value.</p><p>- Value is stable and performed process deisolation.</p><p>- Now, it is under monitoring.</p><p>- Performed electrical de-isolation.</p><p>- Tomorrow will test run G-8930.</p></h3>', NULL, '2025-07-19 17:23:21', '2025-07-19 18:34:55', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Se-EI', false, 'ATL') RETURNING id INTO new_report_id;
