  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 2K PM Day 1 on G-8920', 'Mechanic', 'PM', 'In Progress', '2025-07-20', '<p><u>Action</u></p><div>- Prepare tools and Set up equipment.</div><div>- Drained the lube oil.</div><div>- Remove the sight glass cover.</div><div>- Check the o ring condition.</div><div>- Clean the sight glass cover.</div><div>- Apply dow corning grease to o ring.</div><div>- Reinstall sight glass.</div><div>- Topped up lube oil (Methana-240 L).</div><div>- Replaced lube oil filters (6 EA).</div><div>- Replaced the breather filters (2 EA).</div><div><div>- Removed the alternator and its guard.&nbsp;</div><div>- Removed the alternator mounting bracket.</div><div>- Removed the alternator driver pulley.</div><div>- Removed the alternator shaft oil seal.</div><div>- Checked and cleaned the shaft oil seal cover.</div><div>- Replaced the alternator shaft oil seal and gasket.</div><div>- Replaced new alternator driver pulley and taper bush assembly.</div><div>- Installed the shaft oil seal cover. (13mm ~ 25Nm)</div><div>- Installed the alternator driver pulley. (5mm Allen Key Socket ~ 22Nm)</div><div>- Installed the alternator mounting bracket. (17mm ~ 45 Nm)</div><div>- Replaced the alternator belt.</div><div>- Adjusted and tightened the alternator belt tension.</div><div>- Installed the alternator. (16mm ~ 66Nm &amp; 14mm ~ 40Nm)</div><div>- Installed the alternator guard. (10mm ~ 13Nm)</div><div><br></div><div><p><u>Required Tools</u></p><div>- 8mm &amp; 5mm Allen Key Socket Head</div><div>- Torque Wrenches</div><div>- Screwdrivers</div><div>- Feeler Gauges</div><div>- Scrapers</div><div>- Spark Plugs Remover(Special Tool)</div><div>- Electrical tape</div><div>- Plastic Bags (Red)</div><div>- Marker Pen</div><div><div>- Lube oil drain pump and hose</div><div>- Lube oil top up pump</div><div>- Methana (2Drums)</div><div>- Empty Drum (2Drums)</div><div>- 2 Pallets</div><div>- Electrical Extension</div><div>- Pipe Wrench</div><div>- Belt Wrench</div></div></div></div>', NULL, '2025-07-20 17:33:05', '2025-07-24 11:35:07', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Se-Mech', false, 'ATL') RETURNING id INTO new_report_id;
