  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM:2X-2573:Crane WPS-15:Pull load test', 'Mechanic', 'PM', 'Completed', '2025-07-19', '<div>&nbsp;Pull Test Prepare by Beam Clamp&nbsp;<br><br></div><div>- Connect the beam clamp with the applicable lifting gear to the crane hook to be tested.&nbsp;</div><div>- Connect a load monitoring device. (Dynamometer, portable load cell etc.)&nbsp;</div><div>- Main/Auxiliary hook&nbsp;</div><div>- Recheck equipment after assembly lifting gear with crane hook.&nbsp;</div><div>- Place crane boom in proper boom radius as identified on the crane’s load chart for pull&nbsp;</div><div>test. 68.2</div><div>- Assure that beam clamp is attached beam structure firmly before pulling.<br>- Put and clamp on beam platform at boom crane at max SWL and then gradually hoist up&nbsp;</div><div>load weight.<br>- Pull load test gradually up and observe abnormal thing between pull tests.<br>- Hold the old position about 5 min.&nbsp;</div><div>- Check cylinders drop and winch slippage.&nbsp;</div><div>- Through visual inspection and functional test, the crane after completion of pull test.&nbsp;</div>', NULL, '2025-07-21 09:12:23', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
