  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Direk T.', NULL, 'EXTERNAL', '2025-07-21 09:12:23', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL);
