  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '6MPM IN Sales Gas Moisture Analyzer AIT-1685', 'Instrument', 'CM', 'In Progress', '2025-07-23', '<p>6MPM IN Sales Gas Moisture Analyzer AIT-1685.</p><p>- Continued TS Moisture reading is more than 100 lbs/MMSCFD after as found by Moisture Generator (normal reading is around 0.976 +/-10% lbs/MMSCFD as per nameplate).&nbsp;</p><p>- Observed LED CR1 (XTAL Heater Oven) is always on (it should be indicated blinking while Cell Oven Heater duty cycle) and found alarm <font color="#ff0000">Cell Temp Alert </font>and <font color="#ff0000">Generator Temp Alert</font></p><p>&nbsp; &nbsp;&nbsp; &nbsp;</p><p><br></p><p>- Verified Oven Temperature and MG Temperature by measure thermistor RT1 and RT2 as found feedback resistance are 29.3 kOhm and 25.6 kOhm which more than label on nameplate Cell Oven 22.12 kOhm @ 60''c and MG 23.1 kOhm @ 60''c.</p><p>- Adjusted R17 by disconnect socket J1 and measure P1/1-4 untill feedback resistance stable 22.2 kOhm.</p><p>&nbsp; &nbsp;&nbsp; &nbsp;<br></p><p><br></p><p>- Adjusted R26 by disconnect socket J2 and measure P2/2-3 untill feedback resistance stable 23.04 kOhm.</p><p> &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</p><p><br></p><p>- Trial to swop inlet VL3 (MG) and VL4 (Smpl) for verify the high reading that found moisture is low during MG feed and moisture high during Sample feed.&nbsp;</p><p></p><p>&nbsp; &nbsp;<br></p><p><br></p><p>- Replaced Cystal Cell (PN: 560203060, SN: 52127.1) and Control Board (PN: 560039-905, SN: E2606031YC) back to existing, validate reading is still high when feeding MG.</p><p>&nbsp; &nbsp;<br></p><p><br></p><p>- Send TS data to K.TeerapatB (PPD/S) for consultant.</p><p>Inprogress.</p>', NULL, '2025-07-23 15:21:52', '2025-07-24 15:47:04', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-ME-1685', 'ART-ME-1685', 'MOISTURE ELEMENT', NULL, NULL, 'MOISTURE ELEMENT', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-MT-1685', 'ART-MT-1685', 'MOISTURE TRANSMITTER', NULL, NULL, 'MOISTURE TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-SK-1685', 'ART-SK-1685', 'SALES GAS MOISTURE ANALYSER', NULL, NULL, 'SALES GAS MOISTURE ANALYSER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saralrat K.', NULL, 'EXTERNAL', '2025-07-23 15:21:52', '2025-07-24 15:47:04', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong I.', NULL, 'EXTERNAL', '2025-07-23 15:21:52', '2025-07-24 15:47:04', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
