-- Inserting report ID 34370
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify and troubleshoot ELCB not trip in ZBV1 D-3', 'Electrical & Instrument', 'CM', 'In Progress', '2025-07-25', '<p><b><u>Today Activity</u></b></p><p>Verify and troubleshoot ELCB not trip in ZBV1</p><p><br></p><p><b><u>Action</u></b></p><p>-Test run G-8010&nbsp;</p><p>- Switch breaker 5QF of DCUPS panel.</p><p>- Perform ELCB function test. (Failed)</p><p>- Performed ground test for every ground cable on the main ground bar. (Normal)</p><p>- Stop running G-8010</p><p>- Performed insulation test line cable with ground from main breaker of G-8010 to bus bar. (&gt;220 M ohm)</p><p>&nbsp; ( Remark - need to remove sensor cable like ( R,S &amp; T) on bus bar)</p><p>&nbsp; ( If not remove sensor cables, insulation result will be 0.31 M Ohm)</p><p>- Performed insulation cable test from bus bar to load breakers (198 M Ohm)</p><p>- Next day continue checking insulation test for breaker outlets</p><p><br></p><p><b><u>History (23-July-2025)</u></b></p><p><b><u>Action 1</u></b></p><p>Isolate Diesel engines (G8010 and G8020) of ZBV1.</p><p>Install back ELCB (1QF).</p><p>Deisolate engines and start G8010 from CCR.</p><p>Test ELCBs function 30mA test with RCD tester . (Not Trip).</p><p>Check all ohm value of Earth Cables with Ground tester.</p><p>Found that 650 Ohm at Solar Panels body ground cable.</p><p>Disconnected Solar Panels ground cable from ZBV1 Earth point.</p><p>Then, test again ELCBs function 30mA test with RCD tester. ( Not trip, No OK).</p><p><b><u><br></u></b></p><p><b><u>Action 2 (after lunch)</u></b></p><p>Remove spare earth cables from earth bar.</p><p>Check N and E continuity (OL), Check insulation test with Mega Ohm (N-E = 0.05MOhm)&nbsp;</p><p>Test ELCBs function 30mA test with RCD tester . (Not Trip).</p><p>Re-instate all spare cables and termination. (In Progress)</p><p><br></p><p><br></p>', NULL, '2025-07-25 18:03:38', '2025-07-25 18:43:13', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-LVSWB-8101', 'ATL-BV1-LVSWB-8101', 'CP, ZBV1 LOW VOLT SWITCHBOARD', NULL, NULL, 'CP, ZBV1 LOW VOLT SWITCHBOARD', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
