-- Inserting report ID 34489
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify and Troubleshoot ZBV 1 UPS system Day-2', 'Electrical & Instrument', 'CM', 'In Progress', '2025-07-27', '<p><b><u>Today Activity</u></b></p><p>Verify and Troubleshoot ZBV 1 UPS system. (No DC output)</p><p><b><br></b></p><p><b><u>Root cause&nbsp;</u></b></p><p>Main transformer output1 and output2 have only 31.7 VAC and 0VAC instead of 230 VAC.</p><p><b><br></b></p><p><b><u>Action</u></b></p><p>-Test Run G-8010 from CCR to verify UPS system voltage checking.</p><p>-Check and measure (2T001) main transformer voltage.</p><p>-Tx Input= 401.2 VAC, output1=31.7 VAC, output2= 0 VAC.</p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">History (25-07-2025)</b></p><p><b style="background-color: rgb(255, 255, 0);">Today Activity</b></p><p><span style="background-color: rgb(255, 255, 0);">-Verify and Troubleshoot ZBV 1 UPS system.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b style="background-color: rgb(255, 255, 0);">Found</b></p><p><span style="background-color: rgb(255, 255, 0);">--Rectifier Unit&nbsp; is not working and generate 24 VDC.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b style="background-color: rgb(255, 255, 0);">Action</b></p><p><span style="background-color: rgb(255, 255, 0);">-Test run G8010 with manual mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found that ZBV1 DC UPS Gutor panel ; No Output 24 VDC and No display light.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Measure Input and output MCCBs. (AC= 440 VAC, DC= 0VCDC).</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check Transformer T05 (Input=440VDC, Output= 230.3VDC).</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check PSU of all control card and display card. (No Voltage)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check capacitors (10.4 uF)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found Rectifier Unit&nbsp; is not working and produce 24 VDC.</span></p><p><br></p><p><br></p>', NULL, '2025-07-27 16:01:45', '2025-07-27 16:02:05', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
