  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TEK-3200 fire and gas system grounding alarm.', 'Instrument', 'CM', 'Complete', '2025-07-26', '<p data-start="111" data-end="179"><strong data-start="111" data-end="179">T/S TEK-3200 Fire and Gas System – Grounding Alarm Investigation</strong></p><p> </p><ul data-start="181" data-end="843"> <li data-start="181" data-end="240"> <p data-start="183" data-end="240">&nbsp;- Initial fault identified: Fire and Gas Alarm 24 SHD B1.</p> </li> <li data-start="241" data-end="312"> <p data-start="243" data-end="312">&nbsp;- When checked, the alarm had already cleared.(as found, no active alarm).</p></li><li data-start="313" data-end="447"><ul data-start="152" data-end="610"> <li data-start="254" data-end="332"> <p data-start="256" data-end="332">&nbsp;- All sensors (Gas, Heat, and Flame) were checked and tested for insulation.</p> </li> <li data-start="333" data-end="403"> <p data-start="335" data-end="403">&nbsp;- All sensors were working normally, and insulation was above 55 MO.</p> </li> <li data-start="404" data-end="503"> <p data-start="406" data-end="503">&nbsp;- Replaced all gas sensors in enclosures GD-42501, GD-42502, and GD-42503 with new spare sensors.</p> </li> <li data-start="504" data-end="556"> <p data-start="506" data-end="556">&nbsp;- Calibrated all new gas sensors and transmitters.</p> </li> <li data-start="557" data-end="610"> <p data-start="559" data-end="610">&nbsp;- System was returned to normal service after successful testing and verification.</p></li></ul></li></ul>', NULL, '2025-07-27 18:10:31', '2025-07-27 18:22:09', 'PTTEP\\Bongkot.EI-Workshop', 'PTTEP\\Bongkot.EI-Workshop', false, 'G2N') RETURNING id INTO new_report_id;
