-- Inserting report ID 34510
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TEK-3200 Mark XI ground fault', 'Instrument', 'CM', 'Complete', '2025-07-26', '<p>T/S TEK-3200 Mark XI ground fault.</p><p> </p><ul data-start="114" data-end="706"> <li data-start="114" data-end="193"> <p data-start="116" data-end="193">&nbsp;- Found an intermittent ground fault alarm on the Mark XI HMI panel (24 VDC).</p> </li> <li data-start="194" data-end="296"> <p data-start="196" data-end="296">&nbsp;- Alarm set point was for ground voltage above 5 VDC; readings were fluctuating between 4.2–5.4 VDC.</p> </li> <li data-start="297" data-end="379"> <p data-start="299" data-end="379">&nbsp;- Also noticed the SDV-3211 valve was showing a “close status fault” repeatedly.</p> </li> <li data-start="380" data-end="468"> <p data-start="382" data-end="468">&nbsp;- Performed insulation test on ZHL-3211 and found low insulation resistance (0.06 MO).</p> </li> <li data-start="469" data-end="533"> <p data-start="471" data-end="533">&nbsp;- Inspected feedback of SDV-3211 and found water inside the feedback unit.</p> </li> <li data-start="534" data-end="582"> <p data-start="536" data-end="582">&nbsp;- Replaced the feedback with a new spare part.</p> </li> <li data-start="583" data-end="706"> <p data-start="585" data-end="706">&nbsp;- After replacement, insulation resistance returned to normal (&gt;55 MO), and the ground fault reading stabilized at 4.2 VDC.</p></li></ul>', NULL, '2025-07-27 18:21:44', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TEK-3200-TCP', 'GBN-TEK-3200-TCP', 'TURBINE CONTROL PANEL (SPEEDTRONIC MKIV)', NULL, NULL, 'TURBINE CONTROL PANEL (SPEEDTRONIC MKIV)', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
