BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Mobile Generator ART-G-03 6M PM.', 'Mechanic', 'PM', 'Completed', '2025-07-28', '- Replaced engine lube oil = 8 liters<br>- Replaced engine lube oil filters.<br>- Replaced fuel filter/ water separator.<br>- Replaced Air filters element.<br>- Removed HYD. Starter for inspection pinion gear and fly wheel result all are normal condition.<br>- Removed flame arrestor for inspection and cleaning found flame arrestor block about 70%, reinstall back after cleaned.<br>- Replace cooler fan belt / Generator belt and adjusted belts tension.<br>- Checked engine coolant found normal.<br>- Checked HYD. Oil tank level result level is normal after recharge is 50% remaining.<br>- Checked diesel fuel oil tank level result level is normal about 60-70 %.<br>- Cleaning package.<br>- Start Mobile Generator for test run results Engine and Generator running as normal.', '<span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">1. Engine Oil,Filter, CAT 7W-2326 MESC: 37.68.51.103.3 = 1 ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">2. Water fuel separator, CAT 441-5111 MESC: 43.46.12.054.9 = 1 ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">3. Air Filter (Inner) DONALDSON, P829332 MESC: 58.65.01.102.9 = 1 ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">4. Fuel filter PERKEINS, P/N 4816636 MESC: 43.46.12.055.9 = 1 ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">5. Engine oil MESC: 87.13.90.025.9 = 2 ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">6. Cooler fan belt MESC: 58.14.18.901.9 = 1 ea.</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">7. Generator belt MESC : 58.14.18.902.9 = 1 ea</span><br style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px; background-color: rgb(250, 250, 250);">8..Lube oil, PTT Synthetic 5W-40 Quantity = 2 Gallon</span>', '2025-07-29 08:25:50', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL, false, 'ART') RETURNING id INTO new_report_id;
