  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS G8930 cannot start in weekly test run activity', 'Electrical & Instrument', 'OTH', 'In Progress', '2025-07-29', '<p><u><b>Today''s Activity</b></u><br></p><p>Weekly test run gas generator G8930</p><p><br></p><p><b><u>Action</u></b></p><p>- Adjust fuel pressure 15Kpa from PCV of G-8930.</p><p>- Test run again G-8930.</p><p>- Generator cranking was over 400 RPM and then tripped by Sd, low oil pressure alarm.</p><p>- Restart gas generator again.</p><p>- Generator cranked PRM cannot reach over 150 RPM.</p><p>- Changed battery bank and start again. (Failed)</p><p>- Next day, we will recharge battery at maintenance battery room.</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Performed test run by manual.</span></p><p><span style="background-color: rgb(255, 255, 0);">- G8930 can''t start with under speed alarm at the first time.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Second time, start G8930. (around 150 RPM).</span></p><p><span style="background-color: rgb(255, 255, 0);">- Can''t start in cranking state.</span></p><p><span style="background-color: rgb(255, 255, 0);">-To be troubleshoot after PTW.</span></p>', NULL, '2025-07-29 16:19:28', '2025-08-05 07:10:31', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
