-- Inserting report ID 34624
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM P-5030A Perform 6M PM.', 'Mechanic', 'PM', 'In Progress', '2025-07-29', '<p align="left">1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Suction Strainer</u></p><p align="left">Cleaning strainer.&nbsp;(80% blocked)</p><p align="left">Visual strainer condition.</p><p align="left">Clean sealing surface on RTJ groove.</p><p align="left">Replace RTJ gasket R45D.</p><p align="left">Torque value: 597 ft-lb (809Nm)</p><p align="left">2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Min flow check valve</u></p><p align="left">Cleaning.</p><p align="left">Visual check sealing surface on body and disc.<u></u></p><p align="left">Visual check mechanism.</p><p align="left">Clean sealing surface on RTJ groove.</p><p align="left">Replace RTJ R37D gasket.</p><p align="left">Ensure flow direction is correctly.</p><p align="left">Torque value: 597 ft-lb (809Nm)</p><p align="left">3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Discharge check valve</u></p><p align="left">Cleaning<u></u></p><p align="left">Visual check sealing surface on body and disc.</p><p align="left">Visual check mechanism. (good condition)</p><p align="left">Clean sealing surface on RTJ groove.</p><p align="left">Replace RTJ R45D gasket.</p><p align="left">Ensure flow direction is correctly.</p><p align="left"></p><p align="left">Torque value: 597 ft-lb (809Nm)</p><p align="left">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Lube oil bearing</u></p><p align="left">Lubrication: PTT Hydraulic 46</p><p align="left">Drain, flushing and check condition</p><p align="left">Replace bronze gasket (if necessary)</p><p align="left">DE Capacity: 0.82 liter</p><p align="left"></p><p align="left">NDE Capacity: 0.77 liter</p><p align="left">5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Mechanical Seal</u></p><p align="left">Retighten mounting bolt.</p><p align="left"></p><p align="left">No liquid seep or leaking.</p><p align="left">6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Barrier fluid system</u></p><p align="left">Check N2 Pre-charge pressure:</p><p align="left">Re-charge N2</p><p align="left">DE= 7.2 Bars.</p><p align="left">NDE=7.2 Bars.</p><p align="left">Spec: 7.2 Bar.</p><p align="left">Check pressure/temperature gauge condition.</p><p align="left"></p><p align="left">Check any leakage at flange joint/fin tube.</p><p align="left">7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Coupling</u></p><p align="left">Retighten bolt.</p><p align="left">Check condition of membrane element.</p><p align="left"></p><p align="left">Remove rust and preserve.</p><p align="left">8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Alignment</u></p><p align="left"></p><p align="left">Recheck alignment.</p><p align="left">Alignment value is in acceptable. No need to realignment.</p><p align="left">9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Cleaning and Preserve package</u></p><p align="left">Remove corroded and rusty on structure and bolt nut.</p><p align="left">Preserve with grease/soft seal/Zing It</p><p align="left"></p><p align="left">Cleaning with Oiler-1</p>', 'Photo Link :&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/6.%20Picture/61.%20PPS%20Equipment%20Picture/All%20pumps/2P-5030%20Produce%20Water%20re-injection%20pump/2P-5030A/2025/2025.07.29%20Perform%206MPM?csf=1&amp;web=1&amp;e=Z04wCT">2025.07.29 Perform 6MPM</a>', '2025-07-29 16:46:39', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5030A', 'GBS-2P-5030A', 'PRODUCED WATER RE-INJECTION PUMP A', NULL, NULL, 'PRODUCED WATER RE-INJECTION PUMP A', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dilok T.', NULL, 'EXTERNAL', '2025-07-29 16:46:39', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
