  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C)TG#1 T/S Starter VFD Fault – FN_UF1300_Fault', 'Instrument', 'CM', 'Under Monitoring', '2025-07-29', '<div class="ewa-rteLine">(C)TG#1 T/S Starter VFD Fault – FN_UF1300_Fault</div><div class="ewa-rteLine">-The fault code displayed on the VFD HMI was ''Fault Code 83 – Port 3 DPI Loss''</div><div class="ewa-rteLine">-	Identified that the motor thermistor wiring was not securely connected then retightened the connections to ensure proper contact.</div><div class="ewa-rteLine">-	Repositioned both the instrument wiring and the HIM (Human Interface Module) wiring to improve layout and reduce interference.</div><div class="ewa-rteLine">-	Changed the DPI fault action settings for ports 1, 2, and 3 from “Fault” to “Hold Last” to maintain the last valid stage command during communication faults.</div><div class="ewa-rteLine">-	System will be kept under observation for any recurring faults or abnormal behavior.</div>', NULL, '2025-07-29 17:08:21', '2025-07-29 17:17:44', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\GBS.Turbine-Tech', false, 'G2S') RETURNING id INTO new_report_id;
