-- Inserting report ID 34680
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify/TS ZBV2 Generators failure status at SCADA', 'Electrical & Instrument', 'CM', 'Completed', '2025-07-30', '<p><b><u>Today Activity</u></b></p><p>Verify/TS ZBV2 Generators failure status at SCADA.</p><p><br></p><p><u><b>Found</b></u></p><p>1) Lighting and Genset Charging inverter trip at ZBV2.</p><p>&nbsp; &nbsp; -G8310 and G8320 Low battery voltage trip alarm.</p><p>&nbsp; &nbsp; -G8310 lost auto/ remote mode.</p><p>2) ZBV2 UPS output voltage is out of range(36.7VDC) while Genset running.</p><p>&nbsp; &nbsp; -Lighting and Genset Charging inverter trip due to UPS voltage out of range.</p><p>&nbsp; &nbsp; -Ventilation fans inverter trip due to UPS voltage out of range.</p><p><br></p><p><b><u>Action1</u></b></p><p>-Reset/Restart Lighting and charging inverter.</p><p>-Check the Genset battery charging system.</p><p>-Replace new battery G8310.</p><p>-Set G8310 to auto/remote mode set point.</p><p>-Start G8310 from remote CCR. (Run Properly)</p><p><b><u><br></u></b></p><p><u><b>Action2</b></u></p><p>-Check and verify ZBV2 UPS system while G8310 is running.</p><p>-Measure UPS panel transformer in and out voltage. (input=400 VAC, output= 31.9 VAC)</p><p>-Found distribution voltage have 36.7VDC. (out of range) and can trip inverters.</p><p>-Stop DC UPS system and reset all inverter back to normal.</p><p><br></p><p><b><u>Conclusion&nbsp;</u></b></p><p>-ZBV2 solar system and all inventor are back to normal.</p><p>-DC UPS system output voltage is out of range and it can cause all inventors trip while generator ran.</p><p>-G8130 is back to service.</p><p>-G8320 voltage is low and still charging. (to follow up next activity)</p><p><b><u><br></u></b></p><p><br></p><p><br></p><p><br></p>', NULL, '2025-07-30 16:49:09', '2025-07-30 18:20:58', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
