-- Inserting report ID 34711
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Function test Kx valve on WPS-17', 'ROMO', 'PA', 'In Progress', '2025-07-30', '<p>WPS-17 Activities</p><p>- Function test Kx valve BK-S17-N</p><p>&nbsp; Performed blowdown via test separator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Kx valve setting : Nitrogen pressure at 32 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Result : Kx valve remained closed.</p><p>&nbsp; &nbsp; Choke valve position : 95%</p><p>&nbsp; &nbsp; &nbsp; &nbsp; Wellhead pressure : 39.2 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Flow line pressure : 33.8 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Passing rate test : 5.4 bar. in 30 minute.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Kx valve opening : Valve opened using balance pressure at 90.7 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Well status : Ready to flow.</p><p><br></p><p>- Function test Kx valve BK-S17-D</p><p>&nbsp; Performed blowdown via test separator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Kx valve setting : Nitrogen pressure at 20 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Result : Kx valve remained closed.</p><p>&nbsp; &nbsp; Choke valve position : 75%</p><p>&nbsp; &nbsp; &nbsp; &nbsp; Wellhead pressure : 27.0 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Flow line pressure : 20.8 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Passing rate test : 5.0 bar. in 30 minute.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Kx valve opening : Unable to identify opening pressure.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Well status : Ready to flow.</p><p><br></p><p>- Function test Kx valve BK-S17-J</p><p>&nbsp; Performed flow through production manifold.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Kx valve setting : Nitrogen pressure at 32 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Result : Kx valve remained closed.</p><p>&nbsp; &nbsp; Choke valve position : 55%</p><p>&nbsp; &nbsp; &nbsp; &nbsp; Wellhead pressure : 46.0 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Flow line pressure : 34.3 bar.</p><p>* Wire line team pulled the Kx valve and reduced nitrogen pressure to 20 bar,then reinstalled valve and waited for testing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Well status : Ready to flow.</p><p><br></p><p>&nbsp;Wellhead maintenance Team</p><p>&nbsp; &nbsp;- PM X-mas tree BK-S17-D&nbsp; ( Completed )&nbsp;</p>', NULL, '2025-07-30 20:06:58', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Production-Oper', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WP17-2WH27NPQ.ASY', 'GBS-WP17-2WH27NPQ.ASY', 'WELL 17N/P/Q ASSEMBLY', NULL, NULL, 'WELL 17N/P/Q ASSEMBLY', 'GBS-WP17', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
