  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS G8930 cannot start in weekly test run activity', 'Electrical & Instrument', 'CM', 'In Progress', '2025-08-01', '<p><u><b>Today Activity</b></u></p><p>TS G8930 cannot start in weekly test run activity.</p><p><br></p><p><b><u>Action</u></b></p><p>-Charge battery bank 2 at battery room.</p><p>-Adjust fuel pressure 15kpa to 16 kpa.</p><p>-Test run with battery bank 2 jump start.</p><p>-G8930 can''t start.</p><p><br></p><p><u><b style="background-color: rgb(255, 255, 0);">History (29.July.2025)</b></u></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Today''s Activity</b></u><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Weekly test run gas generator G8930</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Adjust fuel pressure 15Kpa from PCV of G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Test run again G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Generator cranking was over 400 RPM and then tripped by Sd, low oil pressure alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Restart gas generator again.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Generator cranked PRM cannot reach over 150 RPM.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Changed battery bank and start again. (Failed)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Next day, we will recharge battery at maintenance battery room.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Performed test run by manual.</span></p><p><span style="background-color: rgb(255, 255, 0);">- G8930 can''t start with under speed alarm at the first time.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Second time, start G8930. (around 150 RPM).</span></p><p><span style="background-color: rgb(255, 255, 0);">- Can''t start in cranking state.</span></p><p><span style="background-color: rgb(255, 255, 0);">-To be troubleshoot after PTW.</span></p>', NULL, '2025-08-01 19:11:42', '2025-08-05 07:08:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930', 'ATL-OC-G-8930', 'Gen, Generator ZOC Gas Gen 3', NULL, NULL, 'Gen, Generator ZOC Gas Gen 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-08-01 19:11:42', '2025-08-05 07:08:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Win Ko Gyi', NULL, 'EXTERNAL', '2025-08-01 19:11:42', '2025-08-05 07:08:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2025-08-01 19:11:42', '2025-08-05 07:08:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
