-- Inserting report ID 34801
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TEK-3200 HVAC unable to start.', 'Electrical', 'CM', 'Complete', '2025-08-01', '<p data-start="192" data-end="223"><b>T/S TEK-3200 HVAC unable to start.</b></p><p data-start="192" data-end="223"><strong data-start="192" data-end="223">Findings and Actions Taken:</strong></p><ul data-start="225" data-end="1043"> <li data-start="225" data-end="309"> <p data-start="227" data-end="309">&nbsp;- Identified ice build-up blocking the evaporator coil, preventing normal operation.</p> </li> <li data-start="310" data-end="361"> <p data-start="312" data-end="361">&nbsp;- Operated fan-only mode to facilitate ice melting.</p> </li> <li data-start="362" data-end="434"> <p data-start="364" data-end="434">&nbsp;- Adjusted thermostat setting from 23°C to 25°C to prevent future icing.</p> </li> <li data-start="435" data-end="712"> <p data-start="437" data-end="487">&nbsp;- Restarted the system and monitored key parameters:</p> <ul data-start="490" data-end="712"> <li data-start="490" data-end="516"> <p data-start="492" data-end="516">&nbsp; &nbsp;AHU fan current: 0.5 A, Compressor current: 8.2 A</p></li> <li data-start="551" data-end="581"> <p data-start="553" data-end="581">&nbsp; &nbsp;Discharge pressure: 19 bar, Suction pressure: 3.4 bar</p></li> <li data-start="616" data-end="664"> <p data-start="618" data-end="664">&nbsp; &nbsp;Compressor start at room temperature: 26.5°C, stop at room temperature: 23.5°C</p></li> </ul> </li> <li data-start="713" data-end="953"> <p data-start="715" data-end="777"><b>Conducted thermal inspection using IR camera on control panel:</b></p> <ul data-start="780" data-end="953"> <li data-start="780" data-end="840"> <p data-start="782" data-end="840">&nbsp;- All components operating within normal temperature range</p> </li> <li data-start="843" data-end="881"> <p data-start="845" data-end="881">&nbsp;- Maximum observed temperature: 68°C</p> </li> <li data-start="884" data-end="953"> <p data-start="886" data-end="953">&nbsp;- Verified no signs of overheating or damage to contactors and cables</p> </li> </ul> </li> <li data-start="954" data-end="1043"> <p data-start="956" data-end="1043"><b>Performed test run on Unit B; unit did not operate due to high-pressure alarm shutdown.</b></p> </li> </ul><p>  </p><p data-start="1045" data-end="1238"><strong data-start="1045" data-end="1060">Conclusion:</strong><br data-start="1060" data-end="1063">&nbsp;- System A was successfully restored to normal operation after ice removal and thermostat adjustment.</p><p data-start="1045" data-end="1238">&nbsp;- Unit B requires further to be reinstalled condensing fan motor.</p>', NULL, '2025-08-01 19:38:13', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TEK-3200-HVAC', 'GBN-TEK-3200-HVAC', 'HVAC, TRAIN 1', NULL, NULL, 'HVAC, TRAIN 1', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anuphan', NULL, 'EXTERNAL', '2025-08-01 19:38:13', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kittipong', NULL, 'EXTERNAL', '2025-08-01 19:38:13', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL);
