  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Wiwat', NULL, 'EXTERNAL', '2025-08-02 17:48:17', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL);
