BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-1 Firedrying After Crankwashing_Eng-chgout', 'Turbine E&I', 'PM', 'Completed', '2025-08-02', '<div>TG-1 Engine changeout activities</div><div>&nbsp;- Support Engine crank soak washing and fire drying.</div><div>&nbsp;- Get ready for the ADRE vibration monitoring data recording.</div><div>&nbsp;- Regarding to this 1st start-up and firing. All units running signs, such as Engine and driven generator, were running smoothly without any abnormal conditions. As well, no LOPC was found during an internal inspection that was conducted during the Unit Idle running without loading.</div><div>&nbsp;- The unit was normally stopped with slowdown and slow roll as a normal sequence.</div><div><br></div><div>ADRE observation</div><div>&nbsp;- @ 19.2 % NGP : The actual speed sensor reading is 2904&nbsp; &nbsp;rpm ( Engine Purge Crank)</div><div>&nbsp;- @ 100 %&nbsp; NGP : The actual speed sensor reading is 15147 rpm ( Idle running)</div><div>&nbsp;- @&nbsp; 9.2%&nbsp; &nbsp;NGP : The actual speed sensor reading is 1390&nbsp; &nbsp;rpm. ( Engine slow roll)&nbsp;</div>', 'The TG-1 will conduct the new Engine Endurance test after the first starting (Engine change out)', '2025-08-02 20:09:24', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
