  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot solar CCTV failure issue at KP30+300 ', 'Electrical & Instrument', 'OTH', 'Completed', '2025-08-03', '<h3 class="modal-title displayform"><p><u>Today Activity</u></p><p>Troubleshoot solar CCTV failure issue at KP30+300&nbsp;</p><p><br></p><p><u>Action</u>&nbsp;</p><p>- ICT informed EI team that over voltage protector was defected.</p><p>- Open permit and go to check defective equipment at KP-30+300</p><p>- Found no output voltage on over voltage protector. (0 VAC)</p><p>- Checked other equipment condition. (Normal)</p><p>- Replaced new device for over voltage protector.</p><p>- Then, measured output voltage. (220 VAC)</p><p>- But, voltage protector was tripped again.</p><p>- When we checked output cables'' (L-N) continuity, found 0.0 Ohm.</p><p>- Inform ICT team to check CCTV equipment.</p><p>- Now, disconnect cable of CCTV power supply.</p><p>- Service back for ventilation fans.</p><p><br></p></h3>', NULL, '2025-08-03 17:43:33', '2025-08-11 19:21:28', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Se-EI', false, 'ATL') RETURNING id INTO new_report_id;
