BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S G-8930 unable to start up', 'Mechanic', 'CM', 'Under Monitoring', '2025-06-30', '<p><b>Job Description : G-8930 Unable to start up Mechanical Side T/S steps</b></p><p><b><br></b></p><p><b>- Removed all spark plugs and replaced with new ones.</b></p>  <p><b>- Cleaned all ignition connections with contact cleaner and inspected.</b></p>  <p><b>- Removed air filters and checked the air inlet lines. (Found no traces of lube oil inside the air inlet, G-8925 found oil traces)</b></p>  <p><b>- Removed the breather housing and checked the breather filter. Found clean.</b></p>  <p><b>- Removed speed sensor from both bank A and B. Adjusted to ½ turn gap as per instruction.</b></p>  <p><b>- Removed timing sensor and adjusted to 1 turn gap.</b></p>  <p><b>- Replace the dog house fuel filter with a new one.</b></p>  <p><b>- Checked the lube oil pressure sensor with EI team and found one of the sensors has abnormal ohms. (Replaced with a new one)</b></p>  <p><b>- 1-July-25 Fabricated a new connection for lube oil pressure sensor line and installed.</b></p>  <b>- Test ran with load sharing and under monitoring.&nbsp;</b>', NULL, '2025-08-04 16:38:55', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930-PACK', 'ATL-OC-G-8930-PACK', 'Gen, ZOC Gas Generator Package 3', NULL, NULL, 'Gen, ZOC Gas Generator Package 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2025-08-04 16:38:55', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
END $$;

