  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'MPM on two post car lift', 'Mechanic', 'PM', 'Completed', '2025-08-04', '<p>Performed monthly PM for two post car lift</p><p><br></p><p>Action:&nbsp;</p><p>-Performed electrical isolation by emergency stop button.&nbsp;</p><p>-Checked two post mounting bolts tightness. (Torque 100 N-m)<br></p><p>-Checked cylinders (primary and secondary) for any leakage.<br></p><p>-Checked hydraulic hoses if any damage and leakage.<br></p><p>-Checked wiring sling rope condition and greasing.<br></p><p>-Checked mechanical locks and limit switch functional test.<br></p><p>-Checked arm gear if any corrosion and damage.<br></p><p>-Test without load and check if any abnormal noise and condition.</p>', NULL, '2025-08-04 16:48:28', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
