  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai', NULL, 'EXTERNAL', '2025-08-04 17:29:58', '2025-08-05 06:48:27', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mongkol', NULL, 'EXTERNAL', '2025-08-04 17:29:58', '2025-08-05 06:48:27', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
