-- Inserting report ID 34986
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S FT-3300 no reading to DCS', 'Turbine', 'CM', 'Complete', '2025-08-04', '<div>Verify FT-3300 no reading displayed on DCS.</div><div>- Investigation revealed water ingress inside the Exd box, which caused damage to the frequency isolator.</div><div>- Removed moisture and contaminants inside Exd box.</div><div>- Clearing and inspecting the flame path surface.</div><div>- Applied flame path Modicote to ensure proper sealing and protection.</div><div>- Replaced and the damaged frequency isolator with a new spare and reconfiguration.</div><div>- Confirmed that the DCS reading resumed and is now functioning correctly.</div><div><br></div><div>Configuration method for frequency isolator.</div><div><br></div><div>New flow meter Cert. value = 609.298 pulse/m3 , flow rate span : 400 m3/h</div><div><div>	Upper range	= 609.298*400/3600 = <span style="background-color: rgb(255, 255, 0);">67.70 Hz</span></div><div><br></div><div>New converter : model KFD2-UFC-1.D&nbsp; &nbsp; ;Item# 60.05.31.103.3</div><div>	</div><div><br></div><div>Set configure	= press OK + ESC ,1 second</div><div>		Unit = Hz</div><div>		Input = Line Monitor</div><div>		Output &gt; Iout &gt; characteristic = 4 – 20 mA</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &gt; Fault = Down</div><div>			&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &gt;&nbsp;Stat value = 0 Hz</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&gt; End value = 67.70 Hz		;<span style="background-color: rgb(255, 255, 0);">Upper range (Value from Calculated)</span></div><div>			&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &gt;&nbsp;Inverted = Normal</div><div><br></div><div>Wiring Terminal </div><div>	1 = + I/P</div><div>3 = - I/P</div><div>7 = - mA</div><div>8 = + mA</div><div>23 = Power supply +24v</div><div>24 = Power supply&nbsp; 0 v</div></div>', NULL, '2025-08-04 18:29:49', '2025-08-04 18:30:48', 'PTTEP\\Turbine', 'PTTEP\\Turbine', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-FT-3300', 'GBN-FT-3300', 'FLOW TRANSMITTER', NULL, NULL, 'FLOW TRANSMITTER', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anuchit P.', NULL, 'EXTERNAL', '2025-08-04 18:29:49', '2025-08-04 18:30:48', 'PTTEP\\Turbine', 'PTTEP\\Turbine');
END $$;

