-- Inserting report ID 35037
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS G8930 cannot start in weekly test run activity', 'Electrical & Instrument', 'CM', 'Completed', '2025-08-05', '<p><b><u>Today Activity</u></b></p><p>Continue troubleshoot G8930 can''t start in weekly test run activity. (<span style="background-color: rgb(0, 255, 0);">Engine can starting back.)</span></p><p><br></p><p><b><u>Action</u></b></p><p>-Dismantled, clean, adjust fuel regulator at doghouse. (15 Kpa)</p><p>-Check and cranking RPM pick up by using borescope.&nbsp; (Half turn)</p><p>-Check and verify timing sensor.</p><p>-Found that sensor was dirty with lube oil.</p><p>-Clean timing sensor and timing dish.</p><p>-Test run G8930. (Run properly/No abnormality are found)&nbsp;</p><p>-Run with load shared for 1 hour. (completed)</p><p><br></p><p><u><b style="background-color: rgb(255, 255, 0);">History (04.08.2025)</b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">Today Activity</b></u></p><p><span style="background-color: rgb(255, 255, 0);">-TS G8930 cannot start in weekly test run activity.</span></p><p><b style="background-color: rgb(255, 255, 0);"><br></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Checked starter motor condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Replaced lube oil pressure switch S5 with new one.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Connected AFR and ignition control through laptop.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Connected digital pressure gauge at GPVS down stream.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Test run G8930. (Can''t start/ show lube oil pressure fault in first start).</span></p><p><span style="background-color: rgb(255, 255, 0);">-To be continued in next day.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">History (02.08.2025)</b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">Today Activity</b></u></p><p><span style="background-color: rgb(255, 255, 0);">TS G8930 cannot start in weekly test run activity</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Connect G8930 AFR through laptop to monitor ignition and RPM status.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Adjust fuel flow 15 to 19 Kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Install charged battery bank 1.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Test run G8930. (Can''t start, stop with start fail alarm)</span></p><p><u><b style="background-color: rgb(255, 255, 0);"><br></b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">History (02/08/2025)</b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">Today Activity</b></u></p><p><span style="background-color: rgb(255, 255, 0);">TS G8930 cannot start in weekly test run activity.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Charge battery bank 2 at battery room.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Adjust fuel pressure 15kpa to 16 kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Test run G8930</span></p><p><span style="background-color: rgb(255, 255, 0);">-G8930 can''t start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">History (29.July.2025)</b></u></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Today''s Activity</b></u><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Weekly test run gas generator G8930</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Adjust fuel pressure 15Kpa from PCV of G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Test run again G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Generator cranking was over 400 RPM and then tripped by Sd, low oil pressure alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Restart gas generator again.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Generator cranked PRM cannot reach over 150 RPM.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Changed battery bank and start again. (Failed)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Next day, we will recharge battery at maintenance battery room.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Performed test run by manual.</span></p><p><span style="background-color: rgb(255, 255, 0);">- G8930 can''t start with under speed alarm at the first time.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Second time, start G8930. (around 150 RPM).</span></p><p><span style="background-color: rgb(255, 255, 0);">- Can''t start in cranking state.</span></p><p><span style="background-color: rgb(255, 255, 0);">-To be troubleshoot after PTW.</span></p>', NULL, '2025-08-05 17:38:02', '2025-08-05 18:34:23', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.MaintSup', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930', 'ATL-OC-G-8930', 'Gen, Generator ZOC Gas Gen 3', NULL, NULL, 'Gen, Generator ZOC Gas Gen 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-08-05 17:38:02', '2025-08-05 18:34:23', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.MaintSup');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Win Ko Gyi', NULL, 'EXTERNAL', '2025-08-05 17:38:02', '2025-08-05 18:34:23', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.MaintSup');
