BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'SPP : HVAC X-8630B unable to start.', 'Electrical', 'CM', 'Complete', '2025-08-06', '<p>SPP : HVAC X-8630B unable to start.</p><p data-start="109" data-end="122"><strong data-start="109" data-end="122">Findings:</strong></p><ol data-start="124" data-end="689"> <li data-start="124" data-end="474"> <p data-start="127" data-end="159"><strong data-start="127" data-end="159">Alarm: COMP.B1 GENERAL ALARM</strong></p> <ul data-start="163" data-end="474"> <li data-start="163" data-end="244"> <p data-start="165" data-end="244">&nbsp;- HMI displayed abnormal value for <span data-start="198" data-end="225">Differential Oil Pressure</span> at <strong data-start="229" data-end="243">6553.5 bar</strong>.</p> </li> <li data-start="248" data-end="402"> <p data-start="250" data-end="402">&nbsp;- Performed troubleshooting by swapping the pressure sensor and performing a hard reset on the power supply to the safety barrier for COMP.B1 and COMP.B2.</p> </li> <li data-start="406" data-end="474"> <p data-start="408" data-end="474"><strong data-start="408" data-end="419">Result:</strong> Alarm was cleared after reset and sensor verification. the value 0.0 bar before running.</p> </li> </ul> </li> <li data-start="476" data-end="689"> <p data-start="479" data-end="533"><strong data-start="479" data-end="533">Alarm: FSL-8630B – Chilling Cooling Water Flow Low</strong></p> <ul data-start="537" data-end="689"> <li data-start="537" data-end="616"> <p data-start="539" data-end="616">&nbsp;- Checked flow switch FSL-8630B and verified input signal status at remote I/O.</p> </li> <li data-start="620" data-end="689"> <p data-start="622" data-end="689">&nbsp;- Status alternated between <strong data-start="648" data-end="659">1 and 0</strong>, confirming normal operation.</p> </li> </ul> </li> </ol><p data-start="691" data-end="708"><strong data-start="691" data-end="708">Action Taken:</strong></p><ul data-start="709" data-end="756"> <li data-start="709" data-end="756"> <p data-start="711" data-end="756">Restarted the system and monitored operation.</p> </li> </ul><p data-start="758" data-end="769"><strong data-start="758" data-end="769">Result:</strong></p><p>     </p><ul data-start="770" data-end="803"> <li data-start="770" data-end="803"> <p data-start="772" data-end="803">System is now running normally. Unit B running in AUTO mode.</p></li></ul>', NULL, '2025-08-06 17:04:18', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.EI-Workshop', NULL, false, 'G2N') RETURNING id INTO new_report_id;
