-- Inserting report ID 35117
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove PL-3721 to AWP-38', 'Mechanic', 'OTH', 'Completed', '2025-08-04', '<p>Failure cause: AWP-38 request to piging operation.</p><p><br></p><p><u><b>On 4 August 2025.</b></u></p><p><br></p><p>1. Remove support, beam structure and grating floor.</p><p>&nbsp; &nbsp; - Wrench 10, 34, 36 mm.</p><p>2. Remove PL-3721 to AWP-38.</p><p>&nbsp; &nbsp; - Install blind flange 12"# 600 and SPW gasket 12"# 600 = 1 ea. (Wrench# 50 mm. or 2")</p><p>&nbsp; &nbsp; - Install bling flange&nbsp; 4''# 600 and SPW gaslet 4" # 600 = 1 ea. (Wrench# 36 m or 1-1/2")</p><p>&nbsp; &nbsp; - Install blind flange&nbsp; 2"# 600 = 2 ea. and SPW gasket 2''# 600 = 2 ea. (Wrench# 27 mm., or 1-1/16")</p><p><br></p><p><u><b>On 5 August 2025.</b></u></p><p><br></p><p>3. Apply JIMS.</p><p>&nbsp; &nbsp; -&nbsp; Blind flange 12"# 600 = 660 ft.lb.</p><p>&nbsp; &nbsp; -&nbsp; Blind flange 4"# 600 = 240 ft.lb.</p><p>&nbsp; &nbsp; -&nbsp; Blind flange 2"# 600 = 86 ft.lb.</p><p>4. Housekeeping and pressure leak test at 30 barg., not found any leak.</p>', 'Pipe spool for balancing line keep at site location with stud bolt.', '2025-08-08 16:48:12', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP37-1PL-3721.PK', 'ART-WP37-1PL-3721.PK', 'ART WP37 MOBILE PIG LUNCHER PACKAGE', NULL, NULL, 'ART WP37 MOBILE PIG LUNCHER PACKAGE', 'ART-WP37', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pawaris', NULL, 'EXTERNAL', '2025-08-08 16:48:12', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Phum', NULL, 'EXTERNAL', '2025-08-08 16:48:12', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thavit', NULL, 'EXTERNAL', '2025-08-08 16:48:12', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL);
