  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Life boat sea trial.', 'Mechanic', 'PM', 'Completed', '2025-08-08', '<p>Sea trial test life boat #2, 3.</p><p><br></p><p>Life boat# 2.</p><p>1. Pre-check and preparation life boat for sea trial.</p><p>2. Perform lowering and brake test, found function normally.</p><p>3. Perform start test by main battery and emergenct battery, found function normally.</p><p>4. Perform test lighting, found function normally.</p><p>5. Perform deluge spray water, found function normally.</p><p>6. Perform speed test, found 7.9 knots.</p><p>7. Perform recovery life boat.</p><p>8. Cleaning and housekeeping.</p><p><br></p><p>Life boat# 3.</p><p>1. Pre-check and preparation life boat for sea trial.</p><p>2. Perform lowering and brake test, found function normally.</p><p>3. Perform start test by main battery and emergenct battery, found function normally.</p><p>4. Perform test lighting, found function normally.</p><p>5. Perform deluge spray water, found function normally.</p><p>6. Perform speed test, found 10.0 knots.</p><p>7. Perform recovery life boat.</p><p>8. Cleaning and housekeeping.</p>', '<p>Lifeboat# 2</p><p>1. Pawaris (Coxswain)<br>2. Suthus, Thavit (Helper)</p><p>3. Wara (Safety, Observer)</p><p>4. 2 EI Tech (Assist helper)</p><p>5. Prapon (Commander)</p><p>6. Chalermpong, Nattachai (Assist commander)</p><p><br></p><p>Lifeboat# 3</p><p>1. Thavit (Coxswain)<br>2. Suthus, Pawaris (Helper)</p><p>3. Wara (Safety, Observer)</p><p>4. 2 EI Tech (Assist helper)</p><p>5. Prapon (Commander)</p><p>6. Chalermpong, Nattachai (Assist commander)</p>', '2025-08-08 18:26:53', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL, false, 'ART') RETURNING id INTO new_report_id;
