-- Inserting report ID 35156
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'P-6220 engine top part overhaul', 'Mechanic', 'PM', 'In Progress', '2025-08-08', '<p>P-6220 engine top part overhaul.</p><p>8 Aug 2025&nbsp;</p><p>- Tested run engine 30 Minute and keep monitor engine parameter.</p><p>- Checked spare part and prepare tool.</p><p>- Prepare work area, erect scaffold, install temporary fan blower and portable sport light.</p><p>- Removed piping assembly.</p><p>9 Aug 2025&nbsp;</p><p>- Remove valve accessory.</p><p>- Remove turbocharger and exhaust manifold.</p><p>10 Aug 2025</p><p>- Remove cylinder head left and right side.</p><p>- Clean cylinders and did cylinder liner inspection.</p><p>- Found deep mark on piston head No,3,5,7 and 8 after checked with history report in year 2010 found there are old mark, and the mark still remain same size.</p><p>- Install new cylinder head on left bank.</p><p>- Install refurbished cylinder head on right bank.</p>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Department_Share/02-PBN-M/03%20MM/06.%20Pictures/02%20-%20QP%20Resize/Fire%20Water%20Pump/DEP%206220/2025/2025_08_08_P%206220%20engine%20top%20part%20overhaul?csf=1&amp;web=1&amp;e=ziH668">2025_08_08_P 6220 engine top part overhaul</a>', '2025-08-10 21:19:48', '2025-08-10 21:24:50', 'PTTEP\\Bongkot.Valve', 'PTTEP\\Bongkot.Valve', false, 'G2N') RETURNING id INTO new_report_id;
