  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12MPM on G-8020 ZBV1', 'Mechanic', 'PM', 'Completed', '2025-08-12', '<div><i><u>Today Activity</u></i></div><div><p>Performed 12M PM Diesel Generator, G-8010.</p><p><br></p><p><u><i>Action</i></u></p><p>- Checked and cleaned the air filter.</p><p>- Checked the air service indicator.</p><p>- Checked the radiator cap condition.</p><p>- Checked the coolant level and its condition.</p><p>- Drained Lube oil, replaced lube oil filters and top up.</p><p>- Replaced fuel filter with a new one.</p><p>- Checked and adjusted the belt tension and its condition.</p><p>- Checked and tightened the loosening bolts and nuts.</p><p>- Checked the mounting conditions.</p><p>- Checked the radiator fins and leakage.</p><p>- Housekeeping and test run.</p><p>- Recorded the parameters and checked any abnormalities.</p></div>', NULL, '2025-08-12 18:07:27', '2025-08-13 16:26:13', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
