  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2025-08-12 18:07:27', '2025-08-13 16:26:13', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec');
