BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1M PM G8310& G-8320 ZBV2 Diesel Gen Package', 'Electrical & Instrument', 'PM', 'Completed', '2025-08-13', '<p><u><b>Today activity</b></u></p><p>-1MPM G-8310 &amp; G-8320 ZBV2 Diesel Gen Package.</p><p><u><b>Action</b></u></p><p><u>G-8310</u></p><p>-Open Junction boxes for cleaning and re-tighten wiring termination, corrosion, clean terminals.<br>-Check the AVR connection at AVR box.</p><p>-Check and record generator power output.<br>-Replace two battery due to charging inverter trip and low voltage.</p><p></p><p>-Check battery charging system.(13 VDC)</p><p>-Test run, no alarm and working properly.<br></p><p><br><u>G-8320</u></p><p>-Open Junction boxes for cleaning and re-tighten wiring termination, corrosion.</p><p>-Check the AVR connection at AVR box.<br></p><p>-Check battery charging system.&nbsp;</p><p>-Found low voltage and still charging due to charging inventor was tripped.</p><p>-Replace two battery due to charging inverter trip and low voltage.</p><p>-Test run, no alarm and working properly.</p>', NULL, '2025-08-13 15:28:15', '2025-08-13 16:04:18', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
