  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay Lin', NULL, 'EXTERNAL', '2025-08-13 15:28:15', '2025-08-13 16:04:18', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
