  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nobel', NULL, 'EXTERNAL', '2025-08-13 16:02:16', '2025-08-13 16:02:48', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay Lin', NULL, 'EXTERNAL', '2025-08-13 16:02:16', '2025-08-13 16:02:48', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
