-- Inserting report ID 35194
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify and Troubleshoot ZBV 1 UPS system Day-3', 'Electrical & Instrument', 'CM', 'In Progress', '2025-08-16', '<p><b><u>Today Activity</u></b></p><p>Verify and Troubleshoot ZBV 1 UPS system Day-3</p><p><br></p><p><b><u>Finding</u></b></p><p>Rectifier doesn''t work.(0VDC).</p><p>DC MCCB have 24 VDC due to after solar reverse voltage after PMO/E modification (No blocking diode)&nbsp;</p><p><br></p><p><b><u>Action</u></b></p><p>Action</p><p>-Test run G8010 with manual mode.</p><p>-Found that ZBV1 DC UPS Gutor panel ; No Output 24 VDC and No display light.</p><p>-Measure Input and output MCCBs. (AC= 440 VAC, DC= 24VCDC).</p><p>-Check Transformer T05 (Input=440VDC, Output= 230.3VDC).</p><p>-Tx Input= 401.2 VAC, output1=31.7 VAC, output2= 0 VAC. (Transformer T001)</p><p>-Found Rectifier Unit&nbsp; is not working and generate 24 VDC.</p><p>-Plan to replace spare at next day. (in progress)</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity (27July2025)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify and Troubleshoot ZBV 1 UPS system. (No DC output)</span></p><p><b style="background-color: rgb(255, 255, 0);"><br></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Root cause&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Main transformer output1 and output2 have only 31.7 VAC and 0VAC instead of 230 VAC.</span></p><p><b style="background-color: rgb(255, 255, 0);"><br></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Test Run G-8010 from CCR to verify UPS system voltage checking.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check and measure (2T001) main transformer voltage.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Tx Input= 401.2 VAC, output1=31.7 VAC, output2= 0 VAC.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b style="background-color: rgb(255, 255, 0);">History (25-07-2025)</b></p><p><b style="background-color: rgb(255, 255, 0);">Today Activity</b></p><p><span style="background-color: rgb(255, 255, 0);">-Verify and Troubleshoot ZBV 1 UPS system.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b style="background-color: rgb(255, 255, 0);">Found</b></p><p><span style="background-color: rgb(255, 255, 0);">--Rectifier Unit&nbsp; is not working and generate 24 VDC.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b style="background-color: rgb(255, 255, 0);">Action</b></p><p><span style="background-color: rgb(255, 255, 0);">-Test run G8010 with manual mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found that ZBV1 DC UPS Gutor panel ; No Output 24 VDC and No display light.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Measure Input and output MCCBs. (AC= 440 VAC, DC= 0VCDC).</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check Transformer T05 (Input=440VDC, Output= 230.3VDC).</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check PSU of all control card and display card. (No Voltage)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check capacitors (10.4 uF)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found Rectifier Unit&nbsp; is not working and produce 24 VDC.</span></p><p><br></p><p><br></p>', NULL, '2025-08-16 17:59:15', '2025-09-02 14:00:24', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-DCUPS-8001A', 'ATL-BV1-DCUPS-8001A', 'ZBV1 DCUPS System 8001A', NULL, NULL, 'ZBV1 DCUPS System 8001A', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-DCUPS-8001B', 'ATL-BV1-DCUPS-8001B', 'ZBV1 DCUPS System 8001B', NULL, NULL, 'ZBV1 DCUPS System 8001B', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-08-16 17:59:15', '2025-09-02 14:00:24', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'NL', NULL, 'EXTERNAL', '2025-08-16 17:59:15', '2025-09-02 14:00:24', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
