-- Inserting report ID 35197
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot G-9110 radiator fan motor cable burn', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-08-16', '<p><b><u>Today Activity</u></b></p><p>Troubleshooting Gas Generator G-9110 radiator fan motor one power cable in control circuit.</p><p><br></p><p><b><u>Action Plan</u></b></p><p>1.Remove the damage cable from MCCB and magnetic contactor.</p><p>2.Reinstalled new power cable and proper tighten all wiring at radiator control circuit.</p><p>3.Checked and measured radiator motor winding resistance and insulation resistance value. Result is good</p><p>4.Perform test run the gas generator with load share about 20minutes and checked the condition of radiator fan motor power cable at control circuit. No abnormal found.</p><p>5.Finall put full load to G-9110 and under monitoring.</p>', NULL, '2025-08-16 18:47:05', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
