  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced mechanical seal and bearing NDE P-4510', 'Mechanic', 'CM', 'Completed', '2025-08-12', '<p><u>12-13 /08/2025&nbsp; &nbsp;</u></p><p><b>&nbsp;Verify mechanical seal leak</b></p><p>- Flushing mechanical seal by water. Found water leak at connection Q= Quench, D= Drain&nbsp; Mech seal<b></b></p><p>- Clean buffer liquid tank and heat exchanger - Air cooled. Found sludge.</p><p><u>14-16 /08/2025</u></p><p><b>Replace new mechanical seal and bearing NDE</b></p><p>- Removed guard coupling, mechanical seal piping.<br>- Removed guard fan and fan NDE.<br>- Removed housing bearing NDE.<br>- Removed bearing NDE.<br>- Removed old NDE mechanical seal.</p><p>&nbsp;<i> Remove and inspect inside mech seal found IB seal face has a mark and OB seal not movement.</i><br>- Install a new NDE mechanical seal.</p><p>&nbsp; <i>Test leak mech seal before install at 15 PSI / 30 min not leak.</i><br>- Install new bearing NDE. (Black to Black)</p><p>- Install housing bearing NDE</p><p>- Install fan and guard NDE.<br>- After measurement check shaft End play = 0.02 mm.<br>- After measurement check lift DE bearing = 0.03 mm.<br>- After measurement check lift NDE bearing = 0.03 mm.<br>- Install guard coupling.<br>- Install mechanical seal piping all.<br>- flushing inside pump by water before running pump.</p><p>- Top up Barrier seal port NDE = 75%</p><p>- Top-up Lube oil T46 NDE bearing.<br>- MRT pump after repair found normal.<b></b></p><p><br></p>', NULL, '2025-08-19 16:57:21', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-4510', 'ART-P-4510', 'CLOSED DRAIN MAIN PUMP', NULL, NULL, 'CLOSED DRAIN MAIN PUMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
