-- Inserting report ID 35316
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot PIT-84601C malfunction ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-09-04', '<p>Troubleshoot pressure transmitter PIT-84601C malfunction at HIPPS system</p><p>&nbsp; &nbsp;- Pressure transmitter PIT-84601C malfunction at HIPPS system and pressure value is not shown.</p><p>&nbsp; &nbsp;- Check power supply of PIT-84601C at ITR room, transmitter and junction box</p><p>&nbsp; &nbsp;- Power supply show at ITR room and junction box but not show at transmitter</p><p>&nbsp; &nbsp;- Disconnect cable terminals at junction box and transmitter.</p><p>&nbsp; &nbsp;- Check the pressure transmitter. Transmitter is in good condition.</p><p>&nbsp; &nbsp;- Open cable tray cover and check cable connection between junction box and transmitter.</p><p>&nbsp; &nbsp;- Found mouse bite cable near junction box.</p><p>&nbsp; &nbsp;- Reconnect damage cable, properly wrap with insulation tape and reclose cable tray cover.</p><p>&nbsp; &nbsp;- Apply PU foam at cable tray to prevent mouse entry.</p><p>&nbsp; &nbsp;- Reconnect cable terminals at junction box and transmitter.</p><p>&nbsp; &nbsp;- Power supply is back to transmitter and show the pressure value at transmitter.</p><p>&nbsp; &nbsp;- Check the value with CCR, pressure value show at CCR HMI.</p><p>&nbsp; &nbsp;- Unit is back to normal.</p>', NULL, '2025-09-04 17:33:20', '2025-09-05 18:33:39', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-PIT-84601C', 'ATL-MS-PIT-84601C', 'PT-C on DSTM SDV-84602 HIPPS', NULL, NULL, 'PT-C on DSTM SDV-84602 HIPPS', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Richard', NULL, 'EXTERNAL', '2025-09-04 17:33:20', '2025-09-05 18:33:39', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nicolas and Sea Owl Team', NULL, 'EXTERNAL', '2025-09-04 17:33:20', '2025-09-05 18:33:39', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech');
END $$;

